const banks={options:[],futures1:[]};
let context;
function section(subject,chapter,lessonId,source,referenceSection){context={subject,chapter,lessonId,source,referenceSection};}
function q(topic,stem,raw,expansionCalculation){
 const {subject,...meta}=context,bank=banks[subject],seq=bank.length+1,answer=(seq-1)%4;
 const choices=raw.map(x=>x.split('|'));
 if(choices.length!==4||choices.some(x=>x.length!==2))throw Error(`Malformed authored case: ${topic}`);
 for(let i=0;i<answer;i++)choices.unshift(choices.pop());
 bank.push({id:`${subject}-expansion-deriv-${String(seq).padStart(4,'0')}`,...meta,topic,conceptIds:[topic],type:'single',stem,options:choices.map(x=>x[0]),rationales:choices.map(x=>x[1]),answer,explanation:choices[answer][1],sourceKind:'original',origin:'原创应用决策题 · 非真题',difficulty:expansionCalculation?'advanced':'applied',editorialBatch:EXPANSION_DERIVATIVES_BATCH,reviewedAt:'2026-10-14',reviewNote:(subject==='options'&&seq>=124)?'AI辅助逐题原创；已由另一轮AI内容复核并核对列明原理来源，计算题另行复算。报价、合同和数字为明示教学假设，不代表统一业务规则，不是人类专家审定。':'AI辅助逐题原创；已由另一轮AI内容复核并核对列明原理来源，计算题另行复算。报价、合同和数字为明示教学假设，不代表统一业务规则，不是人类专家审定。',...(expansionCalculation?{expansionCalculation}:{})});
}
