// Batch A: options 0001–0075. Contract identification, implementable prices and risk decisions.
section('options',1,'contracts','expansionDerivCases','案例A1：题设合约识别及报价口径');
q('代码相似但交付标的不同','交易员想买入跟踪同一指数的甲ETF，却选中了乙ETF的认购。两只ETF价格接近，合约均为实物交收。复核员首先应怎样处理？',[
'核对标的代码，换成可交付甲ETF的合约|跟踪同一指数不使两只ETF份额成为同一证券，交收对象必须匹配。',
'只比较行权价，较低的就满足采购目的|便宜不改变交付标的，低行权价也可能对应错误证券。',
'保留乙合约，因为指数相同就可以交付甲|相同指数暴露不等于份额交付权利可替代。',
'将乙合约张数加倍以消除标的差异|扩大数量不会消除合约标的身份差异。']);
q('同名合约的调整标记','订单系统同时列出某ETF标准认购和除权后的调整认购，简称行权价四舍五入后相同。下单前最关键的补充核对是什么？',[
'完整合约代码、精确行权价和实际合约单位|显示简称可能省略精度，调整合约需按实际权利义务识别。',
'只看最近成交价是否相同|成交价格相同不能证明每张交收义务相同。',
'只看两者到期月份|月份相同仍可能存在不同单位和精确行权价。',
'选择成交量大的合约即可免核对|流动性有助执行，却不替代合约身份核验。']);
q('报价低不代表总支出低','甲认购报价0.09元、单位12000份；乙报价0.10元、单位10000份。各买一张且不计费，比较实际权利金支出，哪项正确？',[
'甲比乙多付80元|甲1080元，乙1000元，低每份报价不代表低每张支出。',
'甲比乙少付100元|这错误地给甲也套用10000份单位。',
'甲乙支出相同|忽略了报价和合约单位需要相乘。',
'甲比乙多付2000元|2000是单位差，不是两笔权利金的金额差。'],calc('.09*12000-.10*10000',80,'元'));
q('每份价格与现金行权价值','题设一张现金结算认沽单位5000，行权价2.80，结算参考价2.72，原权利金300元。问到期结算款而非净利润，应填多少？',[
'400元|结算款=(2.80−2.72)×5000；原权利金在计算净利润时另扣。',
'100元|这是扣除300元初始成本后的净利润，题目只问结算款。',
'300元|这是历史权利金支出，不是到期结算金额。',
'14000元|这是行权价乘单位，现金差额结算不支付全额名义本金。'],calc('(2.8-2.72)*5000',400,'元'));
q('日历日与交易日倒计时','估值表写明期限按365天自然日年化；周五收盘至下周一收盘无节假日。录入期限减少量时怎样处理？',[
'减少3个自然日对应的年数|口径已规定自然日，周末也计入剩余期限缩短。',
'减少1个自然日，因为只有一个交易间隔|从周五到周一经过三个自然日，不能只数一个交易日间隔。',
'减少2个自然日，周一不计|从周五同一时刻到周一同一时刻经过三天。',
'期限不变，只有行权日才减少|到期时间随着时钟推进减少，不只在行权日更新。']);
section('options',1,'lifecycle','expansionDerivCases','案例A2：题设委托、成交及交收条件');
q('撤单回报前的重复下单','客户买入5张的订单尚未收到撤单成功回报，就按相同方向再买5张。原订单随后也成交。此时最直接的风险是什么？',[
'总持仓可能达到10张，超过原计划|发送撤单请求不等于撤单成功，原订单仍可能成交。',
'原订单成交会自动冲销新订单|两个买单都增加多头，不会相互抵销。',
'后发订单会自动替代先发订单|未设定替改单机制时，独立新订单不会自动替换旧单。',
'系统必然将两笔都撤销|不能假设交易系统会替客户识别并撤销重复意图。']);
q('部分成交后的剩余委托','计划买8张认购，已成交3张，客户决定总量改为5张。若先撤原剩余委托且确认成功，新的买单应报多少？',[
'2张|目标总量5张减去已成交3张，只需再买2张。',
'5张|忽略已成交3张，最终会买到8张。',
'3张|3张是此前已经取得的数量，距离5张目标尚差2张。',
'8张|这会重新执行完整原计划而不是调整目标。'],calc('5-3',2,'张'));
q('部分指派后的义务状态核对','题设客户原有4张美式认购空头，1张已不可撤销地完成指派、进入证券交收，另外3张仍可交易。客户此时买入平仓3张，哪项记录正确？',[
'交易空头归零，但已指派的1张交收义务仍需完成|交易持仓与已确定待交收义务是不同状态，平掉剩余合约不能撤销此前指派。',
'四张义务均消失，无须准备证券|买平只结束仍存续的3张交易合约，不追溯取消已经确定的交收。',
'仍有4张可交易空头，因为交收尚未完成|已指派1张转入交收，其余3张已平，不能继续按原4张计可交易持仓。',
'应再买平1张才能取消已确定交收|已进入不可撤销交收的义务不能用新买一张期权自动取消。']);

q('市价单穿透盘口','某认购卖一0.12元有2张、卖二0.14元有3张。题设市价买5张恰按该盘口成交，单位10000份，不计费。总权利金为多少？',[
'6600元|2×0.12×10000+3×0.14×10000=6600元，不能全按卖一计。',
'6000元|假设5张均按仅有2张深度的卖一成交。',
'7000元|将全部5张按卖二计，遗漏前2张较低成交价。',
'1300元|简单均价未按张数加权且漏乘总数量。'],calc('(2*.12+3*.14)*10000',6600,'元'));
q('净支付为负的组合限价','题设组合报价定义为买入腿支出减卖出腿收入，允许负数；投资者仅接受开仓净收入至少0.02元/份。其最高可接受净支付限价应设多少？',[
'−0.02元/份|净收入0.02对应净支付−0.02；支付数越小，收入越多。',
'+0.02元/份|正值允许净付0.02，已不符合至少收取0.02的条件。',
'0元/份|零价允许无收入成交，不能保证至少收取0.02。',
'−0.02元必须视作无效报价|题设明确组合报价允许负值，不能把单腿非负价格规则直接套来。'],calc('-.02',-.02,'元/份最高净支付'));

q('行权状态流水的重复计数','客户原有2张认购多头，已有效行权1张并转入待收10000份ETF，仍有1张未行权。系统却同时报告2张可交易期权和10000份待收ETF，首要对账修正是什么？',[
'将可交易期权改为1张，单列已行权形成的待收证券|同一权利从期权转为交收请求，不能同时保留为可交易期权资产。',
'删除待收ETF，因为证券尚未到账就不存在请求权|未到账不表示交收请求不存在，应正确反映状态及风险。',
'保留2张期权并把待收ETF记为额外收益|这是同一权利转换的重复确认，并非新创造资产。',
'将未行权的另一张也自动记为已行权|对账不能替客户补作未发出的行权决定。']);

q('现金结算不产生证券所有权','题设某指数认购为现金差额结算，投资者计划用行权取得指数全部成分股。应如何修正计划？',[
"结算后另行买入所需成分股，行权本身只产生现金差额|现金结算合同没有交付成分股的义务，获得证券还需另行执行相应证券交易。",
"先提交行权，再凭结算通知按指数权重直接申领成分股|结算通知确认现金请求，不会转化为按指数权重领取证券的凭证。",
"补足全额行权本金，即可把现金差额交收改为实物交收|准备更多资金不产生合同未授予的实物交收选择，仍应按原现金条款处理。",
"将行权量按成分股权重拆分，由清算机构分别交付证券|拆分现金结算张数不改变交付对象，不能由数量分配推导证券交付义务。"]);
q('权利到期与服务申请期限','题设经营机构的协议行权服务须提前登记，客户未登记且过了服务截止时点，但交易所手动行权时段尚未结束。应首先核实什么？',[
'手动行权权限、申报截止时间及钱券准备|服务申请期限与交易所行权期限不同，应确认仍可用的合法操作路径。',
'是否可把未登记服务视为已经自动生效|没有登记不能推定服务自动建立。',
'是否可以等到次日补办当日行权|过期权利通常不能靠次日补办恢复，题设未给例外。',
'能否只发邮件就代替系统有效申报|沟通邮件不必然构成经营机构认可的有效行权指令。']);
section('options',1,'value','expansionDerivCases','案例A3：独立构造的价值分解及可执行报价');
q('整笔订单执行缺口的基准','经理决定买4张时可执行参考价为0.20元/份，实际2张成交0.21、2张成交0.24，每张10000份，全单费用20元。仅按题设定义，以决策价为基准的执行成本是多少？',[
'1020元|价格成本=[2×(0.21−0.20)+2×(0.24−0.20)]×10000=1000，再加全单费20。',
'1000元|价格偏离计算正确，但漏掉题设要求计入的全单费用20元。',
'2020元|将价格差重复计算了一次，四张订单的价格成本总计1000元。',
'20元|仅算显性费用，遗漏实际成交价偏离决策基准的隐性成本。'],calc('(2*(.21-.20)+2*(.24-.20))*10000+20',1020,'元'));

q('内在价值不等于退出收益','认购行权价3元，标的3.20元，可成交卖出价0.27元；原买价0.30元，忽略费用。客户称实值0.20元所以卖出盈利0.20元，正确修正是？',[
"卖出净亏0.03元，内在价值为0.20元|平仓损益为0.27−0.30，内在价值是3.20−3.00；两项口径不能相互替代。",
"卖出净亏0.10元，内在价值为0.20元|用内在价值0.20代替当前可成交价格0.27，遗漏了退出时仍能收到的时间价值。",
"卖出净赚0.20元，内在价值为0.20元|实值部分没有扣除原权利金，也不是按可成交卖价计算的实际退出净额。",
"卖出净赚0.27元，内在价值为0.20元|0.27是卖出收入，净利润还须扣除原买价0.30，不能把毛收入视为盈利。"],calc('.27-.30',-.03,'元/份'));
q('负时间价值报价的核验顺序','屏幕显示某可立即行权的认购价格低于内在价值，标的和期权时间戳却相差20分钟。研究员拟宣布无风险套利，首先应做什么？',[
'核对同一时刻可成交报价、深度与完整费用|异步和陈旧报价可能制造不存在的价差，先证实可执行性。',
'直接用两个最新显示数证明已锁利|各自最新不代表相同时点，更不保证同时成交。',
'只增加下单规模以提高套利利润|未经核验放大头寸会放大执行风险。',
'认为任何低于内在价值的屏幕报价都不能出现|数据延迟和市场摩擦可能造成显示偏差，需要核查而非武断排除。']);
q('权利金与最大可承受亏损预算','账户只愿在一笔纯买入期权交易中损失最多2500元，题设每张权利金800元且每张开平双边合计费用20元，按全部成本预算应最多买几张？',[
'3张|3×820=2460元，4张需3280元，超过预算。',
'4张|仅凭权利金近似数量向上取整会突破最大预算。',
'2张|两张虽在预算内，但不是满足预算的最大整数张数。',
'按保证金比例算可买更多|普通期权买方支付权利金，不能将未给定卖方保证金杠杆套入。'],calc('Math.floor(2500/(800+20))',3,'张'));
section('options',3,'pricing','expansionDerivParity','Put/Call Parity：匹配条件、现金头寸与交易摩擦；案例A4');
q('非对称融资条件下的平价检验','同标的同执行价同到期欧式期权，交易台借款年息8%、闲置资金只能赚2%，借券也收费。模型用统一2%利率计算微小平价偏离并称一定可套利，首要修正是什么？',[
'分别按实际复制方向核算借贷及借券成本，检验可执行套利区间|无摩擦单利率平价不自动给有非对称融资约束的账户提供净利润。',
'所有方向都用2%，因为这是最低利率|借钱建立某些复制组合实际要付8%，不能按存款利率融资。',
'所有方向都用8%，便可保证理论偏离全部可赚|存款和借款条件不对称，简单替换一个利率仍未处理方向与费用。',
'只要期限匹配就不再需要检查融资|期限匹配是复制条件之一，但不消除资金和借券摩擦。']);

q('复制现货遗漏行权价现金','在零利率、无分红、同到期同执行价K的欧式合约中，团队买认购卖认沽后声称到期价值等于S。遗漏了什么？',[
'需要再持有到期支付K的现金资产|买认购卖认沽到期为S−K，加K现金才等于S。',
'需要再卖一份现货|再卖现货会抵销S部分，得到固定负K而非复制多头现货。',
'需要加一份认购权利金现金，金额必为K|权利金一般不等于行权价，不能替代K现金。',
'不需补充，S−K和S只是两种报价方式|两者相差实际现金K，不是可忽略的记账格式。']);
q('折现行权价的符号','无分红欧式期权有C−P=S−PV(K)。其他量相同，利率上升使PV(K)下降。仅按此关系，C−P如何变化？',[
'上升|右侧减去更小的PV(K)，故认购减认沽的理论差扩大。',
'下降|右侧是现货减折现值，折现值下降会使差额上升而非下降。',
'保持不变，利率只影响债券|复制关系包含到期现金资产，利率会影响其当前价格。',
'无法判断，因为认购和认沽总会同幅上涨|总会同幅上涨的说法不符合题设平价约束。']);
q('除息现值不能重复扣除','模型明确使用现货S、到期前已知分红现值D和行权价现值B。已按C−P=S−D−B计算后又在认购值中减D，问题是什么？',[
'同一分红影响被重复扣减|分红现值已在复制关系中处理，不应再扣同一项。',
'应该重复扣，因为买方和卖方各有一次分红|期权买卖方并非各自取得一份现货分红。',
'分红从不影响欧式平价|已知分红改变持有现货与现金组合的成本。',
'只有认沽需要再扣一次D|把已包含在平价中的现金流按期权类型重复分配仍错误。']);
q('买卖价差下的套利假象','某组合按中间价理论有每份0.02元收益，但按买入付卖价、卖出收买价后变成−0.01元，另有手续费。应怎样判断？',[
'现有可执行报价不支持正净套利|中间价不是保证可成交价格，执行价已将毛收益变负。',
'仍应交易，因为理论套利只看中间价|可执行价格与费用直接决定实际能否锁定收益。',
'把手续费设为零即可恢复0.02元|未计手续费前已为负，免手续费也不能恢复中间价差。',
'用历史最大买价替换当前买价即可锁利|历史报价不能作为当前确定收入。']);
q('箱式组合的贴现比较','题设无摩擦欧式箱式组合到期确定收10元，期限一年，同期也确定支付10元的零息债价格为9.60元。组合卖价9.90元，何种比较最恰当？',[
'相同现金流应比较9.60元，9.90元并非便宜|到期确定金额需与同期限现金资产比较，不能直接同10元比较。',
'9.90小于10，所以一定比债券便宜|把未来金额直接当现值忽略时间价值。',
'箱式含四条腿，所以合理价值必为4×9.60|腿数不决定组合复制现金流的现值。',
'只要四腿构成价差，融资成本就无关|固定到期现金流依然有资金时间价值。']);
section('options',3,'delta-gamma','expansionDerivDelta','Delta：有符号头寸、局部估计与动态调整；案例A5');
q('按绝对值汇总导致假风险','账户持有认购多头Delta为+6000份，认沽多头为−4000份。风控把绝对值相加称净多头10000份，应改成什么？',[
'净Delta为+2000份，另可保留10000份作为总绝对敞口|净敞口要保留符号；总绝对值有别的用途但不能冒充净值。',
'净Delta为−2000份|两项相加6000−4000=+2000，符号不能颠倒。',
'净Delta为0，因为认购与认沽方向相反|相反方向仍需按大小配对，并非天然等量。',
'净Delta为10000份，Delta不能为负|认沽多头Delta可为负，绝对值不适合净额相加。'],calc('6000-4000',2000,'份'));
q('Delta对冲后标的上涨','多头认购以卖出现货对冲至Delta中性。随后标的小幅上涨、认购Delta增加，其他条件不变。若继续追求中性，通常应如何调整？',[
'再卖出一些现货|期权正Delta增加，需要更多负Delta的现货空头抵销。',
'买回一些现货|这会减少负Delta，使组合新增的正Delta进一步暴露。',
'买入更多认购无需调整现货|这通常增加正Delta而非抵销它。',
'保持原对冲因为初始中性永久有效|Delta随价格变化，初始中性不保证持续中性。']);
q('不同标的Delta不能直接净额','甲ETF认购Delta为+5000甲份，乙ETF认沽Delta为−5000乙份。团队声称组合方向风险严格为零，缺少什么核验？',[
'标的价格、相关性及各自风险因子的映射|单位分别为不同证券份额，不能未经映射直接视为同一风险。',
'只需确认两只ETF名字均含ETF|名称类别不足以建立一比一价格变化关系。',
'只需比较两份Delta绝对数相等|相等份数未考虑证券价格、相关性和跟踪差异。',
'只需把负号删掉就能证明中性|删负号既破坏方向，也不能解决标的不同。']);
q('由双侧重估提取局部Delta','为核对模型，保持期限和隐波不变，将标的从3元分别扰动到2.99及3.01元，期权重估为0.200及0.212元。用两点中心差分估计Delta为多少？',[
'0.6|Delta约为(0.212−0.200)/(3.01−2.99)=0.6，分母是完整双侧距离。',
'1.2|只除单侧0.01而非两次估值之间的0.02，导致扩大一倍。',
'0.012|这只是期权价格变化，还没除以对应标的价格变化。',
'60%一定是期权收益率|0.6是价格敏感度，百分比投资回报还需原期权成本。'],calc('(.212-.200)/(3.01-2.99)',.6,'Delta'));

q('百分比变化与绝对变化','期权Delta=0.6，标的价格10元上涨1%，忽略其他敏感度。期权每份价格变化的一阶估计是多少？',[
'增加0.06元|标的绝对涨幅为10×1%=0.10元，再乘0.6。',
'增加0.60元|标的10元的1%是0.10元，乘Delta后应为0.06元。',
'增加6%|Delta以绝对价格变化定义，期权百分比收益还需其价格。',
'减少0.06元|认购多头正Delta对应标的上涨的正向贡献。'],calc('.6*10*.01',.06,'元/份'));
section('options',3,'delta-gamma','expansionDerivGamma','Gamma：曲率、再平衡和近到期风险；案例A6');
q('同Delta不同Gamma的压力风险','两个组合当前Delta都为零，甲Gamma为正，乙Gamma为负。假设无时间流逝和波动率变化，标的较小幅度双向变动，哪项正确？',[
'二阶近似下甲受益于价格偏移，乙受损|Gamma项为二分之一Gamma乘价格变动平方，方向与Gamma符号相关。',
'两者损益都严格为零|Delta中性只消除一阶项，不消除曲率。',
'只有上涨时甲受益，下跌时必受损|平方项不随小幅变动方向改变符号。',
'Gamma越大越能保证长期盈利|实际还存在时间、波动率、费用及模型误差。']);
q('近到期平值的监测频率','同一标的两只平值认购当前Delta都约0.5，一只明日到期，一只半年后到期，隐波及其他定价条件相同。准备保持Delta对冲，通常应对哪只更警惕频繁再平衡？',[
'明日到期的平值合约|临近到期平值Gamma往往更集中，Delta对小幅价格变化更敏感。',
'半年后到期合约，因为所有长期期权Gamma更高|时间更长不意味着平值Gamma必然更高。',
'两者完全一样，只看当前Delta即可|相同Delta并不意味着相同Delta变化速度。',
'都不用，因为平值Delta总固定为0.5|价格离开平值后Delta会变化，不能固定处理。']);
q('负Gamma再平衡的交易方向','卖出认购并用现货对冲至中性的账户，标的先涨后跌。只看负Gamma引起的Delta再平衡，它通常面临什么交易形态？',[
'上涨补买、下跌再卖，产生追涨杀跌式成本压力|空头Gamma使上涨后更需买入对冲、下跌后减持对冲。',
'上涨卖出、下跌买入，天然保证套利|该方向更对应正Gamma对冲，且仍不能保证扣成本盈利。',
'不发生任何现货调整|Delta会随标的变化，维持中性通常需调整。',
'每次波动都只买不卖|对冲方向随价格路径变化，不是固定只买。']);
q('股票无法消除Gamma','组合Delta=3000、Gamma=800，经理卖3000份现货后写道两项风险均为零。应如何纠正？',[
'现货可消Delta，Gamma仍为800|现货价格函数线性，Gamma为零，不能抵销期权曲率。',
'Gamma也降为零，因为现货张数足够|现货的价格函数是线性的，无论增减多少份都不产生Gamma。',
'Gamma会变成−2200|不能把以不同维度计量的Delta数量直接减Gamma。',
'Delta仍为3000，因为只有期权能对冲期权|同标的现货可抵销一阶价格敏感度。']);
q('局部二阶近似适用范围','风险系统用当前Delta和Gamma估算标的跌50%的情景，没有重新估值。复核最应指出什么？',[
'大幅变动时敏感度会改变，应重估并检查模型边界|局部泰勒近似在大跨度下误差可能显著。',
'二阶公式只允许上涨、不允许下跌|公式可处理正负小幅变化，问题是变动范围。',
'只要加入Gamma就能对任意跌幅精确估值|更高阶项和状态依赖未必可忽略。',
'应该删除Gamma，只用Delta会更精确|删除曲率不解决大幅变动的非线性误差。']);
section('options',3,'theta-vega-rho','expansionDerivVega','Vega：期限分层、波动率曲面与估值输入；案例A7');
q('净Vega为零的期限错配','组合近月Vega为−500、远月为+500，市场只发生近月隐波上升。为何净Vega为零仍可能亏损？',[
'总净值抵销假设了两期限同幅变化，局部冲击不满足|波动率期限结构可非平行变动，需要分桶衡量。',
'净Vega为零说明所有隐波变化都无影响|单一汇总指标不能消除每个期限的独立风险。',
'远月Vega正值必定自动补偿近月任意冲击|题设远月隐波未变，正Vega不会仅凭近月变化自动贡献盈利。',
'Vega只对历史波动率有效|通常Vega描述模型对隐含波动率输入的敏感性。']);
q('事件落在不同到期窗内','公告在六月期权到期后、七月期权到期前。两月波动率有明显差异，研究员认为必是报价错误，应怎样复核？',[
'确认事件风险是否只落入七月剩余期限|不同合约涵盖的未来事件不同，隐波差异可有经济原因。',
'同一标的所有月份隐波必须相同|各期限包含的未来风险事件不同，隐含波动率期限结构不必平坦。',
'把六月到期日改成公告日再比较|不能为了消除差异篡改合约期限。',
'只比较权利金，期限差异无需考虑|权利金同时受期限与其他输入影响。']);
q('历史波动与隐含波动的用途','过去一个月实现波动率15%，当前期权隐波28%。分析员用15%直接替换市场隐波并断言模型价即成交价，问题在哪里？',[
"15%是历史统计，以它替换隐波不使模型价成为成交价|历史统计可作判断依据，但与从当前期权价格反解的隐波不同，也不是可执行报价的替代。",
"15%可直接由历史观察，因此必比28%更准确且可执行|历史可观察不等于更能代表未来，更不能使某个模型价格成为市场成交承诺。",
"两个数只要都按年化计算就可互换，差别仅为显示精度|年化单位一致仍未统一回看统计与市场反解的经济含义，不能按同一测量值替换。",
"取两者均值21.5%后，模型价就等于当前无偏市场报价|简单平均没有提供市场愿意成交的证据，也未处理模型与未来情景差异。"]);
q('跨行权价单一隐波的遗漏','标的现价附近隐波为20%，深度虚值认沽隐波为35%。风控统一用20%估计所有认沽价格，首要缺陷是什么？',[
'忽略波动率偏斜，可能低估下行保护的市场成本|不同行权价可有不同隐波，单一输入抹去尾部保护定价差异。',
'所有虚值认沽价格都应为零|虚值只表示当前内在价值为零，剩余期限的潜在行权机会仍有价值。',
'隐波偏斜意味着无论如何都可无风险套利|曲面存在斜率不自动违反无套利约束。',
'把35%换成历史均值就能恢复真实市场价|历史均值不是当前该行权价可成交价格。']);
q('波动率单位归一','系统A的Vega是每1个百分点价格变动0.04元，系统B按波动率小数变化1计量。为了等价，B应显示多少？',[
'4元|1个小数单位等于100个百分点，所以0.04×100=4。',
'0.04元|保留数值但更换单位会把敏感度缩小100倍。',
'0.0004元|换算方向倒置；更大的输入单位对应更大的数值敏感度。',
'40元|放大了1000倍而非100倍。'],calc('.04*100',4,'元/波动率小数单位'));
section('options',3,'theta-vega-rho','expansionDerivTheta','Theta：模型时间约定与价格分解；案例A8');
q('周末Theta不是固定收费','客户看到Theta为−0.002元/自然日，就认为周一开盘交易所必从账户扣0.006元/份。哪项解释正确？',[
'Theta是估值敏感度，实际期权价格还受其他输入影响|时间损耗不是交易所逐日收取的固定费用，也不保证周一成交差额。',
'周末三天一定从现金账户单独扣款|Theta描述模型估值的时间敏感度，并非从现金账户单独扣取的费用。',
'有Theta就意味着周一期权不能上涨|标的、隐波等变化可能抵销甚至超过时间影响。',
'应将该费用改由卖方支付|Theta不是双方之间独立结算的收费项目。']);
q('时间价值衰减的非线性','学生用今天Theta乘剩余90日预测到期价格，结果为负值。对模型使用的合理修正是什么？',[
"Theta应随时间和状态重算，不能固定线性外推90日|固定当前局部斜率外推整个期限可能产生不合理负值，应更新估值并满足价值边界。",
"保留当前Theta乘90，将负结果截为零即可得到精确终值|截零只能移除部分越界结果，不能恢复被线性外推遗漏的状态与时间变化。",
"把90自然日换成剩余交易日后，当前Theta就能固定使用|时间口径需匹配，但更换日数单位不能消除Theta本身会变化的问题。",
"把当前时间价值均分为90份，就得到整个期限恒定Theta|均摊成本只是人为直线，不是模型实际的时间价值演变或逐日敏感度。"]);
section('options',2,'covered-protective','expansionDerivCases','案例A9：题设备兑、保险、分红及成本合并');
q('锁定证券处置的前置核验','题设一万份ETF已锁定为一张认购备兑证券，系统不允许直接卖出。客户想保留认购空头并卖掉ETF，合规操作计划首先应确认什么？',[
'是否获准转为普通卖出持仓、所需保证金及解锁流程|不能把被锁定证券直接当可卖资产，应先满足转换后的权限和资金条件。',
'只需在现货界面反复提交卖单|重复申报不能解除系统的有效锁定，也不满足普通空头保证金要求。',
'把备兑证券改记成现金即可卖出|账面改名不完成解锁和持仓转换手续。',
'先卖另一账户同品种证券，原锁定会自动解除|其他账户交易不会无条件改变本账户的备兑锁定。']);

q('一部分现货已被另项承诺占用','客户有两万份ETF，其中一万份已承诺按不可撤销合同交付给他人。若再写两张每张一万份的认购并称全部有备兑，主要问题是什么？',[
'同一份证券不能重复计算为可自由履约的覆盖资产|应核查可用、未被其他交付义务占用的证券数量。',
'只要账面总数两万份就无条件足额覆盖|账面持有不等于可以自由用于每一项义务。',
'权利金收入能自动生成缺少的一万份ETF|现金收入不自动变成证券，购买还受价格及流动性约束。',
'认购卖方只需准备现金不用证券|题设覆盖涉及实物交付，不能忽略标的准备。']);
q('双约束保险方案选择','现货成本100元/份，希望同数量同到期保险把最大净损失限制为5元，同时保费不超过3元。忽略费用与利息，下列认沽中哪项同时符合两条件？',[
'行权价98、保费3|净最大损失100+3−98=5，且保费3正好符合预算。',
'行权价100、保费4|最大损失虽为4，但保费超过3元预算。',
'行权价96、保费2|保费符合预算，但最大净损失100+2−96=6，超过限额。',
'不买认沽，保费0|虽无需保费，但标的可能下跌超过5元，不能满足保险损失上限。'],calc('100+3-98',5,'元/份最大净损失'));

q('预期分红的保护底线口径','题设ETF成本100，认沽费4、行权价98，持有期间确定收到分红2且不再投资，忽略费用利息。到期资产加已收现金的最低净损益是多少？',[
'−4|最低回收98加分红2，减总投入104，等于−4。',
'−6|只算98−104，漏掉题设已确定到账分红2。',
'−2|把保险费漏扣，或重复增加分红现金。',
'0|保护性认沽并不自动将全部初始成本保住。'],calc('98+2-100-4',-4,'元/份'));
q('以不同ETF认沽替代精确保险','持有甲ETF，用跟踪另一指数的乙ETF认沽做保险。经理宣传甲组合有确定最低价值，最应修正哪里？',[
'跨标的保护依赖联动，不能直接套用同标的最低价值公式|乙的认沽赔付取决于乙价格，未必覆盖甲的独立下跌。',
'只要两只ETF今天同价即可永久精确保护|两只ETF跟踪对象不同，今天同价不保证未来价格路径和跌幅一致。',
'把乙认沽数量翻倍就必能锁底|增加数量不消除基差和相对价格风险。',
'认沽本身没有下行保护功能|认沽有保护作用，问题在被保护资产与合约标的不匹配。']);
q('借出证券召回与认购交付错配','题设某境外账户已合法出借10000股，同时持有需T+1交股的认购空头；借贷合同允许借券人到T+2才归还。经理仅凭账面应收10000股就称交收已准备完成。应怎样修正？',[
'核验提前召回或其他合法交券渠道，确保T+1实际可交付|应收证券数量虽够，但合同允许的归还日迟于期权交付日，存在证券流动性缺口。',
'借贷应收凭证与股票完全等价，可直接用于任何期权交收|应收返还权不是已经到账可交付的证券，题设没有凭证替代交付安排。',
'认购被指派会自动把借贷归还日提前到T+1|两份合同的义务独立，期权指派不自动改变借贷合同期限。',
'收到认购权利金即可免除交股义务|收取权利金使卖方承担履约责任，不会替代规定数量的证券交付。']);

q('股价回本价与备兑最大收益冲突','现货成本5元，卖出行权价4.50元认购收0.10元，客户称只要标的到期涨到5元就回本。忽略费用，何项正确？',[
'被行权时最高净回收4.60元，仍低于5元成本|较低执行价封住卖出价，涨到5元并不会取消认购义务。',
'标的回到5元时可同时保留全部上涨与权利金|备兑卖出认购让渡执行价以上的涨幅。',
'回本价等于5.10元且可无限上涨回本|即使标的更高，交付价格仍受认购约束。',
'到期买回认购后卖现货即可回本，原权利金足够付回购款|标的为5元时认购内在价值0.50元，原收0.10元不足覆盖回购款；不能把解除上涨约束的成本遗漏。'],calc('4.5+.1-5',-.4,'元/份最高净损益'));
q('保险单位和保费的整数选择','持有25000份ETF，要求全部精确匹配认沽保险且总保费不超过1500元。题设标准合约每张10000份、保费600元；调整合约每张12500份、保费750元，条款其余匹配。应选哪项？',[
'2张调整合约|覆盖25000份，费用1500元，同时满足精确数量和预算。',
'2张标准合约|费用1200符合预算，但仅覆盖20000份，不满足全部精确匹配。',
'3张标准合约|覆盖30000份且费用1800元，数量和预算都不符合。',
'1张调整加1张标准|总保费1350元，但覆盖22500份，仍少2500份。'],calc('2*12500',25000,'精确覆盖份数'));

section('options',3,'strategies','expansionDerivCases','案例A10：明确同标的、同到期、相同单位的组合现金流');
q('认购比率价差的尾部裸露','同标的同到期买1张低执行价认购、卖2张高执行价认购，单位相同。有人按普通一比一牛市价差称收益损失均固定，遗漏了什么？',[
'额外一张卖出认购使大涨尾部仍有裸露空头|超过高执行价后净头寸相当于一张认购空头，不能套一比一边界。',
'低执行价多头可以覆盖任意数量空头|一张多头对应一张单位，无法覆盖多出的数量。',
'只要开仓净收权利金就不再承担损失|初始现金流不决定尾部风险是否有界。',
'所有认购价差都只有下跌风险|组合数量结构会改变上行风险形态。']);
q('价差腿单位不同的名义匹配','买一张认购单位12000份、卖一张认购单位10000份。两者同标的同到期但执行价不同。按等张数直接应用普通价差公式有什么问题？',[
'两腿实际份数不同，应先统一每份敞口|一张不一定等于相同数量标的，剩余2000份影响损益形状。',
'不同执行价意味着不能形成任何组合|组合可以存在，只是不能误用等量价差公式。',
'高执行价可自动抵销单位差|执行价和单位是不同维度，不会自动补足。',
'应把单位差忽略，只计算权利金净额|净权利金无法代表全部到期权利义务。']);
q('领口的成本来源','持有ETF后买低执行价认沽、卖高执行价认购，两笔权利金恰好相等。宣传称免费保险且没有任何代价，如何修正？',[
'净期权费可为零，但上行收益受卖购约束|零净权利金是以让渡部分上涨空间为条件，仍有策略取舍。',
'因为零成本，ETF下跌风险全部归零且无边界|保护只在合约数量、期限及执行价限定下生效。',
'卖出的认购不会被执行，因为与认沽费相等|权利金是否相等不决定对手方行权。',
'必须两笔权利金都为零才叫零成本领口|通常所称零成本指净权利金，不是每条腿单价为零。']);
q('跨式的主观情景期望损益','同执行价100的跨式净成本12，研究仅采用三种到期价：80概率20%、100概率60%、130概率20%。不计费，按这组主观概率计算期望净损益为多少？',[
'−2|期望毛价值=20×20%+0×60%+30×20%=10，再减成本12为−2。',
'+10|这是加权毛收益，尚未扣除初始12元成本。',
'+13|把两种非零结果简单平均并漏掉60%的中间情景。',
'+38|把不同情景收益直接相加而非按概率加权，再扣成本。'],calc('.2*20+.6*0+.2*30-12',-2,'元/份期望净损益'));

q('宽跨低成本的代价','同标的同到期，投资者把平值跨式改为低执行价认沽加高执行价认购，净成本通常降低。最应同步说明什么？',[
"两执行价之间存在两腿到期价值均为零的区间|由共同执行价的一点变为两个执行价之间的一段零支付区域，落在其中仍会损失全部投入成本。",
"期末价格只要离开建仓时现价，就足以覆盖两腿成本|价格小幅偏离现价后仍可能落在两执行价之间，零支付无法覆盖正权利金。",
"成本降低就保证两侧盈亏平衡点都更靠近当前现价|盈亏平衡点还依赖新执行价和两腿总成本，不能只凭投入减少作此保证。",
"两腿权利金降低就等于组合不再承担隐波下降风险|更低价格不代表Vega归零，买入的两腿通常仍会受到隐含波动率变化影响。"]);
q('日历价差不等于到期同日价差','卖近月认购、买远月同执行价认购，到近月到期标的大涨。为何不能只用执行价差零来认定无风险？',[
"应分别处理近月履约和远月剩余价值，不能按同日价差抵销|同执行价不等于同一期现金流，远月未到期的价值和近月已产生的履约安排需分别核对。",
"同执行价可把两腿合并成零支付，无须再考虑各自到期日|两个不同到期的权利义务不能像同日零宽度价差一样逐状态直接相抵。",
"先把远月也按近月到期时内在价值结算，就可直接抵销|远月仍有剩余期限，不能人为删除其时间价值或把交收日提前到近月。",
"只用开仓净权利金判断风险，远月未到期价格无需重估|初始净现金流不足以衡量之后远月价值变化与近月到期履约风险。"]);
q('长蝶式峰值与外侧的对照验证','买90和110认购各一份、卖100认购两份，同标的同到期，净成本3。比较到期S=100和S=120两种情景，哪组净损益正确？',[
'前者+7，后者−3|S=100时毛价值10；S=120时30−40+10=0，分别减净成本3。',
'前者+10，后者0|两项都是未扣初始净成本的毛价值，不能当净损益。',
'前者−3，后者+7|把中间执行价峰值与外侧毛价值归零区间颠倒。',
'前者+7，后者+27|高价情景不能只计算低执行价多头，还需计入两张空头及另一多头。'],calc('Math.max(100-90,0)-2*Math.max(100-100,0)+Math.max(100-110,0)-3',7,'中间价净利润'));

q('不等距蝶式的尾端净额','买90和120认购各一份、卖100认购两份，同到期同单位，净支付3。超过120以后，为什么到期净损益固定为−13而非普通等距蝶式的−3？',[
"两侧宽度10和20不同，高端毛价值−10再扣成本3|高价时两多两空的斜率抵销，但常数项为10−20，扣原成本3得−13。",
"数量两多两空相抵，所以高端毛价值为0、净损失为3|数量相等只消除高价段斜率，不会消除不同执行价形成的非零常数项。",
"只计100至120的卖出价差，毛价值−20再扣成本3|遗漏买90卖100这一侧同时提供的正10，不能只保留一边价差付款。",
"把两侧宽度10和20相加，毛价值30再扣成本3|两侧价差方向相反，应按10减20而非同号相加，不能忽略卖出腿的符号。"],calc('(100-90)-(120-100)-3',-13,'元/份高价尾端损益'));

q('铁鹰内区间与信用收入','题设买90认沽、卖95认沽、卖105认购、买110认购，各一份同到期，净收2。到期S=101，净损益是多少？',[
'盈利2|四腿均虚值，到期无履约损益，保留净收权利金。',
'盈利5|5是单侧执行价宽度，不是该点利润。',
'亏损2|开仓为净收而非净付，现金流符号反了。',
'盈利7|将执行价宽度错误加到没有内在价值的区间收益上。'],calc('2-Math.max(95-101,0)+Math.max(90-101,0)-Math.max(101-105,0)+Math.max(101-110,0)',2,'元/份'));
q('平仓短腿后策略风险改变','客户原持有牛市认购价差，随后只卖掉低执行价认购多头，保留高执行价认购空头。风控应如何更新？',[
'取消原有限上行损失的组合假设，重新评估裸卖认购|保护腿离场后组合结构改变，不能沿用原价差风险边界。',
'继续保留原价差损失上限直到到期|风险界限取决于现存头寸，不是策略开仓名称。',
'把剩余短腿自动视为认沽买方|卖掉一腿不会改变另一合约的权利义务方向。',
'只要已实现盈利，剩余短腿就没有风险|已实现利润不能取消未来履约义务。']);
section('options',4,'risk','expansionDerivCases','案例A11：题设资金、履约和风险治理');
q('权利金收入并非可全部消费资金','卖出认购收取5000元权利金，账户另有保证金占用。客户拟将5000元全数转出，首先应检查什么？',[
'转出后权益、可用资金和压力情景下的履约能力|权利金是现金流入但对应尚未结束的义务，不能直接视作已赚自由资金。',
'只看开仓时收入是否为正|正现金流不表示负债或风险已消失。',
'只看期权是否暂时虚值|暂时虚值不能保证未来不会实值或保证金不上升。',
'收款当天就把全部权利金确认为无风险利润|交易尚未终止，利润需结合负债价值和费用衡量。']);
q('压力网格遗漏中间亏损峰值','风险系统只测试标的到期为0或200。题设某有限风险卖方组合在这两个点各赚3，但在100附近亏7。经理据两端结果取消风险限额，正确改进是什么？',[
'增加执行价和损益拐点附近情景，覆盖内部亏损峰值|组合最坏情景可能在价格区间内部，仅测试两端不能证明无损失。',
'把200再提高到300就必能发现全部风险|扩大外端仍可能漏掉100附近的内部亏损区。',
'只测试标的归零就足够|最低标的价不一定是所有期权组合最差的损益位置。',
'将两端盈利取平均能代表最大亏损|均值不能代替对整个损益函数最不利位置的检验。']);

q('报价中断时的风险估值','极端行情中期权盘口暂时无有效买价，系统用零价估计空头负债，显示巨额盈利。合理处理是什么？',[
'使用经批准的估值和压力方法并标记流动性不确定性|缺少可成交买价不代表期权负债价值为零。',
'立即确认全部权利金利润|未平仓义务仍在，缺价不等于义务消失。',
'把所有空头负债按原始权利金永久固定|原始价格也可能严重偏离当前风险，需要合理更新。',
'关闭风险报告直到有行情|无报价时更需风险控制，而不是停止监测。']);
section('options',4,'risk','expansionDerivAssignment','FAQ首段：清算层随机分配与经营机构获准的客户分配方法是不同环节；FIFO条件由题设指定');
q('清算随机不等于客户层也按比例指派','题设清算机构随机分配后，券商收到同系列40张指派；该券商客户层采用已披露的先进先出法。甲较早建立50张空头，乙较晚建立50张，均未平仓。此次客户分配应如何执行？',[
'甲分到40张，乙此次为0张|先在清算层选中券商，再按题设客户层FIFO分配；两个环节的方法不能混为同一规则。',
'甲乙各20张，因为清算机构采用随机法就要求券商按持仓比例分配|上层随机分配不把客户层明示的FIFO改为按比例分配。',
'乙分到40张，因为最近建立的空头必须先履约|这采用后进先出，与题设明确的先进先出顺序相反。',
'甲乙应各分40张，以保证客户之间受到同等对待|券商总共只收到40张指派，分别分40会重复分配同一履约通知。']);
section('options',4,'risk','expansionDerivCases','案例A11：题设资金、履约和风险治理');
q('相互排斥情景的损失汇总','题设只有两种互斥联合情景：甲的方向效应亏2000、隐波效应赚800；乙方向效应赚1500、隐波效应亏1000。忽略交叉项，两个已定义情景中最大净损失是多少？',[
'1200元|甲净亏1200，乙净赚500；应在完整联合情景间取最大亏损。',
'3000元|把甲的方向亏损和乙的隐波亏损拼成未定义的联合情景。',
'2000元|只看甲的方向项，漏掉同一情景中800元抵销。',
'700元|将互斥情景的两笔净结果相加，混淆情景最大损失与累计损益。'],calc('Math.max(2000-800,1000-1500)',1200,'元'));

q('按胜率选择卖方策略的遗漏','策略甲95%交易盈利但最差一次亏损40倍平均盈利；策略乙胜率60%且损失受限。仅凭胜率选甲，缺少的核心比较是什么？',[
'收益损失大小、尾部概率及资金承受能力|高胜率可能伴随少数巨亏，需完整损益分布。',
'只需扩大甲交易次数，低概率亏损会消失|次数增加并不会消灭尾部事件，可能增加遭遇机会。',
'甲平均单笔盈利一定高于乙|期望收益还要结合各次盈利和亏损的幅度，高胜率可能被大额亏损抵销。',
'两者胜率不同所以无法比较风险|可结合盈亏幅度及分布作一致口径比较。']);
q('策略止盈后仍残留挂单','客户已全部平仓认沽空头，却遗留原本用于买入止损的有效条件单。下一步最合理是什么？',[
'核实并撤销不再需要的条件单，确认结果|若再次触发可能建立意外多头或造成系统拒单，需闭环管理。',
'无需处理，因为平仓必然删除一切条件单|题设没有联动撤单保证，不能推定。',
'把条件单数量加倍以防风险|原风险已经结束，加量可能制造新风险。',
'将条件单视为已经成交并记入损益|挂单不等于成交，不能提前确认交易。']);
q('交易授权与风险限额独立','交易员获准卖出认沽，但风险制度规定单一到期月不得超过总限额一半。他认为有交易授权就可全放同月。正确理解是？',[
'方向授权和集中度限额需同时满足|允许交易某类产品并不豁免其他风险边界。',
'交易授权自动覆盖所有数量期限限制|权限范围与风险额度是不同约束。',
'只要先盈利就可以事后补限额审批|结果盈利不能代替事前有效授权。',
'将同月拆成多个订单即可避开集中度限额|拆单不改变合并头寸和实际期限集中度。']);
q('价差交收的过桥资金时序','题设同一组合T日上午须支付20万元，T+1才确定收到18万元，经营机构不允许跨日预支或净额抵销；T日上午可用现金5万元。为了按时支付，至少须安排多少过桥资金？',[
'15万元|T日上午20万元支出只能用现有5万元及过桥资金支付，次日18万元不能提前使用。',
'2万元|这是两日净支出，不是T日上午的即时缺口。',
'0万元|把次日收款提前抵扣，违反题设不允许预支的条件。',
'20万元|忽略了T日上午已经可用的5万元现金。'],calc('20-5',15,'万元'));

q('风险指标越界的升级处理','盘后发现卖方组合超出预定Vega限额，但交易员称明天可能自然恢复。最合适的治理动作是什么？',[
'按制度记录、升级并确定获授权的处置方案|猜测次日恢复不能替代越限管理和责任留痕。',
'删除当日风险记录等待恢复|掩盖越限削弱监测，不能消除风险。',
'把限额临时调高但不通知审批人|越限后由交易员自行抬高边界会规避原审批约束，须走有效授权程序。',
'只要Delta合规就不用管Vega限额|不同风险限额控制不同维度，不能互相替代。']);

section('options',1,'lifecycle','expansionDerivCases','案例A12：题设特殊行权和结算条款');
q('微小实值与行权净收益','题设现金结算期权仅实值5元，主动行权另收8元费用，放弃没有额外费用且允许放弃。其他现金流相同，经济上应怎样比较？',[
'主动行权净增现金为−3元，放弃更有利|应比较未来增量现金流5−8，而非仅看实值标签。',
'只要实值就必应行权|忽略了高于行权收益的增量费用。',
'原权利金很高，所以必须行权|已支付权利金是沉没成本，不改变本次5与8的增量比较。',
'行权费应乘原权利金后比较|本次增量现金流应以5元收益减8元费用，历史保费不参与相乘。'],calc('5-8',-3,'元'));
q('结算平均价与收盘价错用','题设现金结算认购使用最后半小时平均价100.8，行权价100；当日收盘102。研究员按2计算每单位行权收益，应改成多少？',[
'0.8|合同结算参考价是100.8，故内在价值0.8，收盘价不是本题输入。',
'2|2元来自102减100，但合同指定平均价100.8而不是收盘102。',
'1.2|这只是收盘与均价之差，不是认购结算收益。',
'100.8|把结算标的价格当成差额收益，漏扣行权价。'],calc('100.8-100',.8,'元/单位'));
q('美式与欧式模型混用','海外教学案例明确允许存续期提前行权，研究员直接用来证明题设欧式ETF认购明天也能行权。缺少哪项核验？',[
'合约行权方式及适用市场规则|一般收益理论可以比较，但提前行权权利取决于具体合同。',
'只核验两只期权是否均为认购|认购说明买入标的的权利方向，允许行权的日期还要看欧式或美式约定。',
'只核验标的是否上市|上市证券的期权仍可能具有不同的行权方式。',
'只要买方愿意放弃时间价值即可提前行权|经济意愿不能创造合同未授予的提前行权权利。']);
q('外部行情与机构截止时点','客户在经营机构规定的有效申报截止时点后看到标的价格上涨，想要求按晚些行情补做当日行权。最合理的处理原则是什么？',[
"核对截止与例外程序，按真实受理记录判断指令效力|行情变化不会追溯生成及时有效的指令，是否可用例外程序须依真实规则和受理记录。",
"用最新行情重算实值，只要实值就补记为截止前行权|最终价格有利不等于客户在有效时段已经申报，经济价值不能代替业务时点证据。",
"只按客户本机发送时间认定及时，无需检查机构受理要求|客户设备时间和系统受理时点可能不同，应按适用协议核对，不能单凭本机记录替代。",
"交易所截止较晚，就认定机构此前披露的服务截止无效|不同机构可有处理截止，不能因交易所窗口较晚便自动排除已有效约定的服务要求。"]);
section('options',3,'pricing','expansionDerivCases','案例A13：题设估值输入与理论边界');
q('模型波动率负值的数据校验','导入表将隐含波动率写成−20%，定价程序仍输出一个价格。最恰当的处理是？',[
'拦截并核对符号、单位和原始数据|标准波动率参数非负，程序有输出不证明输入或结果有经济意义。',
'保留输出，因为价格为正就正确|结果符号不足以验证参数合法性。',
'负波动率表示价格一定下跌|波动率描述幅度，不是带方向的收益率。',
'把期权多头改为空头即可兼容负波动率|头寸方向不改变波动率输入的定义。']);
q('同期限认购执行价单调性','题设无套利无摩擦、同标的同期限欧式认购，K=90的可买价竟低于K=100的可卖价。何种组合揭示问题？',[
"买90认购、卖100认购，建立同到期的牛市价差|低执行价权利逐状态不劣于高执行价，本题还能先收净现金，构成无摩擦条件下的支配组合。",
"卖90认购、买100认购，建立同到期的熊市价差|这与所需支配方向相反，会支付不利价格并承担非正的到期差额。",
"买90认购、买100认购，同时扩大两份上行参与|两笔买方权利仍需支付成本，未来均可能到期无价值，不能构成题设的确定套利。",
"卖90认购、卖100认购，靠两笔收入覆盖未来履约|收取两笔权利金不约束上涨时的空头损失，不是逐状态无亏的支配组合。"]);
q('同一损益采用两次汇率换算','美元期权每份盈亏已先按7.2元人民币/美元换成人民币，报表又乘7.2。复核应指出什么？',[
'重复换汇，第二次乘汇率应删除|同一美元现金流只需在明确时点按选定汇率转换一次。',
'必须乘两次，因为开仓和平仓各一次|若已计算美元净损益再统一转换，不应无理由再乘同一汇率。',
'应把第二次改成加7.2|币种转换是单位运算，固定加数没有依据。',
'只要汇率没有变化，重复换算不影响结果|汇率恒定并不使重复乘法变成恒等变换。']);

// Batch A: futures1 0001–0075. Decisions cover all nine existing teaching chapters.
section('futures1',1,'futures1-1','expansionDerivCases','案例F1：采购、销售与风险转移的明示条件');
q('已锁采购价后再次买入套保','工厂已用不可撤销固定价合同锁定全部原料采购价格，又拟为同一数量买入期货防涨价。首先应确认什么？',[
"确认是否仍有未锁风险，新增买入可能产生净多头|套保应针对剩余风险，固定价采购已锁住的价格需求不能再无条件重复对冲。",
"按采购吨数再买同量期货，固定采购价不影响所需数量|物理采购数量存在不代表价格仍浮动，必须先确认未锁风险而非机械按吨数重复建仓。",
"只比较合同价与期货价，较低的一边就能证明对冲必要|相对便宜影响交易判断，但不能证明已固定采购仍存在对应的价格风险。",
"确认期货未来盈利概率高，便可替代现货风险对应审查|盈利预期不能建立套保关系，方向交易可能盈利也可能使原无风险成本重新浮动。"]);
q('销售价与原料价同时浮动','加工厂产品售价和原料采购价均随市场浮动，经理只卖出产品期货就声称锁定利润。还需要检查什么？',[
"检查原料成本、收率和售价共同决定的利润敞口|加工利润由收入减原料等成本形成，单独卖出产品期货未必稳定实际毛利。",
"只核对产成品销售数量，无需纳入原料价格变化|原料价格仍会影响利润，销售端数量匹配不能消除成本端的浮动风险。",
"产品和原料各做同样手数，先不换算实际加工收率|两种合约的单位和加工收率决定真实数量关系，同样手数不保证利润敞口匹配。",
"只按产品期货盈利预算毛利，现货成本暂用固定金额|题设原料采购价浮动，随意固定成本会漏掉可能压缩利润的重要风险来源。"]);
q('不确定订单与过度套保','航空服务商预计下季耗油1000吨，但已确认的业务只需要600吨，其余订单可取消。制定套保时主要额外风险是什么？',[
"订单取消可降低实际用量，按预计量全套保可能过量|未来实际需求可能低于预计1000吨，超过真实采购的期货部分会形成独立方向敞口。",
"将满额头寸展到更远月，就可消除订单取消的数量风险|换月份只改变期货期限，不恢复已经取消的业务需求，也不自动修正套保数量。",
"选最活跃合约可使预计1000吨成为确定需求，再全额套保|合约流动性影响执行，不改变企业客户能否取消订单的经营条件。",
"额外400吨始终沿用原预测，无需随可取消订单变化复核|预测不是不可撤销订单，敞口变化后持续沿用原量可能造成过度套保。"]);
q('库存融资与价格风险分离','贸易商已卖出期货对冲库存跌价，但库存贷款将在下月到期而货物两月后才售出。哪项风险仍应单独处理？',[
'融资到期与销售回款之间的流动性缺口|价格对冲不自动延长贷款期限或提前取得货款。',
'期货对冲使贷款无需偿还|期货只管理相关价格风险，原贷款的本金和到期偿还义务仍然存在。',
'库存价值只要稳定就等于现金可用|资产价值与可立即支付现金不同。',
'把期货合约名称记为贷款即可延后到期|报表中的名称不能延长贷款约定到期日，仍需实际融资安排。']);
q('价格发现与单一大单冲击','某远月合约几乎无成交，一笔小额交易将价格推高5%。企业将其作为全部年度预算的唯一依据，最应补充什么？',[
'流动性、成交深度和其他现货远期信息的交叉核验|薄弱盘口的单一成交可能代表性不足。',
'只要来自交易所就一定是未来确定价格|交易所成交仍不构成未来价格承诺。',
'直接用上涨5%推定未来每月都涨5%|一次价格变化不能机械外推所有期限。',
'把成交量去掉，避免影响价格判断|成交量与深度是判断信号质量的重要信息。']);
q('套保风险降低的方差衡量','企业等概率经营净损益原为−10或+10万元，匹配套保后为−2或+2万元，忽略费用。经理称平均收益同为0所以毫无效果，按题设方差口径应如何评价？',[
'均值未变，但方差从100降至4，下降96%|风险管理可以在不提高平均收益时缩小经营结果波动，方差需比较平方偏差。',
'均值为0，所以两者风险完全相同|期望收益不能代替分布波动，结果范围已明显缩小。',
'方差下降80%，因为10降到2|80%是标准差或幅度的降幅，方差从100降至4。',
'套保后无风险，因为两种结果相加为0|相互排斥情景不能相加抵销，实际仍可能亏损2万元。'],calc('1-(.5*4+.5*4)/(.5*100+.5*100)',.96,'方差下降比例'));

section('futures1',2,'futures1-2','expansionDerivCases','案例F2：题设合约规格、交易计数和订单控制');
q('不同报价单位的合约价值','甲合约报元/吨、每手10吨；乙报元/千克、每手10000千克。甲报价2000，乙报价2。忽略其他差异，每手名义金额怎样比较？',[
'相等，均为20000元|先统一数量与报价单位，2000×10=2×10000。',
'甲是乙的1000倍|只比较报价数字忽略报价单位与交易单位。',
'乙是甲的1000倍|只比较单位数量而未匹配每单位价格。',
'无法比较，因为吨与千克不能换算|两者可以通过明确的1000千克/吨换算。'],calc('2000*10-2*10000',0,'元差额'));
q('最小价位约束与合法限价','题设合约允许报价必须为0.2的整数倍，当前报价100.0。交易员计划买入限价100.1，如何处理？',[
'按意图选择合法价位重新申报，100.1不符合最小价位|报价网格约束与交易员希望的精确价格是两回事。',
'100.1一定有效，因为高于当前报价|价格方向正确不能替代最小价位约束。',
'只要增加手数即可提交100.1|交易手数和报价最小档位是不同限制，加量不能使100.1合法。',
'把100.1写成100.10就有效|小数格式改变不改变数值不合规。']);
q('开仓双方与持仓量增加','题设持仓量按单边合约数统计。新买方和新卖方各开10手成交，成交前持仓量100手。成交后应为多少？',[
'110手|双方形成10对未平仓合约，单边统计增加10而非20。',
'120手|把多空双方重复加总为单边持仓量。',
'100手|新开对手盘增加未平仓合约，不是简单换手。',
'90手|题设双方都建立新头寸，应新增10对合约而不是减少存量。'],calc('100+10',110,'手'));
q('开平换手与持仓量不变','题设单边统计。老多头卖平7手，新多头买开7手，原空头不变。成交量增加7手，持仓量如何变化？',[
'不变|多头权利从旧持有人转给新持有人，未平仓合约对数不变。',
'增加7手|新多头增加7手的同时原多头平掉7手，二者对存量影响抵销。',
'减少7手|原多头退出的7手全部由新多头承接，未平仓合约对数不变。',
'增加14手|既重复统计双方，也没区分开仓与平仓。']);
q('成交量累计不能当存量','某合约全天反复换手成交1万手，收盘未平仓仅2000手。分析员认为有1万手等待交割，应如何修正？',[
'成交量是期间流量，未平仓量才是尚存合约存量|同一头寸可多次转手，成交不能逐笔累计成待交割数量。',
'等到次日所有成交自动都变成持仓|成交记录不会在次日重新生成已平合约。',
'两者相差8000手表示交易数据必造假|高换手可自然造成流量大于存量。',
'应把持仓量乘成交次数推算交割|重复换手不增加最终需要履行的合约对数。']);
q('交易年份省略造成错月风险','报单界面同时有次年3月和后年3月合约，客户只写3月买入。经纪执行前应如何处理？',[
'核对完整到期年月及合约代码|相同月份不同年份对应不同期限风险，模糊指令不宜猜测。',
'默认最远年份，因为更安全|更长期不必然更符合客户目的，也不能代替确认。',
'各买一半避免选错|这未经明确授权改变了交易数量与期限结构。',
'只核对品种名称即可|同一品种在不同年份的三月均可能挂牌，必须补全到期年份。']);
q('小型合约替代的数量换算','企业需对冲大合约3手，每手50吨；改用每手10吨的小合约且风险单位相同。等数量替代应为多少手？',[
'15手|3×50÷10=15，按标的数量而非合约张数替代。',
'3手|小合约每手只相当于大合约的五分之一，原3手需要换成15手。',
'5手|仅计算单位倍数，未乘原有3手。',
'150手|把总吨数直接当手数，漏除小合约单位。'],calc('3*50/10',15,'手'));
q('组合委托部分成交的敞口','跨期策略计划买近卖远各20手，实际仅买近20手成交，卖远尚无成交。当前头寸应怎样报告？',[
'20手近月方向多头，待补的远月腿不能算已对冲|风险报告依据已成交头寸，未成交委托不提供确定保护。',
'完整20组跨期套利，按原计划记账|卖远尚未成交，当前只有已买入的近月多头，不能按完整组合记风险。',
'风险为零，因为两张委托方向相反|委托未成交不产生相应抵销头寸。',
'只报告净委托数量零即可|净委托掩盖已经形成的方向风险。']);
section('futures1',3,'futures1-3','expansionDerivMTM','Mark-to-Market：结算与资金变动；所有制度参数均由题设给出');
q('临时结算价更正的增量入账','题设清算先按临时价105结算并入账，后将同日正式结算价更正为104。账户持有50手多头，每手乘数10，数量未变。为避免重记全日盈亏，更正时应记多少增量？',[
'扣减500元|只补记正式价减临时价的差额：(104−105)×50×10=−500。',
'增加500元|多头的结算价格下调应减少收益，不能反向增加。',
'重新记入104×50×10元全部名义价值|名义价值不是结算更正额，且会重复已处理的原结算。',
'无需调整，因为临时结算已经入账|正式价格已更正，应以增量修正临时结果而非保留错误金额。'],calc('(104-105)*50*10',-500,'元增量'));

q('收盘涨而当日盯市亏损','多头昨天结算价100，昨天收盘98，今天结算99。新闻称今天比昨日收盘涨1，账户为什么仍计当日亏损？',[
'跨日持仓盯市基准是昨结算100，故下降1|新闻收盘比较与清算基准口径不同。',
'账户错误，因为新闻涨价必须盈利|先核对比较基准，新闻涨跌并非结算损益保证。',
'只要结算99高于收盘98，就必须盈利1|98是昨日收盘而非昨结算，使用了错误起点。',
'应把两个基准平均为99后计零|无规则依据不能自行平均清算基准。'],calc('99-100',-1,'点'));
q('权益增长中的外部入金剔除','期初权益10万元，期末11.9万元，期间净入金3万元，除此之外只有交易损益和费用。经理宣称赚1.9万元。扣除外部现金流后本期净交易结果是多少？',[
'亏损1.1万元|11.9−10−3=−1.1；权益增长来自入金超过交易及费用损失。',
'盈利1.9万元|仅比较首尾权益，没有剔除投资者新增投入。',
'盈利4.9万元|应扣除而非加上外部净入金，否则进一步夸大收益。',
'亏损3万元|净入金是外部资金流，不等于交易损失金额。'],calc('11.9-10-3',-1.1,'万元净交易结果'));

q('保证金释放不是新增利润','客户平仓后保证金占用由8万元降至0，账户权益保持不变。可用资金增加8万元，是否应计为新增交易盈利？',[
'不应，释放只是资金由占用转为可用|权益没有因释放本身增加，实际盈利已按结算和平仓计算。',
'应全部计入，因为可用资金增加|保证金释放只改变同一权益中可用和占用的分类，并未增加总资产。',
'应计一半，保证金一半是费用|保证金是占用担保资金，题设没有将其中一半当作手续费支出的规定。',
'应从权益扣8万元再计利润8万元|这种额外记账没有经济现金流依据。']);
q('价格盈利与提保同时发生','账户期初权益12万元，占用保证金8万元；当日盈利1万元，但保证金要求升至11万元，无其他变化。可用资金比此前怎样变化？',[
"从4万元降至2万元，减少2万元|新权益13减占用11为2；盈利1不足以抵销保证金新增占用3，可用资金反而减少2。",
"从4万元升至7万元，增加3万元|把保证金占用增加3误当成释放资金且遗漏当日盈利1，因而错误地只在原可用4上加3。",
"仍为4万元，前后没有发生变化|当日盈亏与保证金要求都已变化，不能继续保留原来的可用资金数值。",
"从4万元升至5万元，增加1万元|只加入当日盈利1而遗漏占用保证金从8增加到11的影响。"],calc('(12+1-11)-(12-8)',-2,'万元'));
q('套保流动性备用额度的可靠性','企业预计极端行情需补保证金80万元，账上现金30万元，另有银行50万元未承诺授信，合同允许银行在信用恶化时拒绝提款。声称资金缺口已完全覆盖的问题是什么？',[
"未承诺额度可被拒绝，50万元不能无条件当作现金|应核查提款条件、时点及同一压力情景下可得性，名义额度不等于确定可用的保证金资金。",
"额度与剩余缺口同为50万元，数量匹配便证明风险已覆盖|名义数量相等没有解决信用恶化时银行可拒绝提款的合同条件。",
"提款没有超过授信额度，便不再受信用恶化条款影响|未超额度只是金额条件，合同保留的拒绝提款权仍可能在压力时生效。",
"企业期末套保预计盈利，银行就必须按名义额度当期放款|合同没有把最终套保盈利作为无条件提款保证，未来盈利也不等于当期现金已到账。"]);

q('保证金不足的时间期限','题设风险通知要求上午10点前补足，客户11点才发出转账，资金尚未到账。判断是否完成补足，应重点看什么？',[
'合同约定的到账标准、实际到账时间和处置条件|发送转账并不必然等于按时形成可用资金。',
'只要当天转账就视为满足任意时点要求|题设以上午10点为补足期限，同日较晚转账仍可能不满足及时补足。',
'截图能证明已经到账而无需核验|转账截图只可能证明已提交支付，需另核实资金是否按要求到账可用。',
'账户曾盈利即可自动延迟期限|历史盈利不改变当前资金要求和合同安排。']);
q('连续涨停对空头止损的阻碍','空头想买入平仓，但市场封在涨停且几乎无卖单。为何可用资金充足也不能保证马上退出？',[
'平仓还依赖对手卖盘和撮合，现金充足不创造流动性|风险容量与成交可得性是不同约束。',
'资金足就能要求交易所必按涨停价卖出|交易所并无题设中的无限对手盘义务。',
'买入指令方向错误，应卖出平仓|空头反向平仓应买入，问题在卖盘不足。',
'涨停只限制开仓，不影响任何平仓|题设封板可能同时妨碍买入平仓成交。']);
section('futures1',4,'futures1-4','expansionDerivBasis','Learn about Basis: Grains：地区、品质、期限与期现匹配');
q('仓库地区变更的基差敞口','企业原计划在港口采购，后改为内陆采购，同期期货头寸未变。即使全球价格走势一致，新增需要监测什么？',[
'运输及地区供需变化导致的当地基差|期货不能保证不同地点现货价格相对关系恒定。',
'只需看期货价格，地点不影响采购价|运费与地区供需可能显著影响当地报价。',
'将内陆吨数改成港口吨数可消除地区风险|数量计量不改变交付地点的经济差异。',
'期货合约会自动跟随采购地址修改|标准合约交付条款不会因客户采购地点改变。']);
q('品质升水改变套保结果','企业出售高等级产品，卖出标准品期货套保。到出售时高等级升水明显收窄，标准期现价格完全收敛。仍可能损失哪部分？',[
'高等级相对标准品的品质升水|标准品价格对冲不自动锁定非标准品质差额。',
'标准期现收敛后任何品质差价都必须为零|品质差额与交割标准基差不是同一概念。',
'期货合约单位的整数部分|单位问题与品质升水变化不是同一风险。',
'已结算期货盈利会被自动取消|品质升水变化不追溯取消合法结算。']);
q('预期基差与实际基差的预算偏差','卖出套保初始期货价4000，预算销售时基差−50，实际基差−120。数量匹配不计费，实际有效售价比预算低多少？',[
'70元/单位|预算3950、实际3880，基差多弱70导致有效售价低70。',
'120元/单位|只看实际基差，没有与预算−50比较。',
'50元/单位|只用原预测基差，忽略实际结果。',
'170元/单位|把两个负基差绝对值相加而非计算变化。'],calc('(4000-50)-(4000-120)',70,'元/单位'));
q('固定基差采购合同锁住哪一层','采购合同规定最终现货价=指定期货定价日价格+30元，企业尚未锁期货价。此合同已锁定什么？',[
"锁住相对指定期货的30元基差，尚未锁定商品全价|现货价等于仍浮动的期货价加固定升水，固定价差不等于固定价格水平。",
"锁住当前期货价加30的全价，以后期货变化不再传递|合同使用的是指定定价日而非当前的期货价，尚未锁住该未来参考值。",
"只锁住采购数量，没有固定任何与期货有关的价格关系|明示加30已经固定现货相对指定期货的升水，不能说所有价格关系均未确定。",
"只锁住升水不超过30，实际结算时升水仍可任意下调|题设给的是等于期货价加30的确定公式，不是最多加30的区间选择。"]);
q('提前终止采购改变套保性质','买入期货对冲三个月后采购，采购合同提前取消，期货仍继续持有。最合理的管理动作是？',[
"按更新后的实际敞口和授权，调整不再对应采购的期货|原采购风险消失后期货成为独立方向暴露，应重新明确目的和限额并执行获准调整。",
"原采购日尚未到，应维持原头寸至该日再核对套保关系|采购取消已改变当前敞口，不能仅因原日期未到就忽略现有独立风险。",
"先把期货展到更晚月份，使已取消的采购重新获得覆盖|展期不会让经营需求重新出现，只有改变期限而没有恢复原套保对应关系。",
"继续使用套保科目登记，无需更改原风险目的和限额|内部名称或科目不能替代真实业务敞口，取消采购后仍需更新风险管理。"]);
q('套保期与合约月选择','企业将在7月中旬采购，6月合约6月底停止交易，9月合约可覆盖采购日。若不希望在采购前被迫展期，应优先考虑什么？',[
"优先评估9月合约的流动性和基差，使其覆盖采购日|风险覆盖应延续至7月中旬，选择6月底停止交易的合约会迫使企业提前换月或留下空档。",
"优先6月合约，因月份数字距7月最近，无须安排换月|数字距离不能改变6月合约在实际采购前停止交易的事实，无法直接覆盖7月中旬。",
"优先报价最低的月份，以价格优势替代到期日匹配|低报价不保证合同存续至风险结束，也不自动补偿移仓或期限基差。",
"优先最活跃的6月合约，数量匹配即可忽略停止交易日|流动性和数量匹配都有价值，但不能使已停止交易的合约继续覆盖之后的采购日。"]);
q('负相关资产的套保方向','题设现货价格变化与可用期货价格变化的估计相关系数为负，其他最小方差输入为正。若套保目标是现货多头价格风险，传统卖出方向为何需重审？',[
'最优比率可能为负，按卖出手数定义会对应买入期货|负相关改变抵销方向，不能机械套用同品种卖出规则。',
'负相关说明期货没有价格波动|负相关表示两种价格倾向反向变化，并不表示期货没有自身波动。',
'必须把负号删掉才是合法套保|删除负号会丢失统计上的抵销方向。',
'相关系数为负就必可实现无风险盈利|负相关不等于完美负相关，估计也有风险。']);
q('套保比率估计窗口失效','企业用平稳时期一年数据估计交叉套保比率，近期监管政策使两个品种供需关系脱钩。应如何处理？',[
'检查关系稳定性、重估并进行压力与样本外检验|历史统计关系可能发生结构变化，旧比率不保证继续有效。',
'样本有一年所以永远不需更新|即使历史窗口很长，政策改变了经济关系后旧估计仍可能失效。',
'只扩大期货数量即可恢复相关性|交易数量不会让两个市场的关系重新稳定。',
'将政策日数据删除后宣称关系未变|删除不利事实不能解决新的风险环境。']);
q('按数量而非价值套保的单位错误','企业持有价值500万元的原材料，期货一手名义金额25万元。题设要求按价值80%套保，应使用多少手？',[
'16手|500×80%÷25=16，先求目标套保价值再除每手价值。',
'20手|这是100%价值覆盖，未乘80%。',
'400手|400万元是目标价值，不是手数。',
'25手|把每手名义金额误作应交易数量。'],calc('500*.8/25',16,'手'));
q('整数取整后的剩余风险','最小方差模型建议卖出12.4手，只允许整数手。经理选12手，风险报告应怎样处理？',[
'记录取整造成的残余敞口，并按风险政策选择12或13|整数约束使理论最优与可执行头寸有偏离。',
'12手与12.4手完全相同，无需记录|每手代表实际标的数量，舍去0.4手使可执行对冲少于理论目标。',
'必须交易12.4手，模型优于交易规则|交易规则限制不能由模型输出取消。',
'选13手就一定没有任何风险|向上取整也有偏离，且基差等风险仍存在。']);
section('futures1',5,'futures1-5','expansionDerivCases','案例F5：价差定义、转换关系和可执行套利成本');
q('价差定义反转后的方向','交易台原定义价差为远月减近月，改版后图表定义为近月减远月。原持仓买远卖近不变，图上价差上升对应什么？',[
'原持仓受损，因新定义与原收益方向相反|买远卖近收益取决于远减近扩大，近减远扩大则相反。',
'原持仓获利，因为图表上涨总代表多头赚钱|多头对应哪条合约和价差定义都要明确。',
'收益不变，所以价差符号完全无关|经济头寸不变，但图表变动与收益的映射符号改变。',
'系统会自动把持仓方向反转|图表定义变更不等于执行新的交易。']);
q('同吨数跨品种忽略加工收率','加工一吨原料通常产出0.8吨产品，经理按原料和产品各一吨建套利。首先应修正什么？',[
'按加工收率及合约单位匹配两腿数量|经济转换关系并非一吨原料对应一吨产品。',
'只要两腿价格相关就不需数量匹配|相关性不替代物理转换和价值比例。',
'把手续费设为零即可解决差异|手续费属于交易成本，免除它不会使一吨原料的产出从0.8吨变为1吨。',
'把产品合约代码改成原料即可|合约名称修改不能改变标的性质。']);
q('正毛价差覆盖不了双腿费用','某套利每单位毛收益6元，开平两腿总手续费3元、预估滑点2元、融资成本2元。净收益如何？',[
'亏1元|6−3−2−2=−1，必须合并完整成本。',
'赚3元|6减3只得到扣手续费后的余额，另有滑点2元及融资2元。',
'赚1元|只扣手续费和滑点，漏融资成本。',
'赚6元|毛收益6元尚需扣除合计7元的费用、滑点和融资支出。'],calc('6-3-2-2',-1,'元/单位'));
q('现金套利的仓储容量约束','理论期货价格高于现货加全部持有成本，但可交割仓库已经满库。为何不能直接认定可无限扩大正向套利？',[
'可交割仓储是实现现金套利的必要执行约束之一|没有合适存储及交割安排，理论复制路径可能不可执行。',
'价格高于成本后仓储会自动免费出现|仓库容量是现实交割约束，账面利润机会不能自动增加可用仓位。',
'只要能买现货就不需要存到交割|正向持有套利要把资产保留到相应交付时点。',
'提高杠杆能消除仓库容量限制|杠杆可能提供资金，但不能使满库的可交割仓库立刻有容量。']);
q('反向套利的融券可得性','股指期货显著低于理论价，研究员拟买期货并卖空现货组合。实施前哪个条件不可省略？',[
'现货可借数量、借券成本及卖空限制|反向复制需要可实现的空头现货和相应持有条件。',
'只检查期货账户保证金是否足够|还存在现货腿的借入和卖出约束。',
'用不存在的股票持仓直接报卖即可|没有合法可交付证券不能假定完成现货空头。',
'只要价差为正，借券成本可以忽略|现货卖空通常涉及借券费用及可得性，成本可能超过理论价差。']);
q('统计套利止损与均值变化','两品种价差长期均值100，因永久性税制变化升至180。策略不停加仓押回100，最主要的假设风险是什么？',[
'均衡价差可能已改变，历史均值不再是回归目标|结构变动会改变经济关系，均值回归并非无条件。',
'历史均值100具有法定价格约束力|统计均值不是市场必须达到的价格。',
'价差偏离越大，持仓就绝不可能亏损|持续偏离可扩大亏损和资金压力。',
'只要两腿都上市就保证到期价差归零|不同商品各自有供需和交割标准，挂牌不能保证彼此价差在到期归零。']);
q('价差小风险与毛头寸大风险','跨期组合两腿各1000万元，净价差敏感度很小。为何仍需监测毛头寸？',[
'分别提保、腿间流动性和不同步退出可能制造大额资金需求|净价格风险小不等于每腿资金与执行风险小。',
'净敏感度小就无需任何保证金预算|实际规则未必完全抵销两腿资金占用。',
'毛头寸越大，结算机构承担客户损失越多|结算安排并不把扩大毛持仓后的经济亏损转给结算机构承担。',
'把两个合约合并命名即可取消各腿义务|把两腿称作一个组合不消除各腿在合同中的结算、资金和交割义务。']);
q('两市场合约不可直接交付','同类商品在甲乙交易所存在价差，但交割品级、地点不同。买甲卖乙后为何不能称无条件锁利？',[
'需验证货物能否转换并满足乙交付条件及相关成本|甲市场取得的货物未必符合乙的品质和交付地点，需要验证转换路径及成本。',
'只要商品中文名相同就可直接互交|同名商品可能有不同品质和地点标准。',
'两交易所报价使用同一币种便足够|同币种便于比较报价，但不能解决品级、地点及运输转换成本。',
'期货最后都会现金结算因此无需查交割|结算方式依合同，不能将所有期货假定现金结算。']);
section('futures1',6,'futures1-6','expansionDerivCases','案例F6：期货期权及企业采购保险的明示合同');
q('期货期权行权生成的仓位','题设买入的期货认购行权后形成行权价上的期货多头，不直接交付商品。到期实值并行权后，企业还应准备什么？',[
'新期货头寸的保证金、结算和后续处置|期权结束可能转为期货义务，不能把流程视为已完成实物采购。',
'无需任何资金，因为买方只付过权利金|原期权买方成本与行权后期货资金需求不同。',
'仓库立即自动收到商品|题设明确行权生成期货而非直接交付。',
'期货多头以后不再承担价格变动|新持仓会继续随期货价格产生盈亏。']);
q('采购商选择保险而非锁价','采购企业希望限制上涨成本，同时保留商品下跌带来的采购便宜，愿意支付前期费用。哪项更贴合目标？',[
'购买匹配采购数量和期限的认购期权|认购提供上涨保护而保留放弃权利享受下跌的可能。',
'买入等量期货并称保留全部下跌收益|期货多头在价格下跌时亏损，通常抵销采购便宜。',
'卖出认沽并称上涨有确定封顶|卖沽没有直接给采购上涨建立支付上限。',
'卖出认购以收入覆盖所有未来涨价|卖购对上涨亏损，不符合采购涨价保护方向。']);
q('期货认沽参照期货价格','题设认沽的标的是六月期货，执行价500，行权参考六月期货480，现货490。每单位内在价值应以什么计算？',[
'500−480=20|期权合同指定六月期货为标的，现货价格不是直接行权输入。',
'500−490=10|本题行权标的是六月期货480，现货490不进入该期权的内在价值公式。',
'490−480=10|这是期现价差，不是认沽执行收益。',
'480−500=−20|认沽收益为执行价减标的价并取非负。'],calc('Math.max(500-480,0)',20,'元/单位'));
q('销售底价与保险费的净口径','生产商买认沽保护售货价，行权价2000、保险费60，数量匹配且无基差，忽略其他费用。宣称净售价最低2000的问题是什么？',[
'净最低售价应扣保险费，为1940|执行价给毛收入底线，净收入还需减保费。',
'净最低售价应加保险费，为2060|买方支付保费，不能作为收入加回。',
'保险费已经包含在行权价中不必扣|题设分别列出两项，并无包含安排。',
'购买认沽完全不能保护销售价|购买认沽可以建立毛售货价底线，但要扣除企业实际支付的保险费。'],calc('2000-60',1940,'元/单位'));
q('低权利金不等于低保险缺口','企业比较平值认购和更便宜的远虚值认购，最终选后者却宣称保护强度相同。应补充说明什么？',[
'更高执行价意味着价格先涨一段仍由企业承担|低保费通常伴随更大未保护区间，应与预算容忍度匹配。',
'两者只要都是认购保护就完全相同|执行价决定触发水平和有效成本上限。',
'远虚值认购一定收益率更低|收益率取决于路径和支付成本，不能仅凭虚值程度确定。',
'付费低所以采购总成本一定更低|若价格大涨，高执行价可能使采购净成本更高。']);
section('futures1',7,'futures1-7','expansionDerivCases','案例F7：股指、利率、外汇的明示简化模型');
q('模型负Beta目标与套保授权冲突','公司明确只授权将股票组合Beta降至0至1之间，不允许净做空市场。模型建议目标Beta=−0.2，并算出相应卖出期货手数。执行员应如何处理？',[
"改用获准目标，或取得变更授权后再执行负Beta方案|负Beta表示组合净市场空头，模型计算正确也不能替代对目标方向的明确授权。",
"按模型手数直接执行，算法计算正确就满足现有授权|现有授权约束目标Beta的范围，准确计算一个越界目标仍不符合该约束。",
"分两天实施同样卖出量，避免单次下单显示负Beta|订单分拆不改变最终净市场暴露，不能以执行步骤绕过组合目标的限制。",
"只要保留原股票就能执行，期货造成的净空不在限制内|期货空头可超过股票的市场暴露，授权约束是组合净方向而非仅看是否仍持有股票。"]);

q('组合市值变化后的套保重估','股票组合上涨30%，期货合约名义价值仅上涨10%，Beta保持不变。若要维持相同对冲比例，原期货手数是否当然足够？',[
"需按两侧新的金额规模重算，未取整目标手数应增加|目标手数比例为1.30除以1.10，组合风险金额增长快于每手承载额；实际下单还需处理整数和限额。",
"原手数足够，只要Beta不变就可忽略两侧市值增幅差|Beta相同仍需对冲更大的组合金额，期货每手名义增幅较小，原数量不保证匹配。",
"应减少手数，因为股票上涨产生安全垫且期货已经亏损|历史盈亏和安全垫不能替代所需风险金额计算，减手数反而会进一步降低原目标覆盖比例。",
"仅按期货名义上涨10%调减手数，不必纳入股票上涨30%|这只更新对冲工具分母而不更新组合风险分子，遗漏了更大的股票金额。"]);
q('离散分红与连续股息率口径','题设指数持有成本模型已从现货价格减去已知现金分红现值，又用同一分红估计连续股息率再扣一次。主要错误是什么？',[
'同一分红收益重复进入持有成本扣减|离散现金流和连续股息率应按一致模型处理，不能重复算同一收益。',
'分红必须总计两次，分别给现货和期货|期货本身没有同一笔现货现金分红的双重领取。',
'任何持有成本模型都不能包含分红|收益是持有成本模型的重要输入。',
'只要改用更高利率就可纠正重复计算|调另一参数不能合理修复现金流重复。']);
section('futures1',7,'futures1-7','expansionDerivDV01','第2页 Method #2: Modified Duration；题设平行小变动');
q('债券久期相同但DV01不同','甲债券组合市值1000万元、修正久期5；乙市值2000万元、修正久期5。平行小幅利率变化下，两者DV01关系是什么？',[
'乙约为甲的两倍|DV01近似市值×久期×0.0001，久期相同仍需乘金额。',
'完全相同，因为久期相同|久期是相对敏感度，DV01是金额敏感度。',
'甲为乙两倍，因为金额越小越敏感|把相对与绝对敏感度混淆且方向错误。',
'无法比较，因为市值不参与DV01|题设市值与久期足以作简单近似比较。'],calc('(2000*5*.0001)/(1000*5*.0001)',2,'倍'));
section('futures1',3,'futures1-3','expansionDerivDeliveryInstrument','Why Did Convergence Fail及Storage Fees：交付凭证低费储存权与现粮不同；数字与期限均为教学假设');
q('交付凭证的低费持有权不能当作裸现粮','境外教学案例：到期期货交付可随时兑换同质粮食的凭证。现粮每吨100元，凭证103元；未来两个月持证每月收费1元，立即买现粮则每月储存费3元，买现粮不能自行获得凭证费率。买方恰两个月后用粮，忽略利息及其他成本。为何不能仅据103高于100就断言凭证更贵？',[
'凭证含低费持有权，两月总成本105低于现粮106|凭证103加两月费用2为105，现粮100加费用6为106；两者今日权利不同，不能只按裸粮价排除凭证溢价。',
'凭证和现粮最后都变成粮食，所以两月总成本仍为103和100|最终实物相同不使持有期间费用相同，比较未来同日取得粮食须纳入各自储存安排。',
'买入现粮后即可沿用凭证每月1元费率，总成本应为102|题设明确现粮不能自行获得凭证费率，不能在便宜的现粮买价上拼接另一资产专有的低费权利。',
'持有凭证等于立即兑换粮食，两月后也应支付6元储存费|凭证允许保持未兑换状态并按每月1元收费，强行假定立即提粮会删掉实际存在的持有选择。'],calc('(100+3*2)-(103+1*2)',1,'元/吨选择持证的两月总成本节省'));
section('futures1',7,'futures1-7','expansionDerivTreasury','Vocabulary：CTD、Yield、Conversion Factor；公式依题设');
q('转换因子不是可交割券市价','国债期货交割公式题设为期货结算价×转换因子+应计利息。某券转换因子0.95，分析员把它当作市价95，缺少什么？',[
'转换因子是公式中的标准化乘数，不替代该券实际报价|可交割券价格仍需从市场和相关现金流取得。',
'所有转换因子都表示债券剩余95天|转换因子是交割报价的标准化乘数，不代表剩余到期天数。',
'应计利息永远为零，因此0.95就是全价|应计利息依付息时点变化，且仍不能把因子当市价。',
'因子小于1表示该债券不能交割|可交割资格不由这个单一阈值决定。']);
section('futures1',7,'futures1-7','expansionDerivDV01','第2页 Calculating the DV01 of a U.S. Treasury Futures Contract');
q('最便宜可交割券切换的影响','利率变化导致另一只债券成为最便宜可交割券，原套保使用旧券的期货DV01估计。下一步应做什么？',[
'更新期货有效敏感度及套保比率，检查交割选择权影响|交割基准券变化可能改变期货风险映射。',
'保持原DV01，因为期货代码没变|合约代码不保证经济敏感度不变。',
'把原债券从市场中删除后模型继续有效|真实可交割集合和经济选择不能由删除数据解决。',
'只要转换因子已公布，切换不可能发生|固定因子不阻止相对持有成本随市场变化。']);
section('futures1',7,'futures1-7','expansionDerivFX','Identifying Currencies、Currency Pairs；题设人民币/美元报价');
q('出口收汇的报价方向','出口商三个月后收美元，以人民币/美元报价衡量收入，担心美元贬值。单就方向，应考虑什么？',[
'卖出对应期限美元远期或等价美元空头|美元下跌会降低人民币收入，美元空头可在该方向提供补偿。',
'买入美元远期以增加美元多头|会增加同向美元暴露，而非抵销收汇风险。',
'买卖方向由远期价格高低唯一决定|对冲方向首先取决于现金流和报价定义。',
'不必看报价，所有收款都应买入外币|不同币种收付风险不能用统一口号判断。']);
q('倒数汇率涨跌误读','报价从7.00人民币/美元升到7.20。系统另用美元/人民币表示，方向应怎样变化？',[
'美元/人民币下降|倒数报价由1/7变为1/7.2，人民币每单位能兑换的美元更少。',
'美元/人民币也同幅上涨|互为倒数的报价涨跌方向相反，百分比也不直接相等。',
'美元/人民币不变|当人民币/美元从7升至7.2，其倒数1/7.2低于1/7，不会保持不变。',
'必须先有美元现金流才能取倒数|报价单位转换是数学关系，不依赖是否持有现金。']);
q('外币利润与本币回报分离','以美元结算的期货赚1000美元，期间美元对本币贬值。经理说本币投资回报也固定等于1000美元原汇率金额，遗漏什么？',[
'结算和资金换回本币时的汇率影响|外币交易损益与本币计价最终回报不是同一口径。',
'期货盈利会自动锁住原汇率|除非另行对冲，商品或金融期货盈利不锁外汇转换价格。',
'只要平仓就无需再考虑资金币种|结束期货价格敞口后，留在账户中的美元仍有换成本币的汇率风险。',
'美元盈利必须改记为美元亏损|汇率影响需另核算，不能直接改写原交易币种盈亏。']);
section('futures1',8,'futures1-8','expansionDerivCases','案例F8：数据可得性、预测验证和可执行回测');
q('内部转库与总供应重复统计','同一日期、同一统计范围，货物从内陆仓转到港口：港口库存增加100万吨，内陆库存减少100万吨，无生产、消费或进出口。分析员只用港口数据断言社会总供应增加，正确判断是？',[
'库存地点改变，合并库存总量不变|范围内转移一增一减相抵，不能把内部物流当新增供给。',
'社会库存增加100万吨|只计目的地增加而遗漏来源地同步减少。',
'社会库存减少100万吨|只计来源地减少而遗漏目的地增加。',
'社会库存增加200万吨|把转出和转入都作为新增，发生重复统计。'],calc('100-100',0,'万吨总库存变化'));

q('可交割库存与社会库存区别','社会总库存上升，但符合交易所交割标准的仓单下降，近月合约偏强。分析时应怎样处理？',[
'区分库存可用性、品质、地点与交割资格|总量充足不意味着可用于近月交割的库存充足。',
'社会库存较大就证明任何交割都不紧张|总库存可能无法及时转为合格仓单。',
'仓单下降意味着所有社会库存也必须下降|两个统计集合不同，变化可不一致。',
'只看库存总吨数就能忽略期限和物流|交割时点和运达能力同样影响可用供给。']);
q('产能与实际产量混同','某行业公布新增年产能100万吨，分析员立即把未来一个月供应增加100万吨写入模型。主要应核对什么？',[
"结合投产时点、开工率，将年化产能换为当月实际产量|100万吨是全年生产能力口径，投产时间和利用率还会限制当月能实际形成的供应。",
"只将100万吨除以12，即可认定下个月必增加相应产量|除以12仅统一时间单位，未核实何时投产以及投产后能否达到所用开工率。",
"沿用行业历史开工率乘100万吨，无需再调整年化时间单位|开工率修正不能把全年产能转成一个月产量，仍遗漏年与月的量纲转换。",
"把新增产能全计入下月供给，再在后续月份扣除多计部分|未来会计式回冲不修复下个月供需判断，供应应按实际可生产的时间和数量归属。"]);
q('连续合约跳空与可交易收益','回测用未调整的连续合约，换月日远月高于近月200点，策略把这200点当作当日持仓盈利。主要错误是什么？',[
"拼接价差不是原持仓收益，应按真实合约重建移仓现金流|连续序列从近月换成远月会改变价格层级，原近月头寸并未因换标签而获得200点升值。",
"远月比近月高200点，买入远月时即可确认这200点盈利|在不同价格水平重新开仓不产生免费收益，应分别计算近月平仓和远月后续价格变化。",
"保留200点收益，只要把移仓买卖的手续费扣除就能修正|手续费之外仍有合约拼接产生的虚假价格变动，扣交易费用不能恢复正确收益路径。",
"本次200点先计利润，等下次移仓再自动反向冲回即可|之后期限价差的方向和金额不确定，假定未来自动冲回不能替代本次真实成交记账。"]);
q('复权价格用于成交的偏差','研究用后复权连续期货序列生成信号，却直接用复权价格计算每笔历史现金结算。为什么需分开信号与执行数据？',[
"信号可用复权序列，现金结算须核对真实合约报价和乘数|连续分析会调整历史价格层级，调整值可能从未实际成交，结算金额还依赖真实合约单位。",
"复权只改变图表外观，所以按其绝对价位结算仍等同实盘|复权会改变记录中的价格数值；即使保留部分涨跌关系，也不能把其价位当作真实成交价格。",
"只要补入手续费，复权成交价就能恢复真实合约现金结算|手续费是独立支出，补费用不会还原已被调整的历史报价和具体合约的现金流。",
"各期统一套用当前主力乘数，即可直接结算全部复权价格|统一乘数既未恢复真实成交价，也未核对历史具体合约单位，不能解决执行数据错用。"]);
q('修订数据造成前视偏差','策略回测使用后来修订的月度库存最终值，假设每月首发时已知。应怎样改进？',[
'使用当时可获得的数据版本和发布时间|事后修订信息不能进入历史决策时点。',
'只要修订更准确，就能用于任何历史时点|准确性与当时可得性是不同要求。',
'把交易时间提前一天以提高收益|交易时间提前后离数据首次公开时点更远，使用未来信息的问题更严重。',
'删除所有亏损月份解决修订偏差|删除亏损月份是按结果挑样本，既不恢复历史可得数据又夸大收益。']);
q('参数搜索后的样本外验证','研究员试验数千组参数，挑出历史收益最高者，用同一数据宣称稳健。最应补充什么？',[
"增加未参与选择的样本外检验，并评估多重尝试带来的偏差|在数千次筛选中获胜的同样本成绩容易高估真实能力，验证数据应未用于选参数或反复调试。",
"保留原最优参数，在同一历史数据上重复运行以确认稳健|相同数据与参数的重复结果主要验证执行一致性，不构成未参与筛选的独立收益证据。",
"先看全部参数的测试集表现，再将最高者称为样本外结果|一旦按测试成绩挑选参数，该数据就参与了选择，名称叫测试集也不再保持独立验证作用。",
"只报告最优参数附近仍然盈利的组合，即可排除筛选偏差|邻域稳定性可作辅助检查，但其也可能来自同段噪声，不能替代独立检验及搜索次数影响评估。"]);
q('同一风险因子的假多策略','组合把原油突破、原油动量、原油均线三个策略视为完全独立分散。应重点检查什么？',[
'底层持仓重叠、共同方向及压力期相关性|不同信号名称可能产生高度相似的真实敞口。',
'只要算法代码不同就能视作独立|不同算法可能同时建立相同原油方向，收益仍由同一个市场因子驱动。',
'只数策略数量即可确定风险降低比例|策略数量只有结合底层持仓及共同冲击下相关性，才能判断分散程度。',
'每个策略有历史盈利就不会同时亏损|共同市场冲击仍可能让它们同步亏损。']);
section('futures1',9,'futures1-9','expansionDerivCases','案例F9：场外合同、抵押品与风险治理的题设条件');
section('futures1',9,'futures1-9','expansionDerivCCR','CRE52.5、52.10–11：非现金抵押折扣；题设折扣并非监管参数');
q('抵押品折扣后的可用担保','题设提交债券市值100万元，抵押折扣20%，应计认可担保价值是多少？',[
'80万元|认可价值=100×(1−20%)，折扣为风险缓冲而非额外收入。',
'100万元|100万元是市值，题设认可担保价值还须扣除20%的折扣。',
'120万元|折扣用于减少认可担保金额而非增加市值，应得到80万元。',
'20万元|这是扣减额，不是认可担保余额。'],calc('100*(1-.2)',80,'万元'));
section('futures1',9,'futures1-9','expansionDerivCredit','SRP32.3抵押缓释残余风险；32.24(1)不利相关风险');
q('抵押品与风险同向恶化','企业A向银行B提交A自身发行的债券作为交易抵押；A信用恶化时，银行B对A的衍生品正敞口增加，同时抵押债券下跌。站在银行B角度，应识别什么？',[
'不利相关风险：敞口上升时担保价值同时下降|抵押品质量和对手履约能力并非独立，缓释可能在需要时变弱。',
'抵押面值不变所以担保能力不变|市值、流动性和信用质量决定可实现缓释。',
'有抵押就完全不存在违约风险|抵押价值不足和处置损失仍可能存在。',
'两项变动可无条件相互抵销|敞口扩大与担保缩水都使信用风险恶化。']);
section('futures1',9,'futures1-9','expansionDerivCCR','CRE52.3、52.10：当前重置成本；不计算完整违约风险暴露');
q('名义本金与重置成本区别','两份场外互换名义本金均一亿元，一份当前正市值50万元，另一份500万元。仅比较当前正重置成本，哪份敞口更大？',[
'第二份，当前正市值更高|同名义本金不代表相同当前信用敞口，还须考虑净额和抵押等条件。',
'完全相同，因为名义本金相同|名义本金是计算基数，不是当前合约资产价值。',
'第一份，因为正市值较小更危险|这与题设只比较当前重置成本的口径相反。',
'两份当前敞口都是一亿元|把名义本金全部当即期应收金额。']);
section('futures1',9,'futures1-9','expansionDerivCCR','CRE52.7–8：有效净额协议和法律可执行性；题设跨实体条件');
q('不同法律实体净额的边界','甲公司对银行A有正市值，甲的子公司对同银行有负市值，但没有跨实体净额协议。合并风险报表可否直接按两者抵销信用敞口？',[
"不能直接抵销，须有覆盖相应主体且可执行的净额基础|共同集团的会计合并不自动建立跨主体债权抵销权，应核实协议效力及所涵盖主体。",
"可以直接抵销，币种相同已满足跨实体信用净额条件|同币种便于金额比较，但没有改变谁持有债权和谁承担债务，不会自行生成跨主体净额权。",
"可以直接抵销，同一银行且同日到期已足以建立净额权|对手和日期匹配不补足跨实体法律安排，仍不能无条件抵销不同主体的债权债务。",
"可以直接抵销，合并财务报表范围已等同法律净额范围|财务报表合并服务于会计展示，法律可执行净额需要另行判断，不由合并范围自动决定。"]);
section('futures1',9,'futures1-9','expansionDerivCredit','SRP32.20–21：当前/未来敞口及压力测试；情景概率由题设区分');
q('压力测试概率的误读','风险报告称某极端情景下损失1000万元，领导问这是否说明发生概率一定为1%。应如何回答？',[
'情景损失本身不隐含固定概率，需要另有概率模型支持|压力测试给出条件情景结果，不能凭损失额反推概率。',
'是，所有压力测试都约定1%概率|压力场景选择方法不同，没有这种统一概率。',
'是，只要损失很大概率就必为1%|1000万元是给定情景下的损失，发生概率需独立假设或模型估计。',
'既然不知道概率，情景测试完全没价值|情景仍可检验资金承受和应急措施。']);
q('VaR时间尺度与持仓变现期','机构报告一天VaR，却持有可能需要两周才能退出的薄弱合约。最应补充什么？',[
'与实际变现期限匹配的风险及流动性压力评估|一天价格风险不能完整代表长时间退出期间的损失。',
'一天VaR乘持仓代码数即可|代码数量不等于时间和流动性调整。',
'一天VaR天然适用于任意持有期限|时间尺度改变风险分布及执行成本。',
'只要VaR数值低，就证明两周内随时可退出|VaR描述给定条件下的价格损失分布，不能承诺两周内有足够对手盘。']);
section('futures1',9,'futures1-9','expansionDerivCredit','SRP32.23：独立审查、数据、估值及流程；企业场景为原创治理应用');
q('交易与核算由同一人控制','小企业让同一人谈合同、下单、确认对手账单并核算估值，声称效率最高。主要应增加什么？',[
'独立确认、估值复核和授权制衡|不相容职责分离有助发现错误、隐瞒及利益冲突。',
'只要求该人每天口头保证没有错误|口头承诺不能替代独立证据与复核。',
'把报表名称改为审计报告|独立审计需要独立人员、程序及证据，改报表标题不构成复核。',
'仅提高该人的交易额度|扩大权限会增加而非降低集中控制风险。']);
section('futures1',9,'futures1-9','expansionDerivCases','案例F9末：题设条件性收款与确定付款');
q('远期现金流净额不等于风险消失','企业有同日同币种收付各100万美元，但付款确定、收款取决于客户验收。财务将外汇风险净额记零，最应补充哪项？',[
'收款不确定及可能延迟导致的数量和时点错配|只有实际可靠匹配的现金流才可抵销，条件性回款需另设情景。',
'金额相等就保证永远没有风险|发生概率和到账时间同样影响敞口。',
'只要同币种就可忽略合同条件|币种匹配不等于义务确定性匹配。',
'把付款也记为不确定就能消除风险|不能通过记账改变已确定的付款义务。']);

section('futures1',2,'futures1-2','expansionDerivRoll','Understanding Futures Expiration & Contract Roll：到期处置和移仓');
q('最后交易日与首次通知日区别','题设境外实物合约最后交易日在月底，但空头可能在更早首次通知日起发出交割通知。客户不准备交割，退出计划首先应核对什么？',[
'首次通知日、最后交易日及经纪商更早的持仓限制|仅看最后交易日可能在此前已进入交割义务风险期。',
'只在最后交易日收盘前处理即可|题设明确更早可能收到或涉及交割通知，不能只看最终交易日。',
'把期货浮盈转出就自动取消交割资格|资金转出不是平仓，无法自行解除合约交割风险。',
'只要不主动申请就一定不会交割|实物期货的义务依合同通知和持仓规则，不仅取决于主观意愿。']);
q('移仓不是延长原合同','企业平掉六月期货并建立九月期货，报表称六月合约到期日被延长。应怎样更正？',[
'旧合约已平仓，新合约是独立交易，分别记录成交与成本|移仓以两笔交易重建期限，不是修改既有标准合约条款。',
'九月合约自动继承六月所有成交价|新合约以新成交价建仓，不继承旧价格。',
'因为经济方向一样，旧头寸无需记平仓|方向连续不等于法律和会计上同一份合约继续存在。',
'移仓后原六月已结算损失自动撤销|历史已结算损益不会因新建仓而被取消。']);
q('现金结算仍有最后结算现金流','客户持有现金结算期货，认为没有运货就无需准备到期资金。应提醒什么？',[
'仍需按最终结算价格结清损益和相关资金要求|免去实物交付并不免去货币结算义务。',
'现金结算只收回最初保证金且不计损益|最终价格仍决定未结损益，保证金不是固定赎回本金。',
'现金结算到期后头寸永久继续|合约按规定终止，不能把现金结算理解为无限展期。',
'有浮亏也可等未来行情恢复再结算|到期最终结算不能由客户单方推迟以等待价格反转。']);
q('移仓价差与双腿执行计划','套保将到期，近月流动性下降、远月逐步活跃。经理准备逐腿移仓，最需要控制什么？',[
'移仓窗口、成交价差和暂时未匹配的方向敞口|两腿不同时完成会留下临时风险，流动性迁移会影响成本。',
'只要到期前最终两腿都做完，中途敞口无需管|中途行情可造成损失或追加保证金，不能忽略。',
'只比较两个月历史最高价即可决定成本|实际移仓成本取决于可执行报价与成交时点。',
'把移仓费用排除在套保评价之外|为延续保护而发生的执行成本影响实际套保效果。']);

// Batch B: valuation and operational decision gaps, authored independently from Batch A.
section('options',3,'pricing','expansionDerivOptionValue','公开Summary：无套利价格边界与复制；题设欧式、无摩擦模型');
q('认购价差价格超过折现宽度','同到期欧式认购价差到期付款始终在0至10元之间，同期支付10元的零息债现值9.5元。无摩擦且允许做空，价差现价10.2元，哪项判断正确？',[
'价差超过其确定上界现金流的现值，违反该模型的价格边界|买入9.5元债券、卖出10.2元价差，初始收款且到期债券足以覆盖任何付款。',
'只要价差低于现货价格就一定合理|现货上界过宽，价差还受执行价宽度折现值的约束。',
'价差到期最多10元，所以现在10.2元只是正常时间价值|时间价值不能使支配于确定10元付款的资产比该零息债更贵。',
'必须知道标的上涨概率才能判断上界|逐状态付款上界已足以构造支配关系，不需实际概率。']);
q('凸性检验与负成本蝶式','同到期同标的认购K=90、100、110，价格分别14、10、4，无费用零利率。买两侧各一份、卖中间两份，哪个事实说明价格曲线存在套利问题？',[
'初始净收2元，等距长蝶式到期价值始终非负|14+4−2×10=−2，非负未来现金流却能在建仓收款。',
'三个价格随执行价递减，已经满足全部无套利条件|单调递减只是部分约束，等距执行价的认购价格还须满足凸性条件。',
'初始付2元，未来一定赚更多|初始现金流符号错误，而且蝶式未来可能为零。',
'只有标的恰到100才存在无套利约束|无套利约束比较所有情景，非负到期价值不只在峰值成立。'],calc('2*10-14-4',2,'元初始净收入'));
q('欧式认沽现值下界与立即行权值','无分红欧式认沽K=100，标的10，到期支付100的零息债现值95，认沽价87。仅凭87低于当前立即行权差额90，能否断言套利？',[
'不能；欧式不能立即行权，相关简单下界是95−10=85|87高于折现行权价减现货的下界，仅这个比较不能证明违规。',
'能；所有欧式认沽必须至少等于未折现K−S|把立即行权权利套给只能到期行权的合约。',
'能；认沽必须至少等于执行价100|执行价是到期售价，不等于任何状态下的当前期权价值。',
'不能；任何认沽价格都不存在下界|下界依然存在，只是本题应考虑付款时点与行权方式。']);
q('认购高于现货的支配套利','题设非负标的、无分红、零利率、允许做空且无摩擦。现货100，欧式认购执行价80而价格105。买现货并卖该认购，最关键的套利性质是什么？',[
'初始收5元，到期无论是否行权，剩余财富均非负|认购付款max(S−80,0)不超过S，现货可覆盖全部期权付款。',
'只有到期标的涨过105才不亏|忽略现货与认购空头相互覆盖及初始净收入。',
'认购价格可高于现货，只要波动率足够大|普通认购付款逐状态不超过标的价值，模型内有支配上界。',
'卖出认购必须再借入执行价80才能覆盖|持有完整标的已经覆盖交付，不需要再借80来证明该支配关系。']);
q('欧式期限单调性的反例条件','题设标的已为0并确定保持0，执行价100，利率为正，欧式认沽只能到期收100。一年现金现值95，两年现值90。哪项结论成立？',[
"应分别按95和90估值，两年认沽在这里比一年便宜|没有价格不确定性时两者只是不同到期的100元现金请求，正利率折现使较晚收款更便宜。",
"应都按95估值，因为执行价和最终收款金额完全相同|付款时点不同会改变现值，相同名义金额不足以给出相同的当前价值。",
"两年应至少95，因为额外一年必增加可选择的行权时点|欧式仅能在自身到期日行权，延长期限没有提供在原一年时点提前收款的选择。",
"一年为95、两年为100，因为较长期权应恢复执行价面值|100是两年后收款金额，不是今天价格，不能只对一年付款折现而不折现两年付款。"]);
q('美式权利集合与欧式比较','同标的同执行价同到期、无摩擦且其他条款完全相同，甲可随时行权，乙只能到期行权。若甲比乙便宜，最直接的价值判断依据是什么？',[
"甲保留到期选择，多出的提前行权权利不应使其更便宜|甲可选择只在乙允许的时点行权，其他条款相同下其权利集合包含乙。",
"甲提前付款的机会更多，所以应为这项权利支付价格折让|提前行权是可选而非必须，甲可以不提前支付，不能把选择权当强制负担。",
"甲必须严格贵于乙，因为每一个额外行权日都有正价值|新增选择有时不被最优使用，价值可为零，因此只保证甲不低于乙而非必严格更贵。",
"甲乙期末支付相同，所以提前行权条件完全不影响价值|允许在到期前行权会改变可实现现金流的时点与状态，不能仅比较到期支付。"]);
section('options',3,'pricing','expansionDerivBinomial','公开Summary：单期复制、无风险组合与风险中性定价');
q('单期复制的股票和现金腿','零利率模型中现货100，到期只可能120或80；认购K=100。哪一组合能逐状态复制一份认购到期付款？',[
'持有0.5份现货并借入40元|上涨时60−40=20，下跌时40−40=0，与认购付款一致。',
'持有1份现货并借入100元|上下状态为20和−20，下跌时不能复制认购的零下限。',
'只持有10元现金|两状态现金相同，不能复制0与20的不对称付款。',
'卖空0.5份现货并存40元|产生−20与0，方向与认购多头相反。'],calc('.5*100-40',10,'元复制初始成本'));
q('二叉模型的无套利增长区间','单期标的下行总增长因子0.9、上行1.1，无风险总增长因子却为1.2，假设可自由借贷做空。程序反推出风险中性上涨概率1.5，正确诊断是？',[
"先修复无套利增长区间，1.5不能直接作为定价概率|无风险增长高于标的所有状态增长，可产生支配套利；异常概率是输入矛盾的症状。",
"将1.5截到1，保留原增长因子继续进行精确复制|截断概率会破坏现价与未来状态的无套利对应，不能保留原复制关系。",
"将1.5改为1.5除以2.5，归一成60%就能维持原复制|人为归一化未改变底层资产和无风险资产的支配矛盾，不能确保复制价格仍一致。",
"提高期权执行价，以降低期权收益修复底层增长矛盾|执行价改变的是期权付款，不能修复底层增长范围低于无风险增长的问题。"]);
q('主观上涨概率与复制价格分离','两位分析师使用完全相同的单期上下状态、现货和无风险利率，一位主观上涨概率80%，另一位20%。在可完全复制的无套利模型中，两人的期权理论价应如何比较？',[
'复制价格相同，主观概率可影响投资意愿但不改变同一复制成本|风险中性定价由市场可复制关系决定，不直接使用各人的实际预测概率。',
'看多者给出的复制成本一定四倍|概率比不能改变已固定的股票、现金复制组合成本。',
'看空者必须把认购定价为零|低主观概率不意味着上行状态不存在或权利无价值。',
'必须先平均两人的概率才可定义无套利价格|完全复制不依赖两位分析师达成主观概率共识。']);
q('三个状态对两种资产复制的限制','一期模型有标的80、100、120三个可能终值，认购K=100付款0、0、20；只允许股票和固定现金。为什么通常不能用同一组股票数量与现金精确复制？',[
'股票加现金是终值的直线函数，不能同时拟合三个非共线付款点|两种资产提供的线性结构不足以复制此三状态弯折付款。',
'因为现金在三个状态有三种不同终值|无风险固定现金的终值相同，问题是可复制维度不足。',
'只要把股票数量设为0.5就会自动拟合中间状态|0.5股票减40在100时为10，而认购实际付款为0。',
'任何三状态模型中的期权都不值钱|不能精确复制不等于没有经济价值，只是不能用这两种资产唯一复制。']);
q('二期模型中的自融资调整','二期树中第一步上涨后复制Delta由0.5升至1。策略要继续复制，追加0.5份股票的资金通常如何处理？',[
'按模型用现金账户借贷或卖出其他复制资产融资，并计入后续余额|动态复制必须完整跟踪再平衡现金流，不能免费增加股票。',
'模型默认交易所免费赠送新增股票|复制策略不包含免费资产来源，必须满足资金平衡。',
'原初始权利金自动足额支付任意未来加仓|现金余额需随利息和调整更新，不能把初始收入反复使用。',
'只更新Delta数字，不改变资产持有即可复制|风险指标变更本身不产生实际对冲仓位。']);
section('options',3,'pricing','expansionDerivOptionValue','公开Summary：定价输入与价格边界；数值诊断条件由题设给出');
q('不合法市场价格的隐波求解','无分红无摩擦模型中认购现价高于标的价，系统仍尝试反解正隐波。最恰当的诊断顺序是？',[
"先核对输入和价格边界，确认合法后再进行隐波反解|若报价在模型可达范围之外，应识别单位、时点或价格问题，不能把无根强行当成隐波值。",
"增大求解的隐波上限，直到认购模型价突破标的现价|普通无分红认购模型有现货价格上界，放宽数值搜索区间不能突破经济约束。",
"将无根结果返回为零，视作市场认为标的没有波动|求解不存在与真实零波动是不同状态，返回零会制造错误的经济解释。",
"先将报价截到模型上界，再标记为原报价的精确隐波|截价改变了待解释的市场输入，不能把对修改后价格的结果称为原价格的精确解。"]);
q('低Vega区域的隐波不稳定','深度虚值临近到期期权价格只变动一个最小档，反解隐波却变化很多。题设局部Vega极小，合理解释是什么？',[
"低Vega使反解对价格误差敏感，隐波可能大幅跳动|局部隐波变化近似价格变化除以Vega，小分母会放大离散报价和输入误差。",
"低Vega使价格更敏感，所以一个档位只需很小隐波变化|Vega小表示正向价格对隐波不敏感，固定价格变动反而需要更大隐波变化才能解释。",
"低Vega使反解更稳定，因此可忽略一个档位的报价扰动|正向敏感度低不等于反向估计稳定，隐波数值可能对一个档位就高度敏感。",
"缩短剩余期限就能一律提高Vega，因而消除反解跳动|深度虚值且临近到期时缩短期限未必提高Vega，不能保证改善该反解问题。"]);
q('隐波区间不能伪装单点成交','同一合约买卖价分别反解隐波18%和24%，没有中间价成交。报告最适宜怎样表达？',[
'报告买卖价对应隐波区间并说明中间估值只是参考|报价区间反映执行成本和不确定性，单点不能伪装真实成交。',
'直接宣称市场已在21%隐波成交|算术中点不证明存在该价位的成交记录。',
'选择24%并宣称所有客户均可按此卖出|24%来自卖价，客户出售面对买价，执行方向相反。',
'把区间宽度6%作为期权明天收益率|隐波报价区间不是标的或期权未来收益预测。']);
q('同执行价看涨看跌隐波的可比性','研究员用同标的、同到期、同执行价欧式认购和认沽校准同一无套利模型，但分别输入不同分红率，得到两种隐波后宣称市场严重偏斜。应先检查什么？',[
"统一分红等输入及报价时点，再检验平价和隐波差异|相同执行价的隐波差异可能由输入不一致制造，不能直接归为跨执行价偏斜。",
"保留不同分红输入，取两个反解隐波均值作为公平真值|简单平均不会消除平价输入冲突，也无证据使结果成为唯一公平值。",
"改选不同行权价的两份期权，以此排除波动率偏斜影响|不同执行价本就是偏斜可能存在的维度，换执行价不能修复原来的输入不一致。",
"只要同标的同到期，分红输入不同也不影响隐波可比性|隐波是依赖全部估值输入的反解量，标的与期限匹配不能消除分红假设差别。"]);
q('远期平值与现货平值区别','现货100，但同到期远期价格105。交易台按K/F定义远期价值状态，却把K=100标作远期平值。正确处理是？',[
'按既定远期口径，K=105才是远期平值|现货平值使用S，远期平值使用F，两种口径应明确区分。',
'无论利率分红如何，所有平值都只能K=100|忽略远期价格与现货价格可能因持有成本不同。',
'K=100和105在同一远期口径下都严格平值|同一基准F只有一个相等执行价。',
'应把远期价格改成现货100以保留标签|不能为标签一致而篡改市场输入。']);
q('方差时间插值与波动率平均','模型规定按总方差W=σ²T线性插值。半年隐波20%、一年30%，估计0.75年时，应先插值什么？',[
'半年W=0.02与一年W=0.09，再由插值W除期限开方|模型明确插值对象是总方差，不能先直接平均百分比。',
'直接用(20%+30%)/2并称完全符合该规则|波动率的算术平均一般不等于总方差线性插值结果。',
'把20%和30%相加作为0.75年隐波|相加未考虑方差和期限，量纲口径错误。',
'只插值到期日，隐波固定20%即可|这没有使用一年期市场给出的总方差信息。'],calc('Math.sqrt((.02+.09)/2/.75)',Math.sqrt(.055/.75),'年化波动率'));
section('options',3,'delta-gamma','expansionDerivCases','案例B2：题设多风险因子线性系统与风险归因');
q('同时中和Gamma和Vega的可解性','组合需抵销Gamma=10、Vega=40。允许的两种对冲期权每份(Gamma,Vega)分别为(1,2)、(2,4)，可正负持仓。为何仍无法同时精确中和？',[
'两种工具的Vega/Gamma都为2，不能复制目标比率4|工具风险向量共线，增加数量也不能得到独立的两个风险方向。',
'因为对冲工具不能卖空|题设允许正负持仓，限制来自向量结构而非卖空禁令。',
'只需各买10份就可消除正Gamma|买入正Gamma会增加而非抵销既有正Gamma。',
'把第二工具单位乘100即可改变风险比例|整体缩放不改变Vega/Gamma比率，仍然共线。']);
q('可解双风险对冲的方向核验','组合Gamma=6、Vega=20，工具A每份(1,2)，工具B每份(1,4)。忽略其他风险，哪组交易同时消除两项？',[
'卖出A两份、B四份|Gamma减少2+4=6，Vega减少4+16=20，两式同时满足。',
'买入A两份、B四份|这会增加两项风险，符号与抵销目标相反。',
'卖出A六份，不用B|Gamma可归零，但Vega仅减少12，仍余8。',
'卖出B五份，不用A|Vega可归零，但Gamma只减少5，仍余1。'],calc('20-2*2-4*4',0,'剩余Vega'));
q('模型归因残差不能直接认定舞弊','账面期权损益−1000元，一阶Greeks归因合计−850元。审查员直接认定余下150元为盗用资金，合适的第一步是什么？',[
"先对账费用、非线性和估值时点，再追查残差来源|一阶Greeks不是完整资金审计，残差可能由执行、模型遗漏及输入差异造成，应结合真实流水核对。",
"按Greeks原有比例分摊150，归因加总相等就可结案|强制使加总吻合不说明差异来源，可能掩盖真正的模型、数据或交易问题。",
"把150全部归入Theta，时间经过足以解释任何差额|时间经过不能为任意金额提供证据，须核对实际时间敏感度及其他可能来源。",
"仅据150残差确认资金被转走，无须对照真实现金流水|价格归因差额不是现金转移的直接证据，应先区分估值解释与资金账实差异。"]);
q('外币期权Delta对冲后的汇率敞口','人民币报告账户持有美元计价期权，已用美元标的中和标的Delta，期权净美元资产价值仍为5000美元。若美元兑人民币变化，还要考虑什么？',[
'净美元资产换算价值的外汇敏感度仍存在|中和标的价格Delta不等于中和报告币种与资产币种之间的汇率风险。',
'标的Delta为零后任意汇率变动都无影响|风险因子不同，单一标的对冲不能消掉外币资产换算。',
'5000美元自动转换成固定5000元人民币|币种和汇率不能忽略，数值相同不代表价值相同。',
'只要期权未平仓，就不存在外汇资产价值|未平仓合约也有可计量外币价值及相关风险。']);
section('options',4,'risk','expansionDerivCases','案例B3：题设报告阈值、账户限制和执行预算');
q('动态对冲频率与执行成本权衡','研究模型每秒将期权Delta调为零，但实际每次交易须跨买卖价差，累计费用已超过风险预算。改进方案应优化哪项权衡？',[
'对冲间隔中的残余价格风险与再平衡交易成本|更频繁调整可降低部分风险，却增加成本，应在明确目标下比较。',
'越频繁越能保证净收益，因此无需计算费用|连续无摩擦模型的结论不能忽略现实执行支出。',
'只要一周调整一次就保证没有成本和风险|降低频率仍有交易成本，且可能留下更大的期间暴露。',
'直接把每次费用记为零以保留原算法|修改报表不能消除真实交易成本，也无法满足预算。']);

q('冻结隐波的Delta与总价格斜率','系统甲扰动标的时保持隐波不变；系统乙扰动标的时同时按给定规则上调隐波。两者算出的期权价格斜率不同。比较模型前最应确认什么？',[
'扰动时哪些输入保持不变；乙的斜率还含隐波变化贡献|标准偏Delta固定其他输入，联合扰动会把Vega等影响纳入总变化。',
'同一期权的任何扰动斜率必须完全相同|不同输入变化路径得到不同总敏感度，并不自动说明程序错误。',
'只需增加显示小数位即可消除差异|这里差异来自模型情景定义，不是数值显示精度。',
'把系统乙的隐波变化贡献也命名为固定隐波Delta即可|重命名不会统一条件，会掩盖风险指标比较口径。']);

q('平仓容量与对冲容量的差别','账户卖出100张认购，当前Delta相当于只需买20000份现货对冲。经理把买到20000份称为足额实物履约准备，忽略每张10000份单位。应纠正什么？',[
'Delta对冲数量不是被全部指派时的100万份交付数量|局部价格风险覆盖与全额合同履约需要不同，不能把Delta份数当证券准备上限。',
'只要目前Delta很低，被指派数量永远不会超过2万份|Delta会变化，且不是最大行权比例的合同承诺。',
'期权卖方持有任何现货都能免除剩余义务|部分现货不足以履行全部可能交付数量。',
'把Delta改为1就会自动产生缺少的股票|修改指标输入不创造真实可交付证券。']);
q('隔夜风险限额与日内合规的区别','公司允许日内卖出期权，但禁止隔夜裸露负Gamma。交易员收盘前仍有未成交回补单，称日内曾经合规因此可离开，正确判断是？',[
"确认实际平仓或获准保护，使收盘持仓满足隔夜限制|隔夜标准针对真实收盘后风险，已报但未成交的回补意图不能替代头寸处理。",
"保留已报回补单即可，将其未成交数量从隔夜风险扣除|未成交回补没有减少既有空头，先扣挂单会低估实际隔夜负Gamma。",
"只要日内平均Gamma合规，就可用均值代替收盘状态|日内平均指标不能替代题设针对隔夜实际持仓的特定约束。",
"把回补单设为次日开盘有效，即可视作已覆盖当夜风险|明日可能成交的订单不在当夜提供对冲，仍需管理当前存续的裸露负Gamma。"]);
section('futures1',7,'futures1-7','expansionDerivForward','公开Summary：合约定价与存续期价值，题设无摩擦模型');
q('远期约定价格不会随估值改写','企业原约定一年后按100购买资产，半年后同剩余期限新远期公平交割价升为110。会计把旧合同交割价也改为110，应该怎样纠正？',[
'旧合同仍按100交割，110用于评估其当前价值或新交易|合同约定价和当前同期限新合约定价不同，估值更新不修改原义务。',
'市场价格更新后所有旧合同自动改价|标准估值变化不会自动重写已订立合同。',
'旧合同既然不改价，当前价值也只能为零|固定交割价仍可因市场变化产生正负市值。',
'110是当前现货价，可以直接替换所有现金流|题设给的是新远期交割价，并非现货报价。']);
q('远期替换价差的贴现时点','旧远期多头交割价100，同日到期的新远期价110。题设剩余期限折现因子0.95且无摩擦。用反向新远期锁定10元到期差额，旧远期当前价值应为多少？',[
'9.5元|反向组合将到期净收入锁为10，当前价值为10×0.95。',
'10元|这是到期金额，尚未按题设折现到估值日。',
'104.5元|把新交割价整体折现后当成旧远期价值，未扣原合同义务。',
'−9.5元|旧多头可按较低100买入，相对新市场110是正价值。'],calc('(110-100)*.95',9.5,'元当前价值'));
q('远期估值只包含剩余现金收益','某股票已于昨日支付分红，今天估值到年底的远期。模型又从今天现货价格扣掉昨日已支付的分红现值，错误是什么？',[
"今日现价已在分红之后，不应再扣已支付的历史现金流|当前远期估值应调整估值日之后至交割之间的持有现金收益，昨日已支付金额不属于剩余期间。",
"把昨日分红折算到今天后再扣除，就可消除现金流时点问题|折算数值不改变款项已经支付的事实，仍把估值前现金流重复放进未来持有路径。",
"先把昨日分红加回现价，再直接融资至年底作为远期价格|这人为恢复了过时的含息价，却未同步移除已经支付的现金收益，仍会扭曲今天的复制成本。",
"未来分红也统一不再扣除，因为股票今天已经完成过除息|本次除息只消化本次支付，若未来还有分红，仍应按剩余持有期的现金流单独考虑。"]);
q('预付仓储费的融资成本','现货100元，交割前仓储费5元必须今天预付，无其他收益。融资至交割增长因子1.04。题设完全可复制，理论交割成本是多少？',[
'109.2元|现货和预付仓储均需融资：(100+5)×1.04=109.2。',
'109元|100融资至104后再加5，漏掉预付仓储费的0.2融资成本。',
'105元|把融资成本全部遗漏，只合并当日现金支出。',
'99.2元|仓储是持有成本，应加到采购资金而不是扣除。'],calc('(100+5)*1.04',109.2,'元/单位'));
q('远期与期货现金流路径的利息差','题设两日持仓期货首日结算赚100元，第二日亏100元，首日盈利可按两日之间1%利率投资；对应远期到期价差为0。忽略其他因素，两者终值现金差如何？',[
'期货多1元，来自中间结算款的利息|100×1.01−100=1，而一次到期净额结算没有该中间现金流。',
'完全相同，因为两天价格变化相加为0|原始价差相加为零仍可能有现金流时点的再投资差异。',
'期货多100元，因为只计算盈利日|第二日亏损仍须支付，不能删除不利结算。',
'期货少1元，因为所有结算盈利都收费|题设现金获得利息而非被收利息，符号错误。'],calc('100*1.01-100',1,'元终值差额'));
q('负期货价格下的绝对损益','题设某商品期货允许负报价，每手10单位；多头从5元持有至−3元，按平仓价减开仓价计算多头损益且不计费。哪项记账正确？',[
'每手亏80元，不能把价格零点当自动止损边界|(-3−5)×10=−80，题设未规定标的价零以下免除损失。',
'每手最多亏50元，因为价格不能低于零|这与题设允许负报价的特殊合约条件冲突。',
'每手赚80元，因为负价格代表卖方倒贴|既有多头从5到−3是价格下降，方向不能反转。',
'每手亏3元，因为只看终值绝对值|损益需比较开仓与平仓价格并乘合约单位。'],calc('(-3-5)*10',-80,'元/手'));
q('结算后市值归零不抹去累计损益','题设期货每天现金结算后持仓账面合约价值重置为零，累计已有盈利5000元进现金账户。分析员称合约价值零所以从未盈利，问题是什么？',[
'重置的是剩余合约市值，已结转现金盈利仍然存在|期货价值和累计结算现金流需合并核算，不能只看重置后的合约行。',
'累计盈利必须随重置一起退回交易所|现金结算完成不意味着已赚取资金被自动撤销。',
'应把期货名义本金全部记为盈利|名义本金是风险计算尺度，不是可确认收益。',
'既然合约市值零，就不再需要保证金|未来价格变动仍可造成义务和资金需求。']);
q('全额资金化期货的收益组成','投资组合以全部现金作抵押并买入期货，本期期货结算亏2万元，现金抵押收益0.5万元，无费用。只报−2万元会遗漏什么？',[
'抵押现金收入，组合净结果为−1.5万元|全额资金化策略应合并期货现金损益与可归属的现金持有收益。',
'保证金名义本金也是新增收益|原投入本金不是当期盈利，不能与现金利息混同。',
'现金收益使期货结算亏损自动失效|交易亏损仍真实存在，只在总组合中被0.5部分抵销。',
'抵押现金一旦被冻结就绝不可能有收益|是否有收益依题设安排，本题已给出0.5万元。'],calc('-2+.5',-1.5,'万元组合损益'));
section('futures1',5,'futures1-5','expansionDerivCarry','Contango/Backwardation正文：融资、仓储、便利收益；原创约束案例');
q('便利收益不是可支付的现金股息','工厂持有关键原料可避免停产，模型把这种便利收益估计为年化8%。财务将8%直接录成银行账户将到账的利息，如何修正？',[
'便利收益是持有实物的经济好处，不一定形成可收现金|避免停产的价值不能当作无条件到账的现金票息融资支出。',
'8%一定由交易所按月支付|便利收益并非交易所承诺的付息合约。',
'不能观察到现金就说明持有库存毫无收益|避免缺货和保持生产具有经济价值，即使无独立现金付款。',
'应把便利收益当成仓储费支付给仓库|收益和成本作用相反，不能直接互换费用名称。']);
q('消费品反向套利的供货约束','工厂库存能保证连续生产，远期明显低于现货。研究员建议卖光实物再买远期，声称没有任何代价，遗漏了什么？',[
'等待远期交付期间可能断料，失去库存便利收益|同样到期资产数量不意味着中间期间可用性等价。',
'远期合约会立即交付商品以供今日生产|远期交付在未来，不能假定提前供货。',
'远期价格低就表示所有储存成本为负|曲线还受库存可用性和供需因素影响。',
'只要到期取得相同吨数就可忽略生产停顿|中间停产损失是复制策略的实际经济差异。']);
q('不可经济储存商品的模型边界','某电力产品无法以题设规模经济储存，分析员仍用买现货、存半年、卖远期的现金套利模型要求期货精确等于融资后现货。最主要缺陷是什么？',[
"大规模储存路径不可实施，题设现金套利等式缺少复制基础|持有成本复制要求能买入、保存并在未来交付相同经济资产，物理路径不可行时不能强求该等式。",
"将仓储费用设为零后，买入并持有半年的复制就仍然成立|费用为零是数值假设，不能使本来无法经济储存的电力在所需规模上保存半年。",
"只需改用实际融资利率，就可略去储存限制继续精确套利|更准确的融资成本没有修复关键物理环节，仍无法建立题设声称的完整复制路径。",
"只要远期采用现金结算，就不必核对现货持有复制能否实施|现金结算改变交收方式，却不自动使今天现货变成半年后的电力供给，也不保证该持有成本等式。"]);
q('升水结构不保证未来现货上涨','现货100、半年期货105，题设资金与仓储成本足以解释5元差额。有人断言市场已保证半年后现货至少105，正确评价是？',[
'曲线价差可反映持有成本，不能等同未来现货价格的保证|当前无套利关系与未来实际现货结果是不同命题。',
'期货高于现货说明半年后现货必须更高|价格发现不构成对未来状态的确定承诺。',
'只要有仓储成本，任何期货都应低于现货|持有成本一般提高复制交割成本，方向相反。',
'105与100之间必然存在5元无成本套利|题设已给足以解释价差的资金与仓储成本，不能忽略。']);
q('季节性跨月价差的错基准','天然气冬季供暖月通常需求高，夏季月较低。策略把冬夏价差与同一夏季相邻月份价差均值直接比较并称异常，首要缺陷是什么？',[
'比较对象季节结构不同，应匹配相同交付季节和期限关系|月度供需特征可能构成合理价差，不能用不相当样本当均衡基准。',
'所有月份都交易同一商品，季节因素应为零|同一商品不同月份可面临明显不同的供需和储存约束。',
'只要用更长历史样本就不必匹配季节|长样本混合不同比较对象仍可能产生偏差。',
'把冬月价格改成夏月价格即可验证策略|改写数据不能检验实际跨月交易风险。']);
q('卷动收益与曲线未来变化','投资者因当前近高远低就断言滚动多头未来总收益一定为正，忽略合约价格可能整体下跌。正确修正是？',[
'有利移仓结构不能排除持仓期货价格下跌及曲线变化|总回报包含实际持仓损益与资金收益等，不能由当前曲线一个截面保证。',
'只要买入远月更便宜，就不会产生任何亏损|即便换入价格较低，该远月合约在持有期间仍可能继续下跌并产生损失。',
'把每次换月价差直接累加就等于实际账户利润|移仓涉及旧新合约成交和后续持有，不能脱离完整现金流。',
'当前反向市场代表所有商品未来均短缺|单品种特定期限曲线不能推出全部市场确定供需。']);
section('futures1',4,'futures1-4','expansionDerivCases','案例B4：多因素经营敞口、现金流日期与最小方差定义');
q('原料与汇率双变量的未套保部分','进口企业以美元购买原料，先按当前预计货款锁定固定美元数量的汇率。随后美元原料价上涨使应付美元增加，原外汇合约数量未变。还剩什么风险？',[
'新增美元货款未被原固定数量外汇合约覆盖|原汇率套保锁住指定美元金额，不会自动随商品价格增加名义本金。',
'只要已套汇，任何商品涨价都由外汇合约赔付|外汇合约不直接对冲原料美元价格。',
'原外汇合约会自动追加到实际采购金额|题设是固定名义数量，并无自动调整条款。',
'美元价格上涨只改变吨数不改变美元付款|采购吨数不变时美元单价上升会增加应付美元。']);
q('销售提价传导对净敞口的影响','企业每单位原料涨价可按合同在同月转嫁80%给客户，原料用量已确定。若只针对未转嫁的成本风险建模，应先按哪一层敞口设计？',[
'剩余20%的净成本敏感度，再检查实际传导条件|合同自然对冲已覆盖部分价格变动，按全部成本套保可能过量。',
'无论传导如何，都必须对100%采购额套保|销售收入按合同同步增加已抵销80%的成本变化，不能重复忽略这项自然对冲。',
'既能转嫁80%，就没有任何剩余风险|仍有20%未转嫁部分，且还需核实条件。',
'应按180%建仓，把成本与涨价收入相加|净风险应考虑相反方向抵销，而非无差别相加。']);
q('自动调价滞后留下时间风险','原料成本每天浮动，产品合同按上季度均价每季初调整售价。经理称售价能调就无需任何价格风险预算，遗漏什么？',[
'成本变化先发生、收入调价后发生的时间错配|最终可调价不等于当期毛利立即受保护，滞后期间仍有风险。',
'只要合同有调价条款就能每日同额传导|题设明确采用上一季度均价，不是当日同步调整。',
'把售价记账日期提前就能消除实际现金影响|会计日期不能改变客户实际付款和定价条款。',
'涨价滞后只影响报表不影响经营利润|当期采购成本与销售收入错配可实际压缩利润和现金。']);
q('平均价采购与单日到期对冲','工厂采购价按整月每日现货均价确定，期货头寸却全部在月末单日平仓。最关键的基准错配是什么？',[
"均价与月末点价的窗口不同，需匹配观察期或分期覆盖|月内不同价格路径可能有同一月末价，却形成不同采购均价，单点头寸无法自动匹配整月风险。",
"采购与期货都在同一个月完成，所以价差只可能来自品质|同月并未统一价格观察方法，排除品质差异后仍可能有月度平均与月末单点的时间基准风险。",
"只要期货数量等于实际采购量，就足以消除平均价的错配|数量一致不等于价格参考一致，期货单点收益不能因此自动转为每日平均价格的变化。",
"选择距离月末更近的到期合约，就能精确复制整月采购均价|到期日更接近月末仍然只匹配一个时点，不能单靠期限接近复制整月观察和加权。"]);
q('分批确定价格的剩余敞口台账','企业1000吨采购合同中，600吨已经点价固定，400吨将在下月点价。若只管理尚未定价风险，台账应保留多少吨敞口？',[
'400吨|已经点价的600吨价格已确定，未点价400吨才随未来参考价变化。',
'1000吨|把已固定部分继续列为未定价可能造成重复套保。',
'600吨|把已定价数量与剩余价格风险数量颠倒。',
'0吨|签采购合同不代表所有批次价格都已锁定。'],calc('1000-600',400,'吨未点价敞口'));
q('反向回归斜率不能直接倒置套保','题设ΔS与ΔF均已中心化，两者方差非零，相关系数非零且绝对值小于1；目标是最小化ΔS−hΔF的平方误差。分析员却回归ΔF对ΔS并把斜率取倒数当h，主要问题是什么？',[
"应按ΔS对ΔF的目标回归，倒数一般不保留原误差最小化|目标斜率为Cov(ΔS,ΔF)/Var(ΔF)；反向斜率倒数是Var(ΔS)/Cov，非完全线性关系下一般不同。",
"交换横纵轴只是单位互换，所以斜率倒数仍最小化原残差|两种回归最小化的是不同方向的残差，存在未解释波动时不能按确定直线的倒数规则处理。",
"把反向斜率倒数取绝对值，就能恢复原目标的最优套保比率|绝对值最多改变符号，不能把错误的方差分母与优化方向转换为题设要求。",
"两变量已中心化，所以反向斜率取倒数必与正向结果相同|中心化用于处理均值，不会消除非完全相关的残差，也不改变两种斜率所用的不同方差分母。"]);

q('回归收益率比率与价格比率混用','分析师用百分比收益率回归得到斜率1.2，却直接乘现货吨数得到期货手数，未使用现货和期货单价。为什么不完整？',[
"收益率斜率按价值敞口映射，换为手数还需两边价格和单位|百分比收益变化须乘相应资产价值才能得到金额变化，再以每手期货价值换算所需数量。",
"只把现货吨数除以期货每手吨数，再乘1.2就完成全部换算|这只统一实物数量，仍遗漏收益率回归中现货单价与期货单价决定的价值尺度差异。",
"两边回归都用百分比，所以任何现货与期货价格水平都可省略|百分比统一的是收益率表达，等百分比变动作用于不同价格和名义价值时仍有不同金额影响。",
"用现货吨数乘1.2后，再按期货最小价格变动单位换成手数|最小变动价位不是每手合约的经济价值，不能代替现货及期货价格和合约单位的换算。"]);
q('价格敞口对冲不能保险实物毁损','仓库以卖出期货对冲库存价格，随后火灾毁损货物且没有财产保险。期货并未出现相应盈利。应如何解释？',[
'价格对冲与实物损毁风险不同，卖期货不承诺赔付仓储火灾|衍生品收益取决于价格，不直接取决于仓库财产是否灭失。',
'只要是套保，所有与库存有关损失都应赔付|套保范围应由标的风险和合同现金流决定，不能泛化。',
'没有赔付说明期货价格计算必然错误|火灾损失并不必改变市场参考价格。',
'多卖一倍期货就等价购买火灾保险|扩大价格头寸不创造按实物损毁支付的保险合同。']);
section('futures1',7,'futures1-7','expansionDerivDV01','第2页CTD、转换因子与风险匹配；所有报价均为题设值');
q('最便宜可交割不是现券价最低','忽略持有及其他成本，债券A采购全价101、交割可收100.8；B采购全价99、交割可收98.5。空头选择交割券应优先哪只？',[
'A，净交割成本0.2低于B的0.5|应比较买券成本减交割收入，不能只看现券绝对价格。',
'B，因为99低于101|忽略两券经转换因子等调整后的交割收入不同。',
'A和B相同，因为都是合格债券|资格相同不意味着交割现金流成本相等。',
'选择交割收入最低者，无需考虑采购价|交割收入越低未必越便宜，需要与采购支出合并。'],calc('(101-100.8)-(99-98.5)',-.3,'A减B的净成本差'));
q('转换因子映射期货DV01','题设期货跟踪CTD，现金券每对应名义单位DV01为76元，转换因子0.95。按F约等于现券价除因子，期货每手DV01近似多少？',[
'80元/基点|F随现券价格变动放大1/0.95，因此76÷0.95=80。',
'72.2元/基点|把应除的转换因子误作乘数，方向相反。',
'76元/基点|漏掉期货报价与现券报价之间的转换因子映射。',
'0.95元/基点|把无量纲的转换因子直接当金额风险指标。'],calc('76/.95',80,'元/基点'));
q('国债期货全价交割金额的规模','题设报价按每百元面值，期货结算价102、转换因子0.98、每百元应计利息1.2，每手面值100万元。交割金额如何计算？',[
'1011600元|每百元发票价102×0.98+1.2=101.16，乘1000000/100。',
'101160000元|忘记报价以每百元为单位，直接乘面值多放大100倍。',
'999600元|只乘转换因子得到99.96，漏加应计利息1.2。',
'1032000元|未按题设转换因子调整期货结算价，不能直接用102加利息。'],calc('(102*.98+1.2)*1000000/100',1011600,'元/手'));
q('票息不由期货名义票面支付','题设国债期货合约引用标准票面利率作转换比较，客户持期货多头却未持现券，要求按名义本金收该票息。正确理解是？',[
'期货不是实际付息债券，标准票面用于合约设计不等于票息请求权|债券付息需来自持有相应现券或另有现金流合同。',
'每个期货多头都同时成为所有可交割券持有人|到期可能交割不等于存续期已经拥有债券。',
'只要交足保证金就可领取整笔名义本金票息|履约担保不赋予现券所有权与付息权。',
'转换因子越小，客户可自动多领票息|转换因子用于交割价格映射，不是额外付息比例。']);
q('利率大幅变化下的凸性残差','两组债券头寸当前DV01相抵但凸性不同，团队称任意幅度平行利率变化都完全中和。应怎样修正？',[
'DV01只是一阶局部匹配，大幅变化需重估凸性及敏感度变化|曲线非线性会使等一阶敏感度的组合仍产生剩余损益。',
'DV01一旦相等就保证所有现金流相同|局部斜率相同不意味着两条价格曲线完全重合。',
'提高名义本金就会自动让凸性相同|数量调整不能在不核算条件下保证同时满足所有风险因子。',
'只测试1基点变化就能验证100基点完全匹配|小幅验证不能证明更大范围的线性近似精确。']);
q('已知票息与债券远期持有成本','企业以全价买债券并卖远期，持有期间会收到一笔确定票息。模型只计购债融资成本，未计票息再投资，理论远期价会怎样偏离？',[
'通常被高估，因为漏掉持有债券带来的收益抵减|在题设可再投资条件下，票息收益降低净持有成本。',
'通常被低估，因为票息是额外购债支出|票息由债券持有人收到，不是支付给发行人。',
'完全不影响，因为任何远期都没有持有成本|远期复制通过现货和现金流，债券收益需要纳入。',
'应把票息加到融资成本并再次融资|这把收益方向反转并重复增加成本。']);
section('futures1',7,'futures1-7','expansionDerivForward','公开Introduction/Summary：FRA、互换与复制；结算约定全部题设');
q('FRA提前结算的折现调整','题设FRA名义本金100万元，未来半年市场利率6%、约定4%，按单利在计息期开始结算。半年利息差1万元，按市场利率折现，开始日付款应是多少？',[
'约9708.74元|期末利差10000需除以1+6%×0.5=1.03。',
'10000元|这是计息期末利息差，未调整到开始日支付。',
'10300元|把提前支付应折现错误处理成再向未来复利。',
'20000元|忽略半年计息长度，把全年利差当半年金额。'],calc('1000000*(.06-.04)*.5/(1+.06*.5)',10000/1.03,'元'));
q('FRA保护借款利率的收付方向','企业将在三个月后借入浮息贷款，担心届时利率高于预算。题设FRA按市场利率减约定利率向某一方付款，企业应选择哪一方？',[
'利率上升时收取差额的一方|升息会增加未来贷款成本，FRA收入可抵销相关增加。',
'利率上升时支付差额的一方|这与贷款成本上涨同方向亏损，增加而非抵销风险。',
'只比较当前权利金大小，FRA方向无关|FRA是远期利率承诺，收付方向决定对冲效果。',
'任何FRA名义本金相同就完全等价|同本金下收付方向相反仍有相反风险。']);
q('摊还贷款与固定名义互换错配','企业贷款本金将每季度偿还一部分，却配了全年固定本金的付固定收浮动互换。半年后可能出现什么？',[
'互换浮动收款对应本金高于剩余贷款，形成超额利率敞口|对冲名义应与贷款摊还计划匹配，初始相等不保证以后相等。',
'贷款已还本金会自动同步减少互换本金|两份合同需明确摊还条款，题设固定本金不会自动改变。',
'只要互换方向正确，数量期限都不影响效果|方向、数量和时点共同决定对冲。',
'本金下降会让所有利率风险永久归零|剩余贷款和未摊还互换仍有现金流敏感度。']);
q('贷款零利率地板与互换负浮息','题设贷款年利率为max(L,0)+1%，配套互换付固定3%、收未设地板的L，名义与期限完全匹配。若本期L=−1%，忽略费用，综合年化成本是多少？',[
'5%|贷款付1%；互换付3%并因收负1%实际再付1%，总成本为5%。',
'4%|机械用固定3%加贷款加点1%，遗漏贷款地板与互换未设地板的不对称。',
'3%|把贷款加点和负浮息效果相互错抵，未按两份合同分别列现金流。',
'2%|将互换收负1%误当真正收到正1%，颠倒负利率现金流。'],calc('Math.max(-.01,0)+.01+.03-(-.01)',.05,'综合年化成本'));

q('互换重置日与付款日不同','题设互换浮动利率在季初重置、季末付款。季中市场利率上涨，财务立即改写本期已重置票息，问题是什么？',[
"本期参考利率已确定，后续利率变化仍可影响剩余合约市值|季末尚未付款不表示本期参考利率仍每天更新；未重置现金流及折现因素仍可随市场改变。",
"本期尚未支付，所以应持续按最新市场利率更新本期票息|付款日与重置日是两种时点，题设季初已经锁定参考利率，不能因未付款而改写。",
"本期参考利率已确定，所以整份剩余互换的市值也已经固定|只确定了本期参考利率，之后未重置现金流和当前折现条件仍可能改变整个合约价值。",
"取季初利率与季中利率的平均值，就可保留原重置日的效力|合同指定季初重置，不是两次观察取平均；人为平均改变已确定的现金流计量依据。"]);
q('期初零价值不等于互换免费无风险','标准互换设定固定利率使初始净市值为零。业务员据此称客户未来无须付款且没有风险，哪里错误？',[
'零初始市值表示两腿现值平衡，未来仍有双向现金流和市值变化|没有初始净费用不等于未来义务或风险消失。',
'两腿现值相等说明每个未来日期付款都必相等|总体定价平衡不要求每期实际金额相同。',
'互换没有权利金就不属于金融合同|初始付款方式不决定合同是否存在风险义务。',
'只要签约时净值零，对手方违约也不能造成损失|未来市场变化可形成正价值和重置成本。']);
q('互换已付息与剩余市值重复计入','估值日在本期互换付款完成后，系统从账户扣款，却仍将刚支付的同一现金流作为未来负债折现。应该怎样修正？',[
'从剩余现金流集合删除已结清一期，保留实际现金支付记录|已付现金流与未来负债不能重复减少组合净值。',
'删除付款流水但继续保留未来负债|这会掩盖真实已发生现金流，仍不正确反映合同状态。',
'把已支付金额再折现一次就不会重复|折现并不改变该现金流已经结清的事实。',
'因为互换长期存在，所有历史付款都要留作负债|合同存续不意味着已经履行的每期义务仍未履行。']);
q('互换净票息与提前终止价区别','当前互换最近一期净收息1万元，客户申请提前终止。交易台不能把1万元直接视作终止收款的原因是什么？',[
'终止价值取决于剩余全部现金流的当前现值及合同成本|单期已知净票息不代表未来多期义务与权利的总价值。',
'只要最近一期收款，剩余合约价值必为正且相等|未来利率和期限结构可使剩余价值不同甚至为负。',
'提前终止一定按初始名义本金支付|名义本金通常用于计息，不是固定终止金额。',
'互换交易永远不允许提前终止报价|题设允许申请，关键是正确计算及遵守终止条件。']);
q('名义利率相等但计息惯例不同','两条互换腿名义本金、年利率和付款起止日期相同，但收款腿按Actual/360，付款腿按Actual/365。经理仅因票面利率相同就把本期两腿净额设零，应先核验什么？',[
'分别按合同年基准计算计息因子，再比较实际应收应付|相同年度百分比在不同日数分母下可产生不同期间金额，不能按票面直接抵销。',
'利率数值相同就足够，日数分母只影响显示|计息惯例参与实际现金流计算，并非报表格式。',
'任意选择360或365统一使用即可|未经双方有效约定不能自行修改某一腿的合同计算方法。',
'把本金减少到相同数值就能自动消除差异|本金已相同，剩余差异来自年分数而非数量。']);

section('futures1',7,'futures1-7','expansionDerivFX','Currency Pairs：基础币/报价币；原创交叉汇率和点数约定');
q('交叉汇率的单位链条','题设1欧元=1.20美元、1美元=7.00人民币，忽略买卖价差。企业每欧元采购付款对应多少人民币？',[
'8.40人民币/欧元|1.20美元/欧元乘7.00人民币/美元，美元单位消去。',
'5.83人民币/欧元|误将7除以1.2，得到的单位链条不符合该兑换方向。',
'0.1714人民币/欧元|将两项汇率相除或倒置，得到反向或不一致单位。',
'8.20人民币/欧元|两种汇率不能直接相加，需按币种单位相乘。'],calc('1.2*7',8.4,'人民币/欧元'));
q('外汇远期点数的尺度','题设即期报价1.2500美元/欧元，远期点数为−40点，每点0.0001美元/欧元。约定按即期加点数，远期全价是多少？',[
'1.2460美元/欧元|−40点相当于−0.0040，加入1.2500得1.2460。',
'1.2100美元/欧元|把每点当0.001，点数影响扩大十倍。',
'1.2540美元/欧元|题设负点数应减，不能变成正升水。',
'−38.75美元/欧元|直接把点数整数40当完整汇率单位相减。'],calc('1.25-40*.0001',1.246,'美元/欧元'));
q('负远期点的双边可执行报价','题设即期欧元报价买1.2490、卖1.2510美元；同期限远期点买−50、卖−30，每点0.0001，约定分别加到对应即期报价。企业卖欧元远期应参考哪个价格？',[
'1.2440美元/欧元|企业卖出面对银行买价，1.2490−50×0.0001=1.2440。',
'1.2480美元/欧元|这是银行远期卖价，适用于企业买入欧元，方向相反。',
'1.2460美元/欧元|这是远期买卖价中间值，不能当作保证可执行的卖出收入。',
'1.2540美元/欧元|把银行买价对应的负远期点错误加成正升水。'],calc('1.2490-50*.0001',1.244,'美元/欧元可执行买价'));

q('交叉货币风险不能按本币金额相消','企业有欧元应收和等值美元应付，当前折成人民币金额相同。经理据此把外汇敞口记零，遗漏什么？',[
'欧元相对美元的交叉汇率风险仍然存在|当前本币等值不保证两种货币未来价值始终等额。',
'只要人民币金额相同，任意两币都永久抵销|币种不同导致未来相对价格变化，不满足同币现金流匹配。',
'把欧元符号改为美元即可成为自然套保|报表重命名不能改变合同实际结算币种。',
'金额相同就说明欧元美元汇率固定为1|当前等值可以来自不同数量，并不约束汇率为1。']);
section('futures1',9,'futures1-9','expansionDerivFXRisk','BIS 2026 FX settlement risk：本金风险、PvP、重置和流动性');
q('外汇本金交付后的信用风险','银行已不可撤销付出700万元人民币，约定收100万美元但对方违约未付。交易违约前市值接近零，为何损失敞口仍可很大？',[
"已单边交付本金，交收敞口不能只按此前的净市值衡量|银行已不可撤销付款而尚未收款，整笔交付本金可能处于风险中，实际损失还取决于追偿和回收。",
"两币按约定汇率原本等值，所以应收美元已足以抵销风险|应收金额等值不等于对手已经履行，违约未付正是该应收款可能无法兑现的本金风险。",
"已付人民币属于完成的付款，所以此后只剩汇率价差风险|付款完成只说明本方已交付，不能排除对手不交付对应币种造成的本金损失敞口。",
"此前净市值接近零，所以违约后只需计入当天汇率变化|此前双边尚未交付时的重置价差不代表单边付款后的敞口，不能用旧净值限制本金交收风险。"]);
q('PvP仍留下未到款的流动性问题','外汇交易使用双方付款互为条件的PvP，对方未交币时本方也不付出本金。但本方原计划用收到的外币偿债。哪项风险仍存在？',[
'未如期收到外币的流动性需求及替换交易成本|PvP控制本金单边交付风险，不保证交易必按计划完成或替代币种无成本。',
'只要PvP存在，任何资金安排都不再需要|条件交收防止一种损失，不创造计划中的入账资金。',
'本方仍必须先付本金再等对手方|这与题设付款互为条件的PvP机制相反。',
'所有债务因对方交收失败自动顺延|外部债务期限不会因另一外汇交易失败自动改变。']);
q('外汇掉期的两次本金交换','题设外汇掉期今天换入美元并付人民币，三个月后反向交换。财务只录远端点差付款，最重要遗漏是什么？',[
'近端与远端各自的两币本金交收及资金时点|掉期点反映价格关系，不替代四笔本金支付义务的现金流计划。',
'只漏掉一期固定利息，外汇掉期没有本金交换|题设明确近远两端实际交换货币本金。',
'近端交换后远端无需再做任何支付|反向交换是该掉期合同约定的一部分。',
'只要远端点差小，近端本金就不重要|点差规模与需按时支付的本金规模不同。']);
q('交收净额必须匹配价值日','两笔美元外汇付款一笔周一收100万、一笔周三付100万，没有提前净额或融资安排。经理把两笔在周一直接净成零，应如何修正？',[
"按周一收、周三付分别列示，原价值日不能直接净成零|总额相等不表示到期义务相同；题设没有改变日期的安排，资金计划必须保留真实现金流时点。",
"同币种金额相等即可周一净零，无需再保留周三付款记录|金额匹配不能改变周三仍存在的付款义务，直接消去会遗漏未来实际资金交付。",
"将两笔都改列周三净零，只延后报表日期而不影响权利义务|报表不能任意推迟周一应收款的合同日期，改列净额还可能掩盖周一未收款的交收问题。",
"只列本周合计零已足够，日内或日间安排无需进入资金计划|期间各日的现金可用性和履约状态与周合计不同，期末余额相同不保证途中没有资金约束。"]);
q('取消截止后至收币前的风险窗口','题设银行上午9点后不能撤回已发外币付款，对手币种下午3点才确认到账。即使最后正常到账，风险监测应怎样记录这六小时？',[
"记录9点至3点的单边不可撤销付款风险，即使最终正常到账|风险暴露时段与最终有无实际违约不同，已不可撤销支付而未确认收币的期间仍须监测本金风险。",
"正常到账说明没有实际损失，因此这六小时暴露可追溯删去|无实际损失是最终结果，不能证明期间没有风险，删除会低估曾承担的交收暴露及持续时间。",
"只有对手正式违约才开始计时，此前未收币不构成风险窗口|风险是在不确定履约期间就存在的暴露，不应等信用事件发生后才开始记录。",
"按这六小时的外汇净市值记录即可，无须另列本金交收敞口|单边不可撤销付款后的风险不只等于汇率重置价差，应单独识别未收到对手本金的状态。"]);
section('futures1',9,'futures1-9','expansionDerivCCR','CRE52.3–12：当前重置成本与潜在未来暴露；案例B5');
q('负市值不等于未来没有对手风险','互换当前对银行为负市值，银行此刻若立即终止需付款。交易还剩五年，为什么不能因此把全部对手方风险永久设零？',[
'未来市值可能转正，仍有潜在未来敞口|当前重置成本和未来状态下正敞口不同，需跟踪时间分布。',
'当前负值会自动固定到合同结束|市场利率等因素变化会改变合约剩余价值。',
'只要银行当前欠款，对手方就不可能违约|对手方信用状况不由单份交易当前正负值保证。',
'未来敞口只能等于当前负市值的绝对值|未来分布受剩余期限、市场变化和合同等影响，不是简单取绝对值。']);
q('预期敞口与预期市值取正的次序','题设同一未来日期，交易市值等概率为+10或−10万元，无抵押。按EE=E[max(V,0)]，预期敞口是多少？',[
'5万元|先逐状态把负市值截为0，再按概率平均：(10+0)/2=5。',
'0万元|先平均得到0再取正，错误交换了非线性截断与期望的顺序。',
'10万元|只保留正状态的金额却没有乘该状态50%的概率。',
'−5万元|敞口只考虑对方欠本方的正值，不应产生负的该项指标。'],calc('(.5*Math.max(10,0)+.5*Math.max(-10,0))',5,'万元EE'));
q('平均敞口与分位信用额度的用途','同一未来日期模型给出EE=8万元、99%分位PFE=30万元。风险政策要求额度能覆盖该日期99%分位敞口，审批员拟用8万元。按题设应采用哪个尺度？',[
'使用30万元PFE与相同口径额度比较|EE是分布平均，不能替代政策指定的高分位暴露，30也不是绝对最大值。',
'使用8万元，因为平均数已经包含全部情景|包含所有情景的平均并不意味着能覆盖99%分位水平。',
'使用38万元，因为均值和分位数必须相加|两者是同一分布的不同统计描述，政策没有要求把它们相加。',
'使用22万元，因为额度应为PFE减EE|这个差额衡量不同统计量距离，不是题设规定的分位敞口额度。']);

q('同情景净额与逐笔敞口相加','题设两笔交易在合法同一净额组内，各有等概率两状态：甲分别+10、−10，乙分别−10、+10万元，无抵押。忽略其他风险，净额组EE是多少？',[
'0万元|每个状态两笔市值之和均为0，应先在状态内净额再取正、求平均。',
'10万元|这是每笔EE各5再相加，漏用了题设可执行且逐状态完全抵销的净额。',
'20万元|把不同状态的正值直接相加，忽略净额和概率。',
'−10万元|非负敞口定义不产生负EE，抵销最多降为零。'],calc('.5*Math.max(10-10,0)+.5*Math.max(-10+10,0)',0,'万元净额组EE'));
q('超额抵押的当前敞口下界','题设当前净市值70万元，认可抵押90万元，简化当前重置成本=max(V−C,0)。风险报表应记多少？',[
'0万元|70−90为负，但当前重置成本按定义下限为零，超额抵押不是负损失。',
'−20万元|未执行非负下界，将超额抵押错误计为负信用敞口。',
'20万元|取了负差额的绝对值，把保护缓冲当成当前欠款风险。',
'160万元|市值与收到的抵押品在该风险口径应抵减，不是相加。'],calc('Math.max(70-90,0)',0,'万元当前重置成本'));
section('futures1',9,'futures1-9','expansionDerivCCR','CRE52.14–19：门槛、最低划转额、独立抵押；具体合同阈值由题设给出');
q('抵押门槛与实际应追缴额','题设协议允许无抵押信用门槛20万元，需抵押金额=max(正市值−20,0)。当前市值65，已收抵押30，忽略最低划转额。还应追缴多少？',[
'15万元|目标抵押65−20=45，减已收30还差15。',
'45万元|算出目标总抵押，却未减去已在手30万元。',
'35万元|直接将市值减已收抵押，忽略合同信用门槛20。',
'65万元|把全部市值当追加数，既未扣门槛也未扣已收担保。'],calc('Math.max(65-20,0)-30',15,'万元追加抵押'));
q('最低划转额不是永远免交的扣减','题设最低划转额50万元表示不足50暂不划转，达到后应转全部应补额；无信用门槛。今天应补60万元，客户只转10万元，为什么不对？',[
'应转60万元，最低划转额是触发条件而不是抵扣额|题设达到50后全额划转，不能把50当作永远无需担保的信用额度。',
'10万元正确，因为最低划转额等于免赔额|最低划转额规定何时启动转账，本题未把它定义为可永久不抵押的信用门槛。',
'只需转50万元，超出部分永远无需处理|50是触发金额，不是最大允许划转额。',
'必须等到下一次市值翻倍才可追缴|题设60已达到触发条件，没有等待翻倍的要求。']);
q('单向抵押协议的保护方向','题设只有银行市值为负时须向企业交抵押；银行市值为正时企业无需交抵押。银行将该合同记录为双方均每日受保护，错误是什么？',[
'协议只保护企业一侧，银行的正敞口未获相同变动保证金保护|应按实际抵押收付权利而非协议名称判断缓释方向。',
'双方签字就意味着双方对称交抵押|签署双方共同文件不代表现金流条款对称。',
'银行交出的抵押可以直接抵减自己对企业的正敞口|交出与收到抵押的风险作用不同，不能反向抵减。',
'单向协议说明交易不可能产生正市值|市场价值与抵押安排是不同层次。']);
q('初始保证金与变动保证金的用途','题设VM用于覆盖最新重置市值，IM用于违约后平仓期间潜在不利变化。账户已收足VM，经理拟无条件释放IM，最主要问题是什么？',[
"VM覆盖当前市值，不能据此取消平仓风险窗口所需的IM|最后一次补保至违约后完成处置之间仍可能不利变动，当前重置成本已覆盖不代表该期间风险归零。",
"VM覆盖率达到100%，就可按相同比例抵减全部IM要求|两个保证金覆盖的风险窗口不同，当前敞口全覆盖不能机械抵销未来处置期间的潜在变化。",
"只要VM每日收取，违约到最终平仓之间的风险时长就为零|每日收取不等于违约后能瞬时完成处置，仍有价格变化、执行和补保停止后的风险间隔。",
"IM只服务开仓当天，收到第一笔VM后其保护作用即已结束|题设明确IM覆盖违约后平仓期间的潜在不利变化，该需求不因首次VM到账自动消失。"]);
q('保证金风险期与剩余期限区分','对手方违约前最后一次补保在周一，完成平仓及风险替换在周五，原合约还剩三年。评估这次补保后无覆盖变化窗口，应首先使用哪个时间概念？',[
'从最后补保到风险替换完成的保证金风险期|此窗口衡量违约后不能持续补保时的价格变化，不等同三年合同剩余期限。',
'一律使用原合约三年剩余期作为此次操作窗口|混淆市场暴露的总期限与违约后处置间隔。',
'只使用周一到违约瞬间，不计后续平仓|风险在完成处置和替换前仍可能变化。',
'收过抵押就可把任何窗口设为零|最后补保与最终清算之间通常仍存在时间差。']);
section('futures1',9,'futures1-9','expansionDerivCredit','SRP32.3、32.17、32.23：抵押品实现、操作和估值风险；原创协议案例');
q('抵押市价和折扣同时变化','收到债券初始市值100万元、折扣10%；压力时债券市值降至80万元且认可折扣调至25%。认可担保价值较初始减少多少？',[
'30万元|初始90，压力时80×75%=60，减少30；须同时更新市值与折扣。',
'20万元|只看市价跌幅，漏掉折扣从10%升至25%的影响。',
'15万元|只看折扣百分点变化，忽略市值也下降。',
'35万元|直接相加20与15，未考虑新折扣作用于80万元市值。'],calc('100*.9-80*.75',30,'万元认可担保减少'));
q('抵押争议中的无争议金额履行','题设协议要求抵押争议仅暂缓争议部分。银行请求100万元，对手方认可70万元但因余下30争议拒付全部。按题设应如何处理？',[
'及时支付无争议70万元，并依流程处理剩余30万元|争议范围不应无条件扩展到已确认的全部补保义务。',
'存在任何争议就自动暂停所有付款|这与题设只暂缓争议部分的条款冲突。',
'银行必须先撤回全部请求才能收70万元|题设未要求放弃全部请求才履行无争议部分。',
'直接把100改成70并永久删除争议|这会未经解决放弃仍待核验的30万元，不完成争议闭环。']);
q('不可及时变现抵押的资金错觉','银行持有估值充足但依法处置需数周的担保资产，今天须支付替换交易资金。风险报告为何不能只看抵押账面足额？',[
'可回收价值与今日可筹现金不同，需考虑处置权限和时间|抵押可能降低最终信用损失但不能满足即时资金需求。',
'抵押一旦足额就必能当天无折价卖出|法律和市场流动性可能限制处置速度及价格。',
'等待期越长，现金缺口一定越小|时间延迟可能延长融资压力，而非自动减少。',
'把评估价值直接记入现金账户即可付款|担保资产尚未完成处置，单纯把估值移动到现金科目并不能实际支付替换交易。']);
q('每日补保仍留下盘中缺口','协议只在收盘补变动保证金，上午已足额覆盖昨日市值，午间行情剧烈变化。风险员说今天无需再看敞口，主要错误是什么？',[
'昨日足额抵押不能自动覆盖当日盘中新产生的正市值|补保频率是离散的，两次补保之间仍可能有信用暴露。',
'每日补保等于连续每秒补保|日度安排不能消除具体时点之间的变化。',
'盘中行情只影响交易量，不影响合同市值|价格、利率等变化可直接改变衍生品价值。',
'对手方签过抵押协议后就不再可能违约|补保协议提供风险管理机制，但对手方仍可能因财务困难或其他原因不能履约。']);
q('交易压缩的风险收益边界','两家公司压缩多笔同类互换，保留相同净现金流和净市场风险，但总名义本金下降。最恰当的效果描述是？',[
"可降低毛交易和操作负担，净市场风险按题设仍保持相同|压缩去掉冗余交易而保留相同净现金流；总名义本金减少不等于该净价格敏感度同比下降。",
"名义本金减少多少比例，剩余净市场风险就必减少相同比例|题设已说明净市场风险保持相同，名义规模不能代替对剩余现金流和价格敏感度的分析。",
"净市场风险既然相同，交易压缩就不会带来任何操作收益|在不改变净敞口的同时减少冗余合同，可降低确认和日常处理负担，不能仅凭净风险否定其作用。",
"合同数量减少后，剩余交易的确认与抵押管理也可一并停止|压缩只是减少存续合同规模，保留下来的义务仍须按适用安排估值、确认及管理抵押。"]);
q('新对手承接不等于原对手自动解除','企业签署一份与新银行经济上相反的互换，希望替代原银行交易，但原合同未终止也无三方更替同意。此时应怎样识别风险？',[
'存在两份独立合同，仍需分别管理两家对手风险|经济对冲不等同法律上的债务更替，原对手义务和暴露未自动消失。',
'新合同一签，原合同在法律上自然作废|题设没有原合同终止或有效更替安排。',
'只要净市场风险零，信用风险也必为零|不同对手的违约和净额范围不能无条件相互抵销。',
'把原银行名称改成新银行就完成替换|合同主体变更需有效程序，不能靠内部报表改名。']);
q('报价中值与实际平仓成本','银行按中价给一组完全对冲交易估值为零，但两笔必须分别按对手买卖报价终止且有费用。为何仍应准备退出成本？',[
"中价净零不等于可执行净零，两边跨价差和费用仍需资金|分别终止时实际使用的买卖报价可能偏离中值，加上各自费用，净市场风险对冲也可有正退出成本。",
"两笔方向相反，两家对手的买卖价差就应在退出时自动抵销|对冲方向不改变每笔终止所面对的可执行报价，跨价差通常是各笔的成本而非必然相抵的现金流。",
"用一笔的中价收益抵另一笔中价损失，费用也已隐含覆盖|中价抵销只是在该估值口径下净零，并无额外现金足以证明买卖差价和终止费用已经覆盖。",
"先在内部报表上合并为零，便可不向两家对手分别支付费用|内部合并不解除两份对外合同，题设要求分别终止和收费，不能靠报表净额消除实际支付。"]);
section('futures1',9,'futures1-9','expansionDerivLiquidity','LQY10.45及10.102：评级触发的追加抵押需求；题设约定门槛与立即补足');
q('评级触发条款会在市值不变时追加抵押','题设互换担保额=max(银行对企业正敞口−门槛,0)。正敞口一直为60万元，企业已交40万元；评级下调使门槛由20降到0，协议要求立即补足。没有市场价格变化时，企业应怎样预算？',[
'仍须追加20万元，来自门槛触发而非新市场损失|降级使可无担保部分由20降为0，所需抵押从40升至60；只模拟市值变化会漏掉该现金需求。',
'无需追加，因为互换市值没有发生变化|担保义务同时取决于协议门槛，市值不变不代表所有现金要求不变。',
'追加60万元，因为新门槛为零就应重新交全部正敞口|原40万元仍有效，新增款仅为新总要求与已交款之差。',
'应退回20万元，因为门槛下降表示企业可以提供更少担保|门槛表示允许的无担保敞口，下降会提高而非降低需提交的抵押额。'],calc('(60-0)-40',20,'万元评级触发追加抵押'));
section('futures1',8,'futures1-8','expansionDerivCases','案例B6：原创期货回测、数据和可执行性审查');
q('异步收盘造成虚假领先关系','研究员把同一日期的甲市场收盘价用于预测乙市场收盘价。题设甲实际收盘为UTC 21时，乙为UTC 15时，却因日期相同把甲当作乙之前的信息。最应怎样修正？',[
"按实际时间戳对齐，甲当天收盘晚于乙当天收盘而不可前用|UTC21时形成的信息不能用于声称预测UTC15时已发生的结果，日期相同不代表信息先后顺序相同。",
"两者都用本地交易日期标记，就可忽略UTC收盘时点差异|本地日期标签不能统一信息产生时点，应先转到共同时间轴判断预测时是否已经可得。",
"只要同日期样本的相关系数显著，就可保留甲领先乙的结论|相关显著不证明信息在预测时已经存在，统计强度不能消除使用未来信息的先后错误。",
"增加更多相同日期对齐的历史样本，就能自动消除时差偏差|错误对齐会在新增样本中持续出现，扩大样本不能使较晚收盘变为较早已知信息。"]);
q('用当前保证金回填全部历史','回测将今天5%的保证金率套到过去所有日期，但历史压力期曾按题设提高至15%。对资金可行性评价最可能有什么问题？',[
'低估过去压力期所需现金和强平风险|历史交易能否持续取决于当时实际保证金条件，不只是今天参数。',
'只影响图表颜色，不影响可持仓数量|资金要求决定杠杆容量和是否能满足追缴。',
'只要到期累计盈利，任何历史保证金率都无关|途中资金不足可能使持仓无法存续到最终结果。',
'提高历史收益率分母就能自动补足缺失资金|报表调整不替代逐时现金与保证金模拟。']);
q('随机打散时间序列的验证误区','团队把同一时期相邻分钟随机分到训练和测试集，市场状态高度持续。为何测试结果可能过于乐观？',[
"近邻状态被两组共享，测试未充分检验未来不同阶段的泛化|高度持续的时间状态使随机切分后的两组并不独立，应结合时间顺序和验证目标设计样本外检验。",
"训练与测试没有完全重复的数据行，就已经确保状态信息独立|不同分钟仍可能共享高度相似的持续状态，记录不重复不足以证明时间依赖已经隔离。",
"提高测试集占比，只要测试行数更多就能消除近邻依赖影响|数量比例不改变相邻分钟共享状态的事实，不能替代按时间及信息可得性设计的隔离。",
"重新随机打散多次并取均值，就相当于经历多个未来市场阶段|重复切分同一时期仍在复用既有状态，均值可平滑分割噪声，却不产生真实的新阶段证据。"]);
q('全样本标准化的未来信息','策略按收益均值和标准差标准化信号，参数却用完整十年数据估计，再回测第一年交易。即使信号只用过去价格，仍有什么问题？',[
'第一年的变换参数含有未来九年的分布信息|预处理也应只使用当时可得的训练窗口，不能只检查原始特征日期。',
'标准化不涉及价格，所以不会有未来信息|均值和标准差本身由未来价格数据计算。',
'只要不使用未来收益方向，任何未来统计量都允许|未来波动水平等分布信息也可能改善历史决策。',
'把标准差乘100即可消除泄漏|单位缩放不能修复参数估计时的信息越界。']);
q('一根K线同时触发止盈止损','回测只掌握一小时开高低收，某笔多头同一小时最高价超过止盈、最低价低于止损。程序总按先止盈记盈利，合理修正是什么？',[
'取得更细路径数据或采用明确保守规则，并报告顺序不确定性|OHLC不说明先高后低还是先低后高，不能默认对策略最有利。',
'最高价大于最低价就证明先止盈|最高价大于最低价只是数值关系，不能证明小时内先触达哪一阈值。',
'只要最终收盘上涨就必先经过止盈|最终方向无法决定盘中两阈值的先后触达。',
'随机删除触发止损的记录即可得到准确回测|选择性删记录会系统性夸大收益。']);
q('限价触及不保证回测成交','模拟买单挂在100元，历史最低成交价100元，但该价位只有1手成交且大量订单排在模拟单之前。能否按计划100手全部成交？',[
'不能，需考虑队列、可用成交量及自身订单到达时点|价格触及只是可能成交的必要信息，不证明有足够对手数量轮到该订单。',
'可以，只要最低价等于限价所有挂单都全成|同一价格的有限成交量不能覆盖无限排队订单。',
'可以，把成交价写成99.9能更保守|低于实际可见价格反而给买方更有利假成交，不能修复排队问题。',
'必须全部不成交，因为限价单从不在最低点成交|也不能反向绝对化，应依据可验证队列和数量假设。']);
q('多策略重复使用同一盘口容量','两个策略各自回测都假设可买到同一时刻卖一50手，合并后同时各下50手。总回测为何可能高估可执行收益？',[
"两策略争用同一50手卖盘，合并时须重新分配成交容量|合并买入需求共100手，却只观察到同一时刻50手卖一，不能让两次独立回测重复消耗同一批流动性。",
"每个策略的下单量都未超过50手，所以合并后仍可全部成交|逐策略数量限制未考虑并发总需求，分别不超容量不等于合计100手能使用同一档50手报价。",
"将两个策略分到不同交易账户，就能分别保留50手卖一成交|账户划分不会增加市场对手卖单，总需求仍争用相同有限盘口，须考虑撮合顺序及后续报价。",
"把两策略的回测收益取平均，就已消除重复使用盘口的问题|统计平均没有重建真实执行量，仍可能包含两份无法同时按卖一价格完成的虚拟成交。"]);
q('缺失行情填零收益的低波动假象','低流动性合约连续多日无可靠报价，系统把缺失日都记0收益，再估计风险。最应警惕什么？',[
"把未知价格变动写成确定零，可能压低波动并掩盖跳价风险|未观测到有效报价不等于价值不变，机械填零会改变收益分布，应标明缺失并评估估计方法。",
"填零没有引入虚构涨跌，所以计算出的风险必然更加保守|零本身就是价格不变的数值假设，填补大量零可压低观测波动，不能称为保守上界。",
"只要在下次有效报价时一次补记涨跌，各日风险就已准确|累积变化集中到某一天不能恢复中间真实路径，日波动和跳价风险仍受缺失及归属方式影响。",
"只在均值计算中删去缺失日、波动计算保留零就能恢复风险|对均值另作处理不消除方差样本中的人为零值，估计口径不一致还会继续扭曲结果。"]);
q('负价格使对数收益不可直接使用','某合约实际报价从2跌到−1，研究程序计算log(−1/2)失败。最合理的处理是什么？',[
"该实数对数定义不适用，应改用明示的价差或金额风险口径|负比值没有实数对数，需承认指标边界并使用能容纳负价的清晰定义，不能改变真实行情来迁就公式。",
"将终值−1先取绝对值，再把结果保留为原交易的对数收益|取绝对值把真实负价改成正价，会改变经济路径，所得指标不能继续称为原数据的实际对数收益。",
"给全部价格统一加10后取对数，其数值仍与原经济收益相同|平移可使对数可算，但百分比变化取决于分母，任意加常数会改变收益含义，不能宣称经济等价。",
"仅删除这一条无法计算的记录，剩余波动就能代表完整风险|删除实际极端行情会漏掉重要损失状态，程序可以运行不等于风险样本仍完整或无偏。"]);
section('futures1',2,'futures1-2','expansionDerivCases','案例B7：题设撮合指令、报价有效性和交易记录');
q('主动买入成交不等于新增多仓','行情统计某时段主动买入成交很多，研究员据此认为全是新多头建仓。为何证据不足？',[
'主动买入也可能是空头回补，须结合开平及持仓信息|成交发起方向不能单独识别账户是新增还是结束头寸。',
'主动买入只能由多头开仓触发|空头买入平仓同样会主动吃卖盘。',
'主动买入必使市场总持仓量增加相同数量|持仓量还取决于另一方及双方开平组合。',
'只要成交价上涨就可忽略账户开平标志|价格变化不能直接证明持仓形成或注销。']);
q('全成或撤与部分成交的业务约束','题设系统支持全成或撤FOK和立即成交剩余撤销IOC。套利计划不能接受任何部分成交，哪种指令更贴合单腿数量完整要求？',[
'FOK，但仍须另管不同腿之间的完整配对|FOK要求该笔数量全成否则取消；它不自动保证另一个独立合约也同时成交。',
'IOC，因为它必定完整成交所有数量|IOC允许立即可得部分成交并撤销余量，未保证全部成交。',
'普通市价，因为数量总会无限满足|市价指令仍受市场流动性和系统规则限制。',
'任意指令都可，只要备注不能部分成交|非系统约束的备注不能替代有效指令条件。']);
q('修改数量后的排队优先级','题设撮合规则规定增加订单数量会使整笔重新排队。交易员在同价买单排第一时将10手加到100手，却在回测中保留原队首位置。应怎样修正？',[
'按新报单时点重新评估队列与成交量|题设数量增加触发优先级重置，不能沿用旧订单位置。',
'价格没变就必然保留任何市场的优先级|优先规则取决于明确制度，本题已规定加量重排。',
'只把新增90手算成交、旧10手算撤销|这也不符合整笔重新排队的题设规则。',
'把数量分成显示10手就能自动保留全部100手优先|题设未提供隐藏量保留优先的机制，不能自行假设。']);
q('仅供参考报价不能锁定套利','经纪商邮件给出价差报价，并明确标记仅供参考、最终成交须重新确认。研究员立即把它与交易所盘口配对宣称已锁利，遗漏什么？',[
"参考报价未承诺成交，须确认可执行价格、数量和有效条件|题设最终成交仍须重新确认，邮件里的数字不足以证明两边均能按预计条件成交并锁定差额。",
"只要参考报价时间晚于盘口时间，就可直接视作可执行价格|报价更新先后不改变仅供参考的约定，较新数字仍可能没有数量或成交承诺。",
"交易所一腿先成交后，邮件另一腿就应按原参考价同步生效|单边成交不会替另一对手接受交易条件，未经确认的另一腿仍可能变价或无法成交。",
"只需将预期利润扣除常见手续费，就可以称两腿套利已锁定|成本估计没有解决参考报价是否可成交，未知执行条件可能比手续费更直接影响能否锁利。"]);
q('成交确认中的收付视角反转','企业互换应付固定收浮动，银行确认书从银行视角写收固定付浮动。核对员见文字方向相反就判定错误，正确核对方法是什么？',[
'先统一双方视角，再逐项匹配本金、利率、日期及币种|同一交易两方收付恰好相反，不能按文字表面要求相同方向。',
'双方确认书必须都写付固定才有效|同一现金流不可能让双方都作为付款方。',
'只要收付文字相反，其余条款都可免核对|视角解释方向后，金额和日期仍可能不匹配。',
'把银行确认书改成企业视角就不必保留原件|应保留原确认并明确视角，不随意修改对手原始记录。']);
q('交易回报重复与持仓重建','网络重连后收到同一成交编号的回报两次，系统各加10手，随后持仓比清算多10手。正确处理原则是什么？',[
'按唯一成交标识去重并对账，不把重复通知当新成交|同一已确认交易的重复传输不产生第二笔经济义务。',
'收到两次消息就必有两笔交易|消息传输次数不等于实际成交笔数。',
'直接下反向10手修复报表，不必核实真实持仓|若实际未多持仓，这会制造新的反向风险。',
'把清算持仓改成系统数字即可闭环|应以可核验成交和清算记录查明差异，不能任意改写证据。']);
q('撤销成交与另做反向交易的区别','交易双方依法按题设纠错流程取消一笔错误成交，与客户正常另做一笔反向交易，在交易台账上有何关键区别？',[
"纠错撤销原成交；反向交易保留两笔成交及各自处理依据|正式撤销按题设纠错结果更正原交易并保留轨迹，正常反向交易不追溯抹去原成交及相关结算费用。",
"只要最终净头寸相同，就可把反向成交记作原成交被撤销|经济方向相抵不等于法律和业务状态相同，反向交易仍是新增的真实成交记录。",
"正式纠错也必须另记一笔反向成交，否则无法更新原交易|题设已经采用撤销流程，应按更正结果调整原记录，不应凭空增加一笔从未实际成交的反向交易。",
"原成交和反向成交数量相同，费用也应按方向正负自动抵销|交易方向相反不代表费用互为退款；应依据两笔真实成交与适用收费规则处理，不能自动净为零。"]);
section('futures1',7,'futures1-7','expansionDerivForward','公开Summary：现金流复制及互换；新增风险因子由题设明确');
q('等金额多空不等于市场Beta中性','组合买入1000万元Beta为1.4的指数敞口，卖出1000万元Beta为0.8的另一指数敞口。为何不能因金额相等就称市场中性？',[
'净市场敏感价值仍为1000×(1.4−0.8)=600万元|价值中性不等于Beta中性，应按对共同市场因子的敏感度加权。',
'两边都是1000万元所以所有因子严格抵销|不同指数的Beta和其他风险因子暴露可能不同。',
'净敞口应为2200万元，因为绝对值必须相加|净市场方向需保留多空符号，绝对值总额是另一指标。',
'只要其中一边是空头，就不存在市场下跌损失|剩余正Beta意味着市场下跌仍可能不利。'],calc('1000*1.4-1000*.8',600,'万元Beta加权净敞口'));
q('不同浮动基准的互换基差','企业贷款按基准A浮动，互换却收基准B付固定；原先A与B接近，后来A升而B不动。哪部分没有被锁住？',[
'A与B之间的基差，收B不能完整抵销实际支付A|不同参考利率的相对变化会传入综合融资成本。',
'只要两个都叫浮动利率就完全对冲|名称相同不保证数值或变化关系一致。',
'互换会自动把收到的B改为贷款A|题设没有基准切换条款，不能单方面替换。',
'把固定支付调高就必消除基差变化|改变固定腿不直接消除未来A减B的随机变化。']);
q('股票总回报互换的分红遗漏','题设企业支付某股票总回报，使用只按股价差结算的远期多头对冲。股票价格不变但派发现金股息，远期没有该现金流。剩余风险是什么？',[
'总回报中的股息付款未被价格差远期直接覆盖|总回报包括价格变化和股息，价格回报工具的现金流不完全匹配。',
'股价不变意味着总回报必为零|总回报除了价格变动还包含现金股息，因此股价不变时仍可能有正回报。',
'任何股票远期都会自动支付全部股息|远期公平定价可能反映预期股息，但题设到期付款不含独立股息结算。',
'只要名义本金相同，现金流定义差异都无关|风险管理还需匹配收益口径和支付条款。']);
q('重置名义金额后的回报基数','题设股票互换每季将名义金额重置为当期起始参考组合价值。第一季末参考值由100升至110万元，第二季股价回报10%。若忽略其他项，第二季价格回报金额是多少？',[
'11万元|第二季基数按合同重置为110，10%×110=11。',
'10万元|继续使用最初100万元，忽略季度名义重置。',
'21万元|把第一季和第二季收益合并后当成本季金额。',
'110万元|这是本季名义基数，不是10%回报所产生的现金流。'],calc('110*.1',11,'万元第二季回报'));
section('futures1',2,'futures1-2','expansionDerivCases','案例B8：原创实物交割约定；数量、时间及单证以题设为准');
q('包装毛重不能当合格交割净重','题设每手交付10吨货物净重，仓单列毛重102吨，其中包装重2吨，包装不计入交割。最多覆盖多少完整手？',[
'10手|净货重102−2=100吨，除以每手10吨。',
'10.2手|把包装计入货物并忽略完整手数要求。',
'102手|把吨数直接当合约手数，未除交易单位。',
'9手|净重已有100吨，足够完整10手，不能无理由少算。'],calc('(102-2)/10',10,'手'));
q('干物质量口径的数量换算','题设采购风险按干物质吨衡量，湿货100吨、含水率20%；对冲合约每单位代表1吨干物质。核定敞口时应先用多少吨？',[
'80吨|干物质=湿重×(1−含水率)=100×80%，不能把水分也作为同等干物质。',
'100吨|直接使用湿重，未统一风险标的的数量口径。',
'20吨|这是水的重量，恰好不是需管理的干物质量。',
'125吨|将湿重除以80%是在反推另一个总量，不符合已给湿重求干重的方向。'],calc('100*(1-.2)',80,'吨干物质'));
q('仓单有效期早于交割日','题设某仓单有效到6月30日，计划用于7月10日交割，延续有效需重新检验且尚未办理。账面足量是否足以确认交割准备？',[
'不足，应核查续验能否及时完成或安排其他有效仓单|数量满足不代表交割日文件资格仍有效。',
'只要今天有效，就必能用于任何未来交割|题设有明确有效期限，不能延伸到7月10日。',
'把仓单日期改为7月就视作续验完成|更改显示不能代替检验和有效登记程序。',
'期货头寸会自动延长仓单有效期|两个期限来自不同安排，题设没有自动延期机制。']);
q('检验和运输并行条件的关键路径','题设交割前需运输3天、到库后检验2天，两项不能并行，今天至交割仅4天。经理把最长单项3天当所需总时长，正确判断是？',[
'至少需5天，当前计划短1天，应另找合规及时路径|后项必须等到库才开始，顺序任务应相加而非取最大值。',
'3天足够，因为运输最长|取最长只适用于可完全并行的情况，本题明确顺序依赖。',
'2天足够，只要最终检验完成|题设检验只能在货物到库后开展，不能省略前面的三天运输时间。',
'只要期货已盈利，交割日可以单方延后|经济盈亏不赋予修改交割期限的权利。'],calc('3+2-4',1,'天时间缺口'));
q('仓单部分注销与质押释放的可用量','题设一张仓单最初登记100吨，已注销提货20吨；剩余中原有50吨质押，今天已有效解除其中15吨。只有未注销且未质押部分可用于交割，当前可用多少吨？',[
'45吨|存续80吨，仍质押35吨，可交付80−35=45吨；解除质押不恢复已注销货物。',
'65吨|这是从初始100扣剩余质押35，漏扣已注销提走的20吨。',
'30吨|只扣原质押50，没有反映已生效释放的15吨。',
'95吨|把释放15吨直接加到存续80吨，重复增加了实际库存。'],calc('100-20-(50-15)',45,'吨可交割仓单'));
q('期货结束不自动结束仓储计费','题设实物交割所有权已转给买方，但仓库约定仓储费计至实际提货日。买方交割后迟十天提货，认为期货已结束所以不付后续费用，如何判断？',[
'仍需按仓储合同承担新增保管费用|期货交割与提货保管是不同环节，费用终点依题设仓储约定。',
'期货合约终止会自动取消所有仓储合同|一个交易结束不能无条件解除独立保管约定。',
'后续费用必由期货卖方承担，与条款无关|题设已按买方取得后继续保管计费，不能忽略约定。',
'把交割价调低就算已支付所有未来费用|未约定费用包含和抵扣安排，不能自行冲减。']);
q('可选择交割地点与买方物流预算','题设卖方可在两个指定地点之一交货，买方只按离自己更近地点预算运费。为什么预算不完整？',[
"卖方可选另一地点，买方须把该地点的到厂运输成本纳入|合同把地点选择权交给卖方，买方不能只按最有利地点预算而忽略另一合格交付路径。",
"两个地点都获交割认可，因此到买方工厂的运输成本也相等|符合交割资格只说明可以在那里履约，不保证两处到工厂的路线、距离或运输费用相同。",
"买方按最近地点编制了预算，就可要求卖方照该地点交货|单方预算不改变合同中的选择权，卖方仍可依条款选择另一指定地点。",
"期货已锁定货物成交价，所以交割后的到厂运费无需再估计|锁定合约货价并不自动覆盖指定交货地之后的物流支出，仍需按合同费用范围核算。"]);
q('提货权取得与现货销售回款不同','贸易商交割取得货物提货权，计划再卖给客户。其资金表把取得提货权当作已收到客户货款，主要错误是什么？',[
"取得货物权利与销售收款分属不同步骤，应另列变现安排|交割使企业取得资产或请求权，后续仍需完成下游销售和收款，不能直接记成现金已到账。",
"只要交割资产按市场报价入账，就可按同额列作下游回款|资产估值反映账面价值，不证明已对下游成交或收款，现金表不能用报价替代银行到账。",
"只要对下游开出销售发票，就可把货款记为已到账的资金|发票可能对应应收款和未履行的支付安排，开票事实本身不等于客户资金实际到账。",
"与下游约定了信用销售价格，就可以省去收款日的资金安排|价格确定不消除账期与信用风险，约定稍后付款的应收款仍不能满足当前现金需求。"]);
q('逐批品质门槛不能用合并均值替代','题设交割要求每一独立货批蛋白含量至少10%，不允许混配后合并检验。甲乙两批等重，检测值分别14%和8%。卖方以总平均11%申报两批全部合格，如何判断？',[
'甲符合该指标，乙不符合；合并平均不能代替逐批准入判断|合同规定检查单元为每批，另一批的高含量不能转移给低于门槛的乙批。',
'两批都合格，因为等重平均11%超过10%|平均值计算正确，但使用了与合同不同的验收单元。',
'两批都不合格，因为只要一批失败就必须连带否定另一批|题设逐批判断，乙不合格不自动改变甲的检测结果。',
'只要把两批编号合为一个，实际质量就会自动改变|记录合并既不改变物质含量，也不能绕过禁止混配合检的条款。']);
q('运输保险与交割合格性的区别','题设货物已买运输保险，卖方因此忽略交割品牌和质量证明。复核首先应指出什么？',[
"保险保障损失，不能代替交割品牌、质量证明等资格条件|运输保险处理承保风险的赔偿，与合约规定什么货物可交付及需要什么证明属于不同要求。",
"保险金额只要覆盖全部货值，就可用足额赔偿替代品质要求|足额保险没有修改标的质量条款，保险价值覆盖不能自行使不合格货物成为合格交割品。",
"保险公司已受理投保，就可视为交易所认可全部交割品牌|保险受理不等于交易所进行资格审核，两种机构的判断目的和凭证功能不同。",
"货物已经安全到库，品牌和质量单证便可在交付时省略|运输未损毁不证明品牌和质量满足合同要求，安全到库与必要交割证明仍须分别核对。"]);
q('补足差额现金不等于完成实物交割','题设只允许规定品质商品实物交割，未经同意不得改现金。卖方无货，拟自行按市价与合约价差汇款并声称义务终结，正确评价是？',[
'未经有效约定不能单方以价差款代替规定实物义务|经济差额近似不等于合同履约方式可以自行更改。',
'所有期货都允许卖方自行选择现金差额结算|结算方式须遵守具体合约，题设明确只允许实物。',
'只要汇款超过保证金就必然履约完成|保证金和交割义务不同，金额超过不自动获得替代交付权。',
'把汇款备注写成交割就可改变合同性质|付款备注不能单方面修改已经约定的履约方式。']);

// Batch C: distinct technical-data decisions and agricultural supply/use analysis.
Object.assign(EXPANSION_DERIVATIVES_SOURCES,{
 expansionDerivMA:{title:'CME · Understanding Moving Averages',url:'https://www.cmegroup.com/education/courses/technical-analysis/understanding-moving-averages',kind:'official',note:'2026-10-14实际读取Calculating Moving Average及Using Moving Averages；只采用SMA/EMA定义，不把技术信号当确定预测。'},
 expansionDerivOsc:{title:'CME · Oscillators: MACD, RSI, Stochastics',url:'https://www.cmegroup.com/education/courses/technical-analysis/oscillators-macd-rsi-stochastics',kind:'official',note:'2026-10-14取得正文；采用MACD均线差、RSI涨跌幅比较及背离概念。公式与窗口按题设；不采用所有振荡指标都有固定上下界的笼统表述。'},
 expansionDerivATR:{title:'Fidelity · Average True Range',url:'https://www.fidelity.com/learning-center/trading-investing/technical-analysis/technical-indicator-guide/atr',kind:'reference',note:'2026-10-14取得Description及Calculation；核验真实波幅考虑昨收与跳空。'},
 expansionDerivBands:{title:'Fidelity · Bollinger Bands',url:'https://www.fidelity.com/learning-center/trading-investing/technical-analysis/technical-indicator-guide/bollinger-bands',kind:'reference',note:'2026-10-14取得Description及Calculation；只用均线加减标准差倍数的构造，不采纳必然反转说法。'},
 expansionDerivFix:{title:'CME · Fixing prices',url:'https://www.cmegroup.com/markets/fixing-price.html',kind:'official',note:'2026-10-14取得正文；定价窗口和成交量加权的概念，窗口与交易数字为原创题设。'},
 expansionDerivGrains:{title:'USDA ERS · Feed Grains Database Documentation',url:'https://ers.usda.gov/data-products/feed-grains-database/documentation',kind:'official',note:'2026-10-14取得Data Items、Supply and Disappearance、Marketing Years正文；核验供需分类、收获面积和营销年度。所有数据为教学设定，不采用网页最新预测。'},
 expansionDerivCrop:{title:'CME · Understanding Grains Volatility and Supply & Demand',url:'https://www.cmegroup.com/education/courses/introduction-to-agriculture/grains-oilseeds/understanding-grains-volatility-and-supply-demand',kind:'official',note:'2026-10-14取得Weather、Price of Inputs、Other factors；用于农业供需渠道，不把定性因素当价格方向保证。'}
});
section('futures1',8,'futures1-8','expansionDerivMA','Calculating Moving Average：滚动窗口、指数平滑；案例C1');
q('移动平均更新必须移出旧观测','某期货昨日5日简单均价为100，窗口最早一日收盘90，今天收盘110。更新到今日5日均价时应得到多少？',[
'104|原窗口总和500，移出90并加入110后为520，再除5。',
'105|把昨日均价与今日价格直接二等分，错误改变了样本权重。',
'101.67|把昨日五日全部保留再加入今天，计算成了六日均价。',
'110|只保留最新收盘，没有计算规定的五日滚动窗口。'],calc('(5*100-90+110)/5',104,'价格单位'));
q('EMA递推中的新旧权重','题设EMA今日值=0.25×今日收盘+0.75×昨日EMA。昨日EMA100、今日收盘108，更新值是多少？',[
'102|最新价格只占四分之一，旧平滑值保留四分之三，结果为100+0.25×8。',
'106|把新旧权重对调，误令最新价格占四分之三。',
'104|按简单二等分处理，没有使用题设指数平滑权重。',
'108|完全舍弃旧平滑值，相当于没有进行平滑。'],calc('.25*108+.75*100',102,'EMA价格单位'));
q('EMA初始化差异与预热窗口','两个程序使用完全相同的后续价格和0.2平滑系数，但起始EMA分别为90和110。若不重置，启动后的结果短期仍不同，最合理的核对是什么？',[
'检查初始化及预热长度，起始差异每步保留80%并逐渐衰减|递推含有上一期EMA，种子值会留下逐步缩小的影响，短期不一致不必然是公式错误。',
'只要输入新价格相同，第一次更新后就必须完全一致|新价格权重只有20%，旧种子的80%差异仍会进入更新值。',
'两程序差值每期固定增加20，属于EMA固有规律|相同新输入会抵消，差值按旧值权重衰减而非线性增加。',
'应任意删除其中较低的结果，较高EMA总更准确|高低本身不能判断实现质量，需比较明确的初始化和窗口约定。']);
q('均线多头排列与新发生上穿不同','昨日短均线103、长均线100；今日短均线104、长均线101。策略只在由下向上的新交叉日建仓，今天是否出现该事件？',[
"没有新上穿，短均线昨日和今日都位于长均线上方|两日短长均线差都为3，确认的是上方状态持续，而不是由下方转到上方的新事件。",
"有新上穿，今日短均线104已经高于今日长均线101|只检验当日位置会把既有上方排列重复当成新交叉，遗漏此前两线的位置关系。",
"有新上穿，两条均线今日都比各自昨日提高了1点|各自上涨说明数值方向，不能证明两条线的相对位置在昨日到今日之间发生穿越。",
"有新上穿，今日短均线104超过了昨日长均线100|交叉判定须比较相同时点的两条线，拿今日短线对昨日长线不能证明新相对穿越。"]);
q('指标周期数与实际时间跨度','交易员把10根五分钟K线的均线与10根日K线均线当作相同十日趋势，哪项纠正最准确？',[
'两者观测周期不同，前者约覆盖50分钟交易数据，后者覆盖10个交易日|相同周期数不等于相同时间跨度，必须连同数据频率说明指标。',
'只要参数都是10，指标的经济时间尺度就完全相同|参数计数作用于各自数据频率，分钟和日不能直接互换。',
'五分钟均线一定预测五天后的收盘价|指标采样频率不自动定义可准确预测的未来期限。',
'将五分钟线乘以日均线价格即可统一期限|价格相乘改变量纲，却不能把分钟历史变成日历史。']);
q('未完成K线信号与收盘确认','规则要求整点小时K线收盘后确认上穿。10时40分指标已上穿但11时收盘又回落，程序仍记11时出现有效信号，应怎样处理？',[
'将10时40分视作临时盘中状态，按11时最终数据判断规定的收盘信号|使用形成中的K线与使用完成的K线是不同策略，记录应与约定确认时点一致。',
'盘中发生一次上穿就永远构成收盘上穿|后续价格可以改变该根K线最终均线位置，临时状态不等于最终确认。',
'只要盘中交易曾有盈利，就可改称收盘信号|是否盈利不改变实际信号出现时间或策略定义。',
'把11时收盘价替换为10时40分价格即可完成验证|这样改写数据会把不同时间点伪装为规定的收盘观测。']);
section('futures1',8,'futures1-8','expansionDerivOsc','MACD、RSI与背离；全部算式和配对时点按题设');
q('MACD零轴与信号线的不同比较','题设MACD=短EMA−长EMA，信号线为MACD的平滑值。当前短EMA105、长EMA100、信号线6，哪项同时正确？',[
'MACD为正但低于信号线，两种判断并不矛盾|MACD=5，零轴比较的是两条价格均线，信号线比较的是5与其平滑值6。',
'MACD为负，因为当前低于信号线|低于信号线不等于低于零，混淆两个不同参照基准。',
'MACD一定高于信号线，因为短EMA高于长EMA|短减长为正只能确定MACD高于零，不能确定与6的大小关系。',
'信号线等于6说明期货价格当天上涨6|信号线是指标平滑值，不是期货单日价格变化金额。']);
q('MACD跨品种比较的价格尺度','甲期货报价约100、MACD为2；乙报价约10000、MACD为20。经理只因20更大就断言乙相对动量更强，最主要遗漏是什么？',[
"MACD是价格差，应先明确归一化基准再比较相对强弱|绝对均线差保留报价量纲，20与2分属不同价格尺度，不能直接当作可比的百分比动量。",
"只要每手合约单位相同，就可直接比较20与2的相对动量|合约单位相同并不使标的价格水平相同，绝对价格差与相对百分比变化仍是两种口径。",
"将MACD分别乘每手数量后，金额更大的就有更强相对动量|换算成每手金额仍是绝对敞口，未除以相应基准价值，不能因此获得无量纲的相对强度。",
"把MACD都换成最小报价跳数，就可忽略两品种的价格水平|跳数统一的是各自报价网格，并非占价格水平的百分比，仍不能自动形成相对动量的共同尺度。"]);
q('RSI使用平均上涨和下跌幅度','题设RSI=100−100/(1+平均上涨幅度/平均下跌幅度)，两项平均值为0.8和0.2。按此定义，RSI是多少？',[
'80|相对强度为4，RSI=100−100/5=80；下跌幅度以正数计量。',
'60|把上涨减下跌的0.6直接乘100，不符合比值转换公式。',
'400|这是平均涨跌比4乘100，遗漏RSI把比率映射到0至100的转换。',
'20|把平均下跌占总幅度的比例当作上涨强度，方向颠倒。'],calc('100-100/(1+.8/.2)',80,'RSI'));
q('全平窗口的RSI零除约定','某窗口价格全部相同，平均上涨和平均下跌均为0。软件直接计算两者比值而报错。最恰当的工程处理是什么？',[
'明确并记录全平窗口的边界约定，避免把0/0当作有效市场强弱证据|普通比值在该边界未定义，需固定可复现处理，不能凭空解释为极强上涨或下跌。',
'平均下跌为零，所以无论平均上涨是否为零都证明最强上涨|同时没有上涨时，零分母不能单独证明市场有上涨动量。',
'把0/0随意改成任意大数且无需披露|不同替代值可能触发不同交易，边界规则需一致并可审查。',
'补写一个虚构上涨日即可使历史指标合法|人为修改真实价格会制造不存在的信息和交易信号。']);
q('区间位置与当日阴阳线可并存','题设随机指标K=100×(收盘−近段最低)/(近段最高−近段最低)。近段区间80至100，今日开盘99、收盘98。哪项正确？',[
'K为90且今日收盘低于开盘，两项可以同时成立|K比较收盘与多日区间，阴阳线比较当日开收盘，参照区间不同。',
'今日下跌所以K必须低于50|当日相对开盘下跌并不排除收盘仍靠近多日区间上沿。',
'K为90说明今日收益率为90%|K是区间相对位置，不是从开盘到收盘的收益率。',
'收盘98小于开盘99，所以近段最高只能是99|近段最高来自整个指定窗口，不由今天开盘一个值决定。'],calc('100*(98-80)/(100-80)',90,'K值'));
q('背离判断必须配对同一价格波峰','规则要求比较连续两个价格波峰对应的指标。第一次价格峰100时指标70，第二次价格峰110时指标65；第二峰前一天指标曾为80。应如何判断规则中的顶背离？',[
"比较70和65，价格峰升高而对应指标降低，符合判据|题设要求指标值与两个价格波峰同步配对，第二峰前一天的80不属于被指定的第二个配对点。",
"比较70和80，指标创新高，所以这两次价格峰没有背离|80来自第二峰前一天，任意换用中间指标高值违背题设按价格波峰时点进行配对的规则。",
"只比较100和110，价格继续新高就可排除指标顶背离|顶背离恰是价格更高而对应指标未同步升高，单看价格不能判断两者关系是否背离。",
"比较70和65确认背离后，就能据此确定下一日必然下跌|历史判据成立不等于未来方向已被确定，仍不能由两组观测保证下一交易日表现。"]);
section('futures1',8,'futures1-8','expansionDerivBands','Description/Calculation：上下轨的均值与标准差分解');
q('布林上下轨扩张与中心不变','题设上轨=均价+2倍标准差，下轨=均价−2倍标准差。均价保持100，标准差由2增至4，哪项描述正确？',[
"上轨104升至108，下轨96降至92，中心仍为100|标准差由2增至4，两侧各按两倍标准差外扩，均价没有改变，因此带宽扩大而中心不移动。",
"上轨104升至108，下轨96升至100，中心升至104|这把标准差增加对两条轨道都当作正向影响，实际上它在下轨公式中应被减去。",
"上轨仍为104，下轨仍为96，中心不变所以带宽不变|固定的是均价项，波动项已经改变；不能因中心不变便忽略两边标准差项的扩大。",
"上轨104降至102，下轨96升至98，中心仍为100|这错误地让标准差翻倍时两侧距离减半；题设固定倍数的轨道距离应随标准差增加。"]);
section('futures1',8,'futures1-8','expansionDerivATR','Calculation：真实波幅取当日区间及相对昨收的最大值');
q('真实波幅不能遗漏隔夜缺口','昨收100，今日最高112、最低109。按TR=max(高−低,|高−昨收|,|低−昨收|)，今日真实波幅是多少？',[
'12|三个候选为3、12、9，取最大值12，包含从昨收到今日高位的缺口。',
'3|这仅为日内高低差，漏掉隔夜跳空形成的更大价格变化。',
'9|这是最低价相对昨收的距离，未取三个候选中的最大值。',
'24|三个候选不是相互独立的区间，不应把它们简单相加。'],calc('Math.max(112-109,Math.abs(112-100),Math.abs(109-100))',12,'价格单位TR'));
section('futures1',8,'futures1-8','expansionDerivFix','Fixing price：成交量加权与明确窗口；原创基准比较');
q('VWAP基准不是逐笔价格等权平均','题设指定窗口只有两笔成交：100元1手、110元9手。买入实际均价108元；若以窗口成交量加权价评估，哪项正确？',[
'窗口VWAP为109，买入均价比该基准低1|应以手数作权重；用105的等权笔均价会把同一执行错误地评为差3。',
'窗口基准105，买入比基准差3|把大小悬殊的两笔成交等权，未使用题设成交量加权基准。',
'窗口基准110，买入比基准低2|只使用最后成交价，遗漏早期1手对整个窗口基准的贡献。',
'买入均价108必须同时是市场VWAP|本订单实际成交均价与全部市场成交的基准不是同一数据集。'],calc('(100*1+110*9)/10-108',1,'元低于窗口VWAP'));
section('futures1',8,'futures1-8','expansionDerivCases','案例C2：图表坐标与价格数据解释；数学尺度由题设明确');
q('等距对数刻度与等额涨幅不同','题设图表纵轴使用对数刻度。价格由50升至100与由100升至200，两段图上高度相同。正确解释是什么？',[
'两段均翻倍，百分比涨幅相同，但绝对涨额分别50和100|对数刻度的距离对应价格比值，不能据相同图高认定金额变化相同。',
'两段绝对涨额都为50，因为视觉高度相同|这把线性坐标的等额间距性质误套到对数坐标。',
'第二段百分比涨幅只有第一段一半|两次末值都是初值的两倍，百分比涨幅均为100%。',
'使用对数坐标会让真实账户收益自动变相同|图形显示不改变合约数量、实际价格差和金额损益。']);
section('futures1',8,'futures1-8','expansionDerivGrains','Data Items：供给、使用、库存、收获面积和营销年度；案例C3');
q('供需平衡中的期末库存残值','题设单位万吨：期初库存20、产量100、进口10、国内使用85、出口25，无损耗或其他项目。供需表期末库存应是多少？',[
'20|总可用130，国内加出口使用110，余下20；库存是平衡后的存量。',
'45|只扣国内使用，遗漏出口也会减少本地区可用库存。',
'−10|只将产量100与国内使用85、出口25比较，遗漏期初库存和进口。',
'70|把出口当成增加国内供应的项目，收支方向用反。'],calc('20+100+10-85-25',20,'万吨期末库存'));
q('收获面积不能替换为播种面积','题设播种100万公顷，其中10万公顷因灾不收获；预计每公顷实际收获面积产6吨。若单产估计正确，产量应是多少？',[
'540万吨|单产定义以收获面积为分母，应以90万公顷乘6，而不是全部播种面积。',
'600万吨|把没有收获的10万公顷也按正常单产计入产量。',
'60万吨|这是损失面积按正常单产计算的潜在减少量，不是剩余总产量。',
'666.67万吨|将产量反向除以收获比例，反而在受灾后增加预测供给。'],calc('(100-10)*6',540,'万吨产量'));
q('库存增加但库存使用比下降','某商品期末库存由20升至22，年度总使用量由100升至125，统计口径相同。只据此，库存相对使用的缓冲怎样变化？',[
"库存使用比由20%降至17.6%，相对缓冲下降|原比率20÷100为20%，新比率22÷125为17.6%；使用量增长更快，因此库存吨数增加仍可伴随比率下降。",
"库存使用比由20%升至22%，相对缓冲上升|22%把新库存22仍除以旧使用量100，遗漏本期使用量已经增长到125。",
"库存使用比维持20%不变，相对缓冲保持相同|库存和使用量同向增加不代表同比例变化，两项增长率不同会改变库存相对使用的比率。",
"库存使用比由20%降至2%，相对缓冲大幅下降|2%是库存增量2相对原使用100的比例，不是期末库存22与本期使用125的水平比率。"],calc('22/125*100',17.6,'新库存使用比百分数'));
q('营销年度与日历年度的需求错配','题设玉米营销年度为9月至次年8月，研究员以该期产量配同名日历年1月至12月消费量，直接求余额。首要修正是什么？',[
'将供给、消费及库存起止时点统一到同一期间再编平衡表|两个年度重叠但并不相同，混配会遗漏或重复部分月份的流量。',
'只要年份标签都含2026，就属于相同期间|标签相似不能替代明确的月度起止范围。',
'把消费除以12再乘12即可完成日期调整|总量缩放不改变其涵盖的月份，无法补出缺失时段。',
'只调整价格币种就能使供需年度一致|币种与时间覆盖是不同维度，货币转换不能修复期间错配。']);
q('未装运销售承诺与实际出口的关系','题设期初未装运出口订单30万吨，本周新销售12、取消2、实际装运8，无其他调整。周末未装运量应如何记录？',[
'32万吨；装运8从未装运转为已出口，不能再留在未装运量内|订单存量=30+12−2−8，销售承诺与实际出境是两个不同阶段。',
'40万吨；实际装运不会影响未装运订单|已经履行的8万吨应从待履行余额扣除，不能继续作为未完成承诺。',
'48万吨；装运和新销售都增加待装运量|装运是履约流出，不是新的未装运合同。',
'20万吨；把本周净销售10从期初订单扣掉|新增净销售增加承诺存量，只有取消与装运在此模型中减少它。'],calc('30+12-2-8',32,'万吨未装运量'));
q('残差饲用量不能当直接观测需求','供需表把饲用及残差定义为总供给减其他使用减期末库存。其他项不变时，统计部门上修产量10，残差也增加10。能否证明牲畜真实多吃了10？',[
'不能，平衡残差会机械吸收供给修订，须另找实际饲喂证据|该项目包含统计平衡成分，不是完全独立直接测量的消费记录。',
'能，表中使用量增加必全部来自真实额外消费|忽略残差由其他估计相减得到，修订可在没有新饲喂行为时改变它。',
'能，产量修订会自动使所有牲畜即时增加食量|统计估计的改变不构成真实消费行为的因果机制。',
'不能，因此任何供需平衡表都没有分析用途|识别残差局限不等于否定平衡表，正确做法是结合独立证据解释。']);
section('futures1',8,'futures1-8','expansionDerivCrop','Weather、Price of Inputs、Other factors：分层供需渠道；原创情景');
q('总产量不变而食用品质供给下降','暴雨后粮食总吨数基本不变，但一部分食品级降为仅能饲用。食品加工厂只看总产量判断原料供应无变化，遗漏了什么？',[
'食品级可用供给减少且饲用替代供给可能增加，需要按用途分层|总吨数不变可以掩盖品质结构变化，不同需求者可用的供给并不相同。',
'全部用途的有效供给都必然与总吨数同比不变|食品用途有品质限制，降级货不能无条件替代原食品级原料。',
'食品级与饲用级必定同时同幅上涨|两个细分供需变化不同，不能从总吨数或质量事件推出相同价格变化。',
'只要商品名称不变，品质对采购完全没有影响|实际生产用途可能要求具体品质，名称不能替代适用性判断。']);
q('同样降雨在不同作物阶段的解释','题设甲地作物正处缺水生长期，乙地作物已成熟待收获；同样的持续降雨到来。基本面分析首先应怎样区分？',[
"甲评估缺水缓解，乙评估收获延误或品质影响，分别判断|天气对供给的作用依赖生长阶段与前期状态，不能仅凭同样降雨量就套用相同价格方向。",
"两地降雨量相同，就应把单产和上市时间作相同幅度调整|缺水生长期和成熟收获期的影响渠道不同，单一毫米数不足以规定相同的产量及进度变化。",
"甲地可能因补水受益，就可将相同增产比例直接用于乙地|成熟作物未必继续通过同样生长渠道增产，持续降雨还可能妨碍收获或影响品质。",
"乙地作物已成熟，所以未来供给数量和品质不再受降雨影响|成熟不等于已顺利收获并进入流通，收获损失、延误和品质变化仍可能影响可用供应。"]);
q('出口受限的内外市场分化','题设某出口国临时停止发运，国内产量和国内需求短期不变、货物暂不能转运其他出口市场。分析其境内与进口方市场时，哪项最合理？',[
'出口国境内待售货可能增加，依赖其供应的进口方可得货可能减少|贸易通道受阻可令不同地区供给方向相反，不能无条件推断全球各地同涨同跌。',
'出口减少必使出口国境内货物同步减少|原拟出口货物暂留境内，并非因为少出口就物理消失。',
'全球总产量必下降与禁运数量相同|改变跨境流向不等于改变已经生产出的总数量。',
'进口方可以把未到港合同自动当作已到港库存|法律承诺和可使用的实物库存不同，发运中断不能由账面替代。']);
section('futures1',8,'futures1-8','expansionDerivGrains','Data Items：农户年度均价、动物单位和用途差异；原创分析');
q('农户年度均价不是年末可成交现价','报告给出某作物营销年度农户平均售价，按全年各月实际销售数量加权。贸易商想以该数直接锁定今天到港采购成本，为什么不合适？',[
'该数综合不同月份和农户销售分布，不是今天指定交货条件的可执行报价|历史年度均价服务于收入和市场统计，不能直接代替当前地点、品质和交期报价。',
'全年数据越多，平均值就自动成为今天的成交承诺|样本规模不能让历史统计数变成当前交易对手可执行价格。',
'只要它按数量加权，就包含今天所有运费与关税|权重规则不自动扩展价格所覆盖的交付条款和成本项目。',
'年度均价必须等于最后一个交易日收盘|加权全年销售与取年末单个时点是不同的计算定义。']);
q('牲畜头数相同不代表饲料需求相同','题设两种动物日均耗料分别1和5单位。养殖区总头数保持100，但高耗料动物由20增至40，其他条件不变。应怎样评价谷物饲料需求？',[
'需求会增加，应按动物构成和耗料系数估计，不能只看总头数|100头的结构改变使高耗料动物占比上升，相同存栏总数不代表相同饲料用量。',
'总头数没变，饲料需求必不变|这等同假定所有动物耗料相同，与题设1和5的差别冲突。',
'高耗料动物增加必使每头低耗料动物吃得更少并完全抵销|题设各类单体耗料不变，没有这种自动抵销机制。',
'只需比较动物出售价格，不必考虑耗料差异|价格可能影响未来经营选择，但当前物理耗料仍须依构成计算。']);
section('futures1',8,'futures1-8','expansionDerivCases','案例C4：原创受约束生产、收入风险及供需识别模型');
q('共同土地约束下的相对种植收益','农户可耕地固定，只能种甲或乙。甲预期每亩净收益由500升至550，乙由480升至600，其他种植条件相同。只因甲收益提高就预测甲面积必扩大，忽略什么？',[
'土地有机会成本，乙相对收益提高更多可能吸引面积转向乙|固定土地要在备选作物间分配，应比较相对净收益而非只看甲的绝对改善。',
'任何作物收益上升都允许总土地无限增加|题设土地固定，两个作物面积扩张存在共同约束。',
'净收益已扣成本，所以不需要与其他用途比较|扣除会计成本仍不排除放弃另一作物收益的机会成本。',
'甲原先收益更高，就永久拥有全部新增面积|原先排序可被新的相对收益反转，不构成长期固定选择。']);
q('加工停产决策不能只看含固定成本利润','题设加工每吨产品收入100、可避免变动成本80、当期无论开停都必须支付的固定成本30，无产能机会成本。只比较本期现金贡献，继续加工与停产相比怎样？',[
"继续加工每吨比停产多贡献20|加工增加收入100并新增可避免成本80，固定30在两方案下相同，故本期增量现金改善20。",
"继续加工每吨比停产少贡献10|100减80减30是加工全成本利润，但停产仍付固定30，不能把该利润直接当两方案的差额。",
"继续加工每吨比停产多贡献100|固定支出虽不因决策改变，加工仍新增80的可避免变动支出，不能将全部销售收入当增量贡献。",
"继续加工与停产的现金贡献相同|两者固定费用相同只使该项在比较中抵销，仍需计入加工独有的收入100与变动支出80。"],calc('100-80',20,'元/吨相对停产现金改善'));
q('产量价格相关时的预期收入','农户两种情景各半：丰收卖120吨、价格2万元/吨；减产卖80吨、价格3万元/吨。分析员用平均数量100乘平均价格2.5估计收入250万元，错误在哪里？',[
'应先逐情景求收入再平均，正确期望为240万元|两情景收入均240；数量与价格相关，平均乘积不等于两个平均数相乘。',
'应取较高单价乘较高产量，收入360万元|把互不同时发生的丰收数量和减产价格拼接，制造了不存在的情景。',
'250万元正确，任何随机量都可先平均再相乘|乘积的期望通常还受协方差影响，不能一般性拆成均值乘积。',
'应取两个收入相加480万元，不乘概率|两情景互斥且各半，求期望需按发生概率加权而不是同时实现。'],calc('.5*120*2+.5*80*3',240,'万元预期销售收入'));
q('价格数量同降与需求移动的识别','题设短期供给曲线固定且向上倾斜，无其他变化。某商品均衡价格和成交数量同时下降，哪种变化与模型最一致？',[
'需求曲线向左移动|在给定向上供给曲线上，需求减少使均衡价格和数量同时下降。',
'需求曲线向右移动|其他条件不变时会推动价格和数量上升，与观察方向相反。',
'沿原需求曲线因供给增加而移动|供给被题设固定，且供给增加通常使价格下降、数量上升。',
'仅价格计量单位改变且实际数量完全不动|这不能解释题设中真实成交数量也下降的事实。']);
q('需求弹性与支出变化不能混同','题设某商品价格下降10%，购买量按给定近似增加3%，分析只考虑这两个变化。总采购支出相对原值约是多少？',[
'92.7%，支出下降但降幅不是简单的10%|新支出=0.90×1.03=0.927，数量反应部分抵销价格下降。',
'90%，因为支出只随价格变化|采购支出同时取决于数量，题设已经给出数量增加。',
'103%，因为买得更多必定花得更多|数量增加并不保证总支出增加，还要结合更低的单价。',
'113%，因为将价格降幅与数量增幅都当增加相加|价格下降应降低单价，且价格和数量需相乘而不是把变动率同号相加。'],calc('.9*1.03*100',92.7,'新支出占原支出百分数'));

Object.assign(EXPANSION_DERIVATIVES_SOURCES,{
 expansionDerivExercise:{title:'OIC · Options Exercise FAQ',url:'https://www.optionseducation.org/referencelibrary/faq/options-exercise',kind:'reference',note:'2026-10-14实际读取提前行权、分红与通知时差、停牌问题正文。仅背景核验，所有境外式行权及交收条款在题干给定，不解释为境内统一规则。'},
 expansionDerivAdjust:{title:'OIC · Splits, Mergers, Spinoffs & Bankruptcies FAQ',url:'https://www.optionseducation.org/referencelibrary/faq/splits-mergers-spinoffs-bankruptcies',kind:'reference',note:'2026-10-14实际读取交付证券、现金收购及分拆篮子各段。仅核验调整可能改变交付物的机制，不复制其拆股数字或假定中国合约采用同一规则。'}
});
section('options',3,'pricing','expansionDerivCases','案例D1：明示二叉模型中的美式最优停止；行权权利原理见OIC Exercise');
q('美式节点须比较继续持有与立即行权','题设美式认沽K=100，当前标的80；下一期到期可能为100或60，无股息，一期无风险增长因子1.05，风险中性上涨概率0.6。无费用，当前节点应如何估值和行动？',[
'价值20，立即行权优于继续价值约15.24|继续价值=(0.6×0+0.4×40)/1.05≈15.24，立即取得100−80=20，应取两者较大。',
'价值15.24，任何二叉树都只允许折现未来收益|这遗漏美式当前节点可停止并取得20的额外权利。',
'价值35.24，把行权价值与继续价值相加|立即行权与继续持有是互斥选择，不能同时获得两种路径的权利。',
'价值40，应选择未来最有利情景而不考虑概率|未来40不是确定可得，估值不能把最大情景当当前无条件价值。'],calc('Math.max(100-80,(.6*0+.4*40)/1.05)',20,'当前节点期权价值'));
section('options',1,'lifecycle','expansionDerivExercise','FAQ：提前行权、分红归属、通知和停牌；合同细节为题设');
q('指派通知晚于分红权利确定时点','题设美式认购已在除息日前有效行权，合同规定对应股息归行权买方；卖方直到除息日后才收到指派通知。卖方因通知晚而把这笔股息列为自身确定收入，哪项正确？',[
'应按有效行权及权利归属调整股息，通知到达较晚不改变既定归属|经济权利以题设有效事件确定，不以卖方读到通知的时刻重新开始。',
'通知晚于除息日就自动取消先前有效行权|题设行权已经有效，通知时差不是撤销事件的条款。',
'收到现金股息的一方一定最终拥有股息，不会有后续调整|先收到现金不必然代表最终权利，可能需要按合同完成对应补偿或转付。',
'所有认购卖方只要持仓曾备兑就永久保留分红|备兑提供交付来源，不排除有效行权改变股票及股息归属。']);
q('提前处置比较可实现净现金而非中价','题设美式认购立即行权并出售所得股票，可实现内在价值5元，全部相关费用0.20；卖出期权可执行买价4.75，卖出费用0.05，中价显示5.40。若目标是立即退出取得最多净现金，选择哪项？',[
'行权并卖股净得4.80，高于卖期权净得4.70|应比较实际可实现的两条现金流；中价5.40没有承诺成交，不能据其时间价值否定行权路径。',
'卖出期权净得5.35，因为中价减费最高|用不可直接成交的中价代替可执行买价，夸大退出所得。',
'卖出期权净得4.95，因为应把手续费加回|手续费是退出支出，应从4.75扣除而不是相加。',
'行权并卖股净得5，行权费用不属于决策成本|题设要求立即净现金比较，两条路径实际发生的费用都必须纳入。'],calc('(5-.20)-(4.75-.05)',.1,'行权路径多得净现金'));
section('options',1,'contracts','expansionDerivAdjust','FAQ：并购调整交付物、全现金交付及分拆篮子；全部参数是题设');
q('证券与现金交付篮子的实值判断','题设调整认购每张行权须支付30×100=3000元，取得50股甲公司股票及700元现金；甲股现价50元。忽略费用，按整个交付篮子计算每张内在价值是多少？',[
'200元|交付篮子价值50×50+700=3200，减行权总支付3000得200，不能只比较股票现价50与显示行权价30。',
'2000元|把50−30直接乘原100乘数，忽略当前交付仅50股且另含现金。',
'0元|只计算50股的2500价值，遗漏合约同时交付的700元现金。',
'700元|这是交付物中的固定现金部分，不是扣除全部行权支付后的净权利价值。'],calc('Math.max(50*50+700-30*100,0)',200,'元/张内在价值'));
q('全现金交付确定后的股票波动输入','题设收购已不可撤销完成，调整后美式认购现在可支付3000元取得确定现金3200元，无其他条件或费用。估值员继续用原股票高波动率制造额外上涨机会，主要问题是什么？',[
"改按确定现金权利估值，原股票波动已不对应交付物|合同已不交付未来变动价值的股票，不能继续使用失去经济对象的股价路径创造额外上行价值。",
"继续采用原股票波动率，因为合约名称仍带有原股票代码|名称不是经济交付内容，估值应跟随已生效的固定现金权利而非原代码。",
"改用收购方股票波动率，因为确定现金由该公司提供|支付现金的主体不使收购方股票成为本合约交付资产，不能因此引入其股价上行。",
"把所有现金结算期权的波动率设零，统一当固定现金估值|普通现金结算金额仍可能取决于未来指数等随机参考，本题关键是金额已确定而不只是以现金付款。"]);
q('分拆篮子期权的第二证券风险','题设调整期权的交付篮子含20股甲和10股乙，乙是分拆后独立交易公司。风险系统只加载甲价格，把乙市值固定为零。最直接的遗漏是什么？',[
'合约价值同时依赖乙的市场价值，须纳入乙及两者共同变化的情景|一个调整合约可以包含多种证券，沿用旧单一标的映射会漏掉真实交付风险。',
'乙由甲分拆，所以乙价格永远与甲保持固定比例|公司关系不构成独立证券交易价格固定比例的合同保证。',
'只要期权代码仍含甲名称，乙的交付义务就不存在|名称不能覆盖已经生效的交付条款，应以实际篮子组成识别风险。',
'将甲的波动率直接加倍必能精确代替乙|第二证券有独立变动和相关性，任意放大单一参数不能保证重现篮子风险。']);
section('options',3,'pricing','expansionDerivParity','Put/Call Parity：对匹配欧式期权恒等式求导及终值复制；原创检验');
q('由平价关系检验同要素Greeks一致性','题设无股息欧式期权、相同K和到期及模型输入，满足C−P=S−PV(K)。系统报告认购Delta0.6、认沽Delta−0.4，Gamma分别0.03和0.05。哪项核对结论正确？',[
'Delta差为1符合恒等式，但两者Gamma不等应查实现或输入一致性|右侧对S的一阶导为1、二阶导为0，因此Delta差1且Gamma差0。',
'Delta必须互为相反数，所以0.6和−0.4一定错误|平价要求二者之差为1，不要求绝对值相同。',
'Gamma允许任意不同，因为认购和认沽方向相反|头寸类型的方向差已体现在一阶项，匹配欧式价格差对S是线性函数。',
'只要两种Gamma都为正，就已通过全部一致性检验|正号仅是单项性质，不能替代跨合约恒等关系的核对。']);
q('认购价差与认沽价差加现金的同终值比较','同到期执行价100和110。买100认购卖110认购净付4；卖110认沽买100认沽净收6；同期到期支付10的无风险债券现价9.8。假定交易均可执行且无费用，哪种同终值方案较便宜？',[
'认沽价差加债券成本3.8，比认购价差少0.2|认沽价差终值比认购价差恒少10，补上到期10的债券才可比较；成本9.8−6=3.8。',
'认沽价差本身收6，因此与认购价差完全同终值且免费|它在低价区域须支付10，缺少补足固定差额的现金资产。',
'认购价差更便宜，因为4小于9.8|遗漏认沽方案开仓收到的6，未按完整组合净成本比较。',
'两者成本必相同，因为教科书平价不允许比较实际报价|无套利恒等式用于检验报价，不保证每组给定可执行报价已满足它。'],calc('4-(9.8-6)',.2,'同终值初始成本差'));
section('options',3,'payoffs','expansionDerivCases','案例D2：非负标的域、比率结构及逐段收益；不重复普通价差代数变式');
q('跨式下侧代数根可能不在价格域','题设普通标的价格只能非负，长跨式K=100，全部不可退成本120，忽略利息，终值为|S−100|。其可实现的到期盈亏平衡价格有哪些？',[
'只有220，代数根−20不在允许的价格域|在S为零时下侧最大终值只有100，仍不能覆盖120成本，只有上侧能回本。',
'−20和220都可作为该标的实际价格情景|负根虽满足形式方程，但违反题设标的非负的定义域。',
'只有100，因为它是两腿共同行权价|S=100时终值为零，正好是损失全部120成本的位置。',
'没有任何平衡点，因为成本大于行权价|认购一侧随S上涨没有给定上限，220处仍能形成120终值。']);
q('认沽反向比率结构的中段最大亏损','题设买2份K=90认沽、卖1份K=100认沽，净收2，标的非负，同日到期无费用。下列哪项同时正确？',[
"S=90亏8、S=0赚82，最差点为S=90|S≤90时净损益82−S，90至100时为S−98，100以上为2，故最差为S=90时亏8。",
"S=90亏8、S=0亏98，最差点为S=0|零价时遗漏两份90认沽多头共180的价值，只计算100认沽空头会颠倒尾部结果。",
"S=90赚2、S=0赚182，最差收益为2|只保留两份认沽多头和初收2，遗漏卖出100认沽在中段及零价时的履约负担。",
"S=90亏10、S=0赚80，最差点为S=90|这是未计初始净收2的毛支付，题目净损益必须将该已收权利金加入各情景。"]);
section('options',3,'delta-gamma','expansionDerivGamma','Gamma：局部曲率、非线性联合情景及到期不可微边界；原创重估表');
q('联合压力重估不能简单相加单因素变化','组合基准价值10；只冲击标的后价值12，只冲击隐波后价值13，同时实施两种冲击后的完整重估价值16。若把两个单因素增值直接相加，遗漏多少？',[
'遗漏1的交互及其他非线性效应，合并增值应为6而非5|单因素变化分别2和3，但联合变化为16−10=6；完整重估已给出更可靠的该情景结果。',
'遗漏10，因为三个情景都应各加一次基准值|基准价值应在求变化时一致扣除，不能在组合增值中重复加入。',
'没有遗漏，因为两种风险名称不同就必然可加|输入名称不同不保证定价函数对两个变量完全可分。',
'应把12和13相加为25，才是联合价值|直接加两项情景总价值重复计算基准，也未使用实际联合重估16。'],calc('(16-10)-((12-10)+(13-10))',1,'联合变化相对单项和的差'));
q('由对称价格重估提取Gamma','题设其他输入固定，S=99、100、101时某期权模型价分别4.60、5.00、5.50。按中心二阶差分估计S=100附近Gamma，应是多少？',[
'0.10|Gamma约为(5.50−2×5.00+4.60)/1²，先消去线性斜率再估计曲率。',
'0.45|这是两侧一阶差商(5.50−4.60)/2，估计的是Delta而不是Gamma。',
'0.50|这是从100至101的单侧价格增量，未扣除一阶敏感度。',
'20.10|把中心价格正加两次，没有按二阶差分减去2倍中心值。'],calc('(5.50-2*5+4.60)/(1*1)',.1,'Gamma近似值'));
q('到期折点处不存在唯一普通导数','到期认购价值为max(S−100,0)。在恰好S=100处，从左和从右看价值对S的斜率分别是多少，能否据此称普通导数必为0.5？',[
"左0、右1；普通导数不存在，0.5只能另作约定|到期支付连续但存在尖角，左右斜率不同，临近到期模型数值不证明到期函数可微。",
"左0、右1；取两侧均值0.5就是该点普通导数|普通导数要求双侧极限相同，不是只要两侧存在就可以用平均数代替。",
"左0.5、右0.5；实值概率对半使支付函数处处光滑|题设是确定的到期支付函数，不是到期前平滑估值，虚值与实值两段斜率分别为0和1。",
"左1、右0；上涨后认购进入饱和区，敏感度下降|普通认购虚值侧支付不变、实值侧随标的一比一增加，不存在这里所称的上行支付饱和。"]);
Object.assign(EXPANSION_DERIVATIVES_SOURCES,{expansionDerivAssignment:{title:'OIC · Options Assignment FAQ',url:'https://www.optionseducation.org/referencelibrary/faq/options-assignment',kind:'reference',note:'2026-10-14取得正文末段原成交对手与指派关系、开仓卖对平仓买情形；具体集中分配机制在题设明确，不套用为中国市场细则。'}});
section('options',1,'lifecycle','expansionDerivAssignment','FAQ末段When I sell an option to open：成交对手可为买入平仓，存续空头进入指派分配池');
q('卖出开仓的对手买平不消除指派义务','题设集中清算对同系列未平空头分配有效行权。A卖出开仓10张，成交对手B恰在买入平仓其旧空头，原有其他多头仍持有权利。A认为此笔没有新增权利仓，故自己不可能被指派，错在哪里？',[
'A承接了存续空头义务，其他持有人的有效行权仍可按机制分配给A|开平配对使市场总未平仓可不变，但B退出不等于A取得的新空头没有对应的存续权利。',
'说法正确，只有卖开与买开相遇才可能产生任何履约义务|卖开对买平是空头持有人替换，A的新义务并不因总持仓不增加而消失。',
'A应等B重新开多后才开始准备履约|集中分配不以原成交对手未来重新开多为前提，其他存续多头可行权。',
'B买入平仓会同时把A卖出开仓变成卖出平仓|两账户开平标记各自决定持仓变化，对手的平仓不会改写A的有效开仓指令。']);
section('options',3,'delta-gamma','expansionDerivCases','案例D3：原创动态对冲现金流及Gamma-Theta近似模型；参数均明示');
q('同一终点下动态对冲现金流不同','为对冲认购，先在S=100卖空0.5股；S涨到110时再卖空0.2股；S回100时买回0.2股，最后在100买回其余0.5股。忽略利息费用，仅对冲股票交易的现金盈亏是多少？',[
'赚2，但不能据此断言含期权成本后的总策略赚钱|股票流入50+22，流出20+50，净2；期权自身损益及时间成本还须另计。',
'零，因为标的起终点都为100|中途改变了持股数量，交易现金流具有路径依赖，不能只用初末价格差。',
'赚7，因为价格一度上涨10且曾有0.7股空头|空头在上涨期间不是获利方向，且0.7股并非全程在100开仓。',
'亏2，因为所有卖空回补都必然亏损|实际新增0.2股在110卖、100买回，产生正2的已实现现金差。'],calc('.5*100+.2*110-.2*100-.5*100',2,'股票对冲现金盈亏'));
q('含交易费的Gamma收支平衡方差','题设Delta对冲的简化损益模型为1000×(实现方差−0.04)−4，方差与0.04均按同一期年化口径，4为全部执行费。按此模型，至少达到哪个实现方差才能不亏？',[
'0.044，即4.4%的方差数值|令损益为零需实现方差−0.04=4/1000；这里是方差阈值，不是4.4%的波动率。',
'0.04，因为实现波动与隐含波动相等就无条件回本|相等只抵销模型中的风险收支，仍未覆盖4的执行费用。',
'0.20，因为0.04的平方根是20%|把波动率数值直接填入要求方差的模型，混淆了平方关系。',
'0.036，因为费用可从所需实现方差扣除|费用提高回本门槛，应加到所需实现方差而不是降低它。'],calc('.04+4/1000',.044,'回本实现方差'));

Object.assign(EXPANSION_DERIVATIVES_SOURCES,{
 expansionDerivSOFR:{title:'CME · Understanding SOFR Futures',url:'https://www.cmegroup.com/education/articles-and-reports/understanding-sofr-futures',kind:'official',note:'2026-10-14实际读取Price=100 minus rate、SR1/SR3最终结算、参考期、已知与未知利率混合等正文。只用一般构造；题目日数、精度和报价均明示，不要求记忆境外合约现行参数。'},
 expansionDerivNDF:{title:'BIS · Non-deliverable forwards: impact of currency internationalisation and derivatives reform',url:'https://www.bis.org/publications/qr-201612/non-deliverable-forwards-impact-currency-internationalisation-and-derivatives-reform',kind:'reference',note:'2026-10-14读取正文中NDF差额结算定义；2016分析支持稳定机制，不用于宣称当前市场规模或资本管制现状。'},
 expansionDerivICS:{title:'CME · Treasury Analytics Intercommodity Spread Tool',url:'https://www.cmegroup.com/tools-information/quikstrike/quikstrike-treasury-analytics-user-guide-ics.html',kind:'official',note:'2026-10-14实际读取ICS Components、ICS Statistics与DV01定义；区分执行腿数比例、价差报价与风险比例。实际数值和组合由题设给出。'}
});
section('futures1',4,'futures1-4','expansionDerivCases','案例D4：含价格上限、保底付款和数量选择权的实体合同风险映射');
q('采购合同价格上限改变局部套保量','题设企业每吨采购价=min(市场指数P,100)，数量确定且无其他价差。当P=120且小幅变化仍高于100时，继续按每吨一份普通线性期货多头对冲，主要问题是什么？',[
'采购价在该区间已固定100，额外期货多头会新增局部方向风险|价格上限使采购支出对P的局部斜率为零，不能在所有状态机械使用一比一线性套保。',
'采购价始终等于P，因此任何价格都需要一比一多头|题设min函数在指数高于100时进入封顶区间，敏感度发生变化。',
'合同有上限就说明任何价格区间都没有风险|当P低于100时采购价仍随P变化，不能把当前局部结论扩展到全部状态。',
'期货多头会自动在P超过100后停止盈亏|普通线性期货没有题设采购合同中的封顶条款，风险不会自动同步截断。']);
q('最低付款数量与实际耗用量不同','题设企业签订必须按到期浮动指数支付100吨的合同，不提货也必须付款，不能退回或转售。实际生产计划降至60吨。核定该合同的指数价格付款敞口，应采用哪一数量？',[
'100吨，并单独记录40吨不再有生产用途的经营损失风险|付款义务未随实际耗用减少，价格套保应映射仍不可取消的指数付款。',
'60吨，因为只有真正消耗的原料才可能形成付款|题设不提货仍须付款，实际用途不改变已经确定的合同义务。',
'40吨，因为闲置部分才有价格波动|使用部分和闲置部分都按同一到期指数付款，不能只算闲置量。',
'零吨，因为生产计划变化能自动取消原合同|题设明确不得取消或转售，内部预测调整不解除外部义务。']);
q('买方数量选择权使成交量依赖价格','供货商允许客户到期按固定100元选择采购80至120单位；客户可从市场无障碍采购替代品。题设市场价高时客户倾向多提、低时少提。用固定100单位远期完全复制此合同，遗漏什么？',[
'客户拥有与价格相关的数量选择权，卖方面临非固定数量的或有交付|成交量可能在对卖方较不利的价格状态扩大，不能只以平均数量视作普通固定量远期。',
'数量上下限对定价无影响，因为平均值是100|平均数量不能刻画选择权与价格共同变化的现金流。',
'客户既可多买也可少买，所以选择权价值必然为零|选择权由客户行使，正负数量变化不保证在不同价格状态下公平抵销。',
'固定单价意味着卖方任何未来采购成本都固定|卖方若需市场补货，其成本仍受市价和客户选择数量影响。']);
section('futures1',5,'futures1-5','expansionDerivCases','案例D5：期现配对、跨月恒等与执行后的风险净额；规则均为题设');
q('期转现配对中实物买方的期货方向','题设实物买方A原持期货多头，实物卖方B原持相同数量空头；双方以有效期转现安排交付实物并相互了结已有期货。期货腿应怎样配对？',[
'A卖出平多，B买入平空；实物腿仍由B向A供货|原套保持仓需以反向期货交易了结，不能把购买实物方向照搬为再次买期货。',
'A买入开多，B卖出开空，从而自动结束旧持仓|两方各自同向加仓会扩大而非结束原有期货持仓。',
'双方都卖出期货，因为需要减少风险|B原为空头，应买入了结；两笔同向卖出也不能互为成交对手。',
'只完成实物转账便可在没有约定期货处理时删除交易所持仓|实物履约不自动改写独立的期货清算记录，需要按有效安排完成期货腿。']);
q('跨月价差三角关系的中间月份抵销','同品种同单位三个月合约A、B、C，定义X=A−B、Y=B−C、Z=A−C。若三个价差可同时无费用成交，X=2、Y=3、Z=6，怎样识别不一致？',[
"买X和Y、卖Z；复制成本5低于Z报价6|X加Y的B空头与多头抵销，复制A−C；再卖Z抵销剩余A和C，题设无费用同时成交可锁定差额1。",
"买Z、卖X和Y；Z报价6高于复制成本5|这在6买入同一经济组合并在5卖出复制物，方向会锁定不利差额而不是获取报价不一致的收益。",
"买X、卖Y和Z；两个价差中的B会自行抵销|卖Y会把其中B多头变为空头，与买X中的B空头同向，不能实现题设所需的中间月份抵销。",
"只卖Z而不买X和Y；较高报价足以锁住差额1|没有反向复制组合时仍暴露于A与C的价差变化，单独卖出不能把当前报价差变为确定现金收益。"],calc('6-(2+3)',1,'复制价差偏离'));
section('futures1',7,'futures1-7','expansionDerivICS','ICS Components/Statistics：交易腿数比与DV01权重分离；题设组合');
q('固定比例组合后的残余DV01微调','题设一个可执行组合含买2手A、卖1手B；多头A与B的DV01分别40和100，正DV01代表利率下降1bp的收益。已买2个组合，要把净DV01调零且只补A，应怎样做？',[
'再买1手A|两个组合合计4A−2B，净DV01=160−200=−40，补1A增加40后为零。',
'再卖1手A|原残余已为−40，卖A再减40会扩大而非抵销敞口。',
'不补，因为交易所组合比例必然等于实时风险中性比例|执行方便的固定腿数比不保证与当前DV01恰好相符。',
'再买2手B，因为两组合包含2手B空头|完全回补B会留下4手A的正风险，未按净敏感度目标求调整量。'],calc('(2*100-4*40)/40',1,'需额外买A手数'));
q('净变动报价与有符号价差水平','题设屏幕价差报价定义为今日完整价差水平（有符号的A−B）减昨日同口径水平。昨日完整价差为50，屏幕现在显示4。交易员把4当作可直接比较的完整价差水平，正确恢复值是多少？',[
'54|报价4只是相对昨日基准的净变动，完整水平=50+4。',
'4|忽略报价明确使用的基准，把变化量当成水平量。',
'46|题设显示正4，代表相对基准上升，应相加而不是相减。',
'200|基准水平与价格变动相加即可，不是把两者相乘。'],calc('50+4',54,'完整价差水平'));
section('futures1',9,'futures1-9','expansionDerivCases','案例D6：实体延后定价的信用暴露与组合担保变化');
q('货权已转让的延后定价销售','题设粮商已把货权交给买方，成交价将在下月按指数确定、货款届时支付，买方不能退货。粮商仍把全部已交货物列为自有可质押库存，主要应如何修正？',[
'区分已转出的货权与未结价应收款，同时管理买方信用和剩余价格风险|已交货不等于已收款，也不能继续把同一批货当作仍由自己控制的自由库存。',
'尚未确定单价，所以货权必然还属于粮商|题设货权已转让，定价状态和所有权状态不是同一条件。',
'货权转让后原卖方就没有任何风险|未收款存在信用暴露，指数尚未确定还可能留下价格风险。',
'只要期货套保足额，买方不付款也能自动补足全部货款|期货管理价格变化，不是对买方全部应收账款的信用保险。']);
q('抵押折扣合格仍须满足发行人集中上限','题设某衍生品保证金要求认可担保至少80万元，其中单一发行人债券认可价值不得超过总认可价值40%；现金无此限制。现有现金40万元和该债券市值100万元，债券折扣10%，不能用其他资产。最少还需补多少现金才能达标？',[
'8万元；现金至少48、债券认可32可组成合规80万元|集中上限使至少60%的认可担保必须来自现金，80×60%=48；已有40还差8。',
'0万元，因为40现金加90认可债券远超80|总额足够不代表组合合规，若依靠大量同一债券会违反40%的集中上限。',
'4万元，因为只需补债券10%的折扣差|折扣影响市值认可，集中比例是另一个独立约束，不能只补折扣。',
'40万元，因为任何单一发行人债券都完全不能使用|题设允许其占认可担保最多40%，并非禁止使用全部此类债券。'],calc('80*(1-.4)-40',8,'万元最少新增现金'));

section('futures1',7,'futures1-7','expansionDerivNDF','NDF差额结算定义；报价、名义币及换算公式全部由题设明确');
q('NDF差额从报价币换为结算币','题设美元多头NDF名义100万美元，约定7.00人民币/美元，定盘7.20；人民币差额按(7.20−7.00)×100万美元，再按定盘汇率换成美元支付。多头应收约多少美元？',[
'27777.78美元|人民币差额200000元，除7.20人民币/美元才是美元结算额，不能把两种币的数字直接混用。',
'200000美元|200000的单位是人民币，尚未换成题设结算币美元。',
'28571.43美元|用约定7.00而非题设明确的定盘7.20作最后换算。',
'1440000美元|将人民币差额再乘人民币/美元，币种量纲不成立。'],calc('(7.2-7)*1000000/7.2',27777.77777777778,'美元应收NDF差额'));
section('futures1',7,'futures1-7','expansionDerivSOFR','Price=100 minus rate、已知与未定参考期、日数加权、最终结算精度；所有条款均题设');
q('100减利率报价下的套保方向','题设短端利率期货报价=100−年化利率百分数，利率预期由3%升至4%时价格由97变96。企业担心未来浮动融资成本上升，需要从这一变化获利的期货方向是什么？',[
'卖出该利率期货，价格下降时空头获利|需要先把利率上升转换为报价下降，不能把对利率看涨直接等同买入合约。',
'买入该期货，因为企业担心的是利率上升|期货报价与利率按100减R反向，买入会在97降96时亏损。',
'买卖均相同，因为100减R只影响显示不影响损益|显示报价是实际计价依据，合约价格方向决定多空盈亏。',
'只要融资成本会上升，任何期限的任意利率期货都能完全抵销|即使方向正确，还需匹配参考利率、期限和敏感度，不能忽略基差。']);
q('月平均期货中的未实现利率反推','题设30天月均利率合约隐含全月平均4%，前20天实际平均3.5%已固定，日数等权且忽略风险溢价。剩余10天隐含平均利率应为多少？',[
'5%|全月目标利率日累计30×4=120，已实现20×3.5=70，余50除10得5。',
'4%|把包含已实现低利率的全月平均直接当剩余区间平均，无法使合计达到4。',
'4.5%|按两个区间等长处理，忽略20天与10天的权重差异。',
'3.5%|沿用已实现水平会使全月仍为3.5，不能解释给定4的市场报价。'],calc('(30*4-20*3.5)/10',5,'剩余十天隐含年利率百分数'));
q('隔夜利率观测需按覆盖自然日加权','题设月平均利率按自然日算术加权。某段只有两次公布：4%适用于周五至周日3天，5%适用于周一1天。该四天平均应为多少？',[
'4.25%|不同观测覆盖天数不同，(4×3+5×1)/4=4.25，而非对两个公布数字等权。',
'4.5%|只数两次公告，漏掉4%实际覆盖三个自然日。',
'9%|把两个年利率直接相加，没有按日数形成平均。',
'1.125%|先等权平均再除4，对平均数重复除以天数且仍未使用正确权重。'],calc('(4*3+5)/4',4.25,'四日平均年利率百分数'));
q('后置复合利率与期初已知期限利率不同','题设贷款A在期初一次重置三个月期限利率，贷款B按未来三个月每日隔夜利率后置复合，二者期初预计成本相同。资金预算为何不能把B整季利息也视为当日确定？',[
'B还取决于尚未发生的每日利率，预计相同不代表现金流已经固定|A的本期重置值已锁定，B的实现值需随未来利率逐日累积，确定性时点不同。',
'同为三个月就必须在同一天固定全部利息|期限长度相同不说明利率观测和确定方式相同。',
'B每日公布利率，所以期初已知未来全部每日值|每天逐步知道新值不等于一开始知道整个未来路径。',
'预期成本相等就说明二者在所有未来情景下都付相同金额|一个期望数相同不能替代逐状态现金流匹配。']);
q('最终结算精度不必等于交易最小价位','题设某利率期货可交易报价最小步长0.005，但合约明确最终结算价四舍五入到0.0001。计算得最终结算96.1234，系统因非0.005整数倍拒绝入账，哪里错了？',[
'把委托撮合价位规则误用于最终结算，应按题设结算精度入账|交易网格与结算公式可采用不同精度，需识别字段的业务用途。',
'任何最终结算价都必须向下调到交易网格|题设已明确四位小数规则，不能擅自增加向下取整条件。',
'结算精度更细就意味着客户可报任意四位小数委托|反过来也不成立，结算规定不会自动放宽交易报价最小步长。',
'应把96.1234当作利率百分数而不是合约价格|题设该数已是计算完成的最终结算价，问题是验证规则而非字段身份转换。']);
q('利率期货月份标签与实际风险窗口','题设甲合约名称为九月，但参考期是九月中至十二月中、十二月结算；乙九月到期，参考的是六月中至九月中。企业管理九月至十二月隔夜融资风险，应优先核对哪份？',[
'甲，其参考期间与待管理利率发生期更接近|选择应依据现金流所对应的利率观测窗口，不能只凭到期月份与九月文字相同。',
'乙，因为所有九月融资风险都必须选九月到期|乙主要反映此前六月至九月的利率，与未来九月至十二月不匹配。',
'甲乙相同，因为都能找到九月两个字|同一月份可能分别表示参考期起点或终点，名称不能代替日期表。',
'选任意更远合约，因为期限越长套保误差必越小|更长并不保证对应同一风险窗口，期限错配仍可能增加基差。']);

// Batch E: futures 0219 onward. Specific execution protocols, reference-rate and curve mechanics.
Object.assign(EXPANSION_DERIVATIVES_SOURCES,{
 expansionDerivOrders:{title:'CME · Futures Order Types',url:'https://www.cmegroup.com/education/courses/futures-trading-mechanics-and-regulation/futures-order-types',kind:'official',note:'2026-10-14实际读取Market Order与Stop Order正文。案例逐项写明订单条件，只核验市价转限价、保护范围和触发机制，不声称各中国品种提供相同订单。'},
 expansionDerivMatching:{title:'CME · How CME Group Ag Markets Operate',url:'https://www.cmegroup.com/education/articles-and-reports/overview-what-makes-ags-markets-work',kind:'official',note:'2026-10-14读取The Central Limit Order Book及Matching Algorithms，区分同价FIFO与按量分配。未采用文中历史产品比例和收费作为当前规则。'},
 expansionDerivImplied:{title:'CME · Implied Options on Globex: Livestock and Dairy',url:'https://www.cmegroup.com/education/files/implied-options-overview-agriculture.pdf',kind:'official',note:'2026-10-14读取2016资料第4–5页中真实单腿与价差生成隐含流动性的机制。题设仅借用组合原理，所有腿、价格和数量均自设；不采用历史适用产品清单。'},
 expansionDerivCTD:{title:'CME · Get to know Treasuries CTD',url:'https://www.cmegroup.com/education/courses/introduction-to-treasuries/get-to-know-treasuries-ctd',kind:'official',note:'2026-10-14读取Carry、Net basis、IRR；最低净基差与融资成本均需考虑。数值题不使用2017样例，不把最便宜现货等同CTD。'},
 expansionDerivCurves:{title:'CME · Emerging Market Discounting and Price Alignment Transition',url:'https://www.cmegroup.com/trading/interest-rates/files/emerging-market-discounting-and-price-alignment-transition-detailed-deck.pdf',kind:'official',note:'2026-10-14读取第8–9页预测曲线与折现曲线、第12页切换补偿。2021历史方案标注Pending Regulatory Approval；仅用于稳定估值机制，不声称其是当前实施规则。'},
 expansionDerivCurveTrade:{title:'CME · Yield Curve Spread Trades: Opportunities & Applications',url:'https://www.cmegroup.com/education/files/yield-curve-spread-trades.pdf',kind:'reference',note:'2026-10-14读取第2页前后期限、陡峭/平坦及DV01配比。2013研究由交易所承载，未使用历史比例、收益预测或零利率下界假设。'}
});
section('futures1',2,'futures1-2','expansionDerivOrders','Market Order：市价转限价的剩余数量处理；明确的教学订单规则');
q('市价转限价订单不持续追逐下一档','题设买入市价转限价单5手，规则为先在最优卖价成交，剩余转为该首次成交价的限价买单。卖盘100元2手、101元10手，期间不变。首次撮合后应是什么状态？',[
'成交2手，余3手以100元挂买；不会自动扫到101元|此订单的剩余部分已转成100元限价，不能按普通扫盘市价单处理。',
'5手全部成交，2手100元加3手101元|这忽略了首次价格成交后转限价的特别条件。',
'5手全部转成101元限价，没有即时成交|最优100元有2手可成交，不应跳过已有的可执行流动性。',
'成交2手后自动取消3手，因为所有市价类订单都是IOC|题设明确剩余挂限价，而非立即取消的有效期规则。']);
section('futures1',2,'futures1-2','expansionDerivOrders','Stop Order：触发价、保护边界和可执行盘口分别核对');
q('止损保护范围限定可成交档位','题设卖出止损保护单4手，成交价触及100触发，最低可执行价为98，超出保护范围不成交。触发后买盘99元1手、98元1手、97元10手，且无新增买盘。立即最多能成交多少？',[
'2手；97元的深度在保护范围之外|保护边界允许99和98两档成交，却不能为了完成数量继续卖到97。',
'4手，因为触发后所有止损单均无价格约束|本题明确提供最低保护价，不能忽略订单类型的限制。',
'1手，因为98元恰等于边界也必须排除|最低可执行价包含98这一边界，不能擅自改成严格大于。',
'0手，因为100是唯一允许成交价|100是触发价，题设允许触发后在不低于98的价格成交。'],calc('1+1',2,'保护范围内可立即成交手数'));
q('触发依据是成交还是报价必须按约定','题设某期货卖出止损仅由真实成交价小于等于100触发。最新成交仍为101，最优买报价已降至99且尚未成交。系统未触发是否符合题设？',[
'符合；报价越线尚未满足真实成交越线的触发条件|触发字段明确为成交，不能用盘口买价替换，即使两者在快速行情中可能差异很大。',
'不符合；任何买报价下降都应当被当作成交|报价表达交易意愿，不证明已有订单在该价成交。',
'不符合；止损必须在第一次出现浮亏时触发|题设使用指定价格和数据字段，与个人成本或浮亏无关。',
'符合；下一步应只等每日结算价降至100以下再触发|题设使用实时成交价，不能改为日终结算价这一不同数据字段。']);
section('futures1',2,'futures1-2','expansionDerivCases','案例E1：显式假设下的隐藏量、分配、条件单驻留及原子减仓');
q('冰山单显示量不能替代总未成交量','题设一笔卖单总量20手，每次最多显示5手；当显示部分成交完自动补充。已经累计成交7手、未撤单，系统当前显示3手。客户问这笔订单还有多少手可能继续卖出，应答多少？',[
'13手，包括当前显示3手和仍隐藏的10手|总剩余是20减累计成交7；显示量只是订单当前公开的一部分。',
'3手，因为盘口没有显示的数量必定已经取消|题设隐藏量仍有效，盘口可见范围不等于客户订单总余额。',
'17手，因为只需从总量减当前显示3手|当前显示不是已成交，不能将两种状态相减作为余额。',
'20手，因为隐藏订单每次补充都会恢复完整原始数量|补充显示不生成新委托总量，累计成交仍应扣减。'],calc('20-7',13,'总未成交手数'));
section('futures1',2,'futures1-2','expansionDerivMatching','Matching Algorithms：题设纯按数量比例、无需舍入的同价分配');
q('按比例撮合不等于排队第一全拿','题设同一价位两笔买单甲6手、乙4手，甲先到；本次明确只按挂单数量比例分配，无优先量、无舍入问题。新来5手可成交卖单，甲分得多少？',[
'3手|甲占同价总量6/10，本次分配5×6/10=3，时间先后不替代题设比例规则。',
'5手，因为甲在队列最前且有足够数量|这是FIFO结论，不能套用于题设明确的纯比例算法。',
'2.5手，因为两个客户应无条件平均分配|题设依据数量份额而非人数，6手与4手权重不同。',
'6手，因为甲申报了6手就必须全部满足|本次对手总量只有5手，不能给单一买家分配超过成交总量。'],calc('5*6/(6+4)',3,'甲获配手数'));
section('futures1',5,'futures1-5','expansionDerivImplied','第4–5页Implied IN/OUT；题设线性组合的可执行价格与最小腿容量');
q('隐含价差报价需要正确取两边盘口','题设可原子执行买A卖B，单位和腿数均一比一。A最优卖价101有8手，B最优买价98有3手，其他价格不考虑。由这两笔真实订单生成的买入A−B隐含报价是多少？',[
'净支付3，最多3组|买A取卖价101，卖B取买价98；组合容量由较少的B买量3限制。',
'净支付3，最多11组|两腿是配对履约关系，容量不能把8与3相加。',
'净收入3，最多3组|买入较贵A再卖较便宜B需要支付差额，不能颠倒现金流符号。',
'净支付199，最多8组|组合价格是买入支出减卖出收入，不是两价格相加，也不能只看A深度。'],calc('101-98',3,'每组净支付价格'));
section('futures1',9,'futures1-9','expansionDerivCases','案例E2：条件单驻留位置与交易引擎原子执行规则');
q('本机条件单未送交易所时的断线处理','题设止损条件由客户电脑监测，触发后才发送普通委托。电脑已断网，平台仅有“条件已保存”记录，没有交易所委托回报。此时应如何理解保护状态？',[
'条件可能无法监测或发送，应按既定应急渠道核实并恢复受控下单能力|本机保存不等于交易所已接收可触发订单，驻留位置决定断线时的工作依赖。',
'平台有条件保存回执，就可视为交易所已受理同一止损订单|回执只证明本机条件配置保存，题设明确还没有交易所委托受理回报。',
'恢复网络后立刻重复发送整笔止损，无需核对持仓与既有委托|断线期间其他渠道可能已成交或下单，应先核实状态，避免重复退出或形成反向仓位。',
'把本机历史触发时间填作交易所受理时间即可证明保护有效|本机监测记录不能替代外部受理证据，改写时间也无法补上未发送的实际委托。']);
q('引擎原子仅减仓限制的并发退出','题设账户仅有3手多头，无其他开仓；两笔卖单各3手，都带交易引擎原子校验的“仅减仓”标记，规则不允许因此形成空头。两单几乎同时到达，可确定什么？',[
'两单合计最多卖出平掉3手；剩余部分被限制或拒绝|原子校验在每次执行时按实际剩余持仓控制，不以两单最初各看到3手为由允许卖出6手。',
'两单一定全部成交6手，随后系统再自动买回3手|题设是执行前原子限制，不是成交后纠偏；不能先制造反向仓位。',
'两单一定都拒绝，因为系统无法处理同时订单|题设提供原子处理机制，并未规定并发时全部拒绝。',
'“仅减仓”保证这3手一定能立即按原止损价成交|该标记限制头寸方向与数量，不提供对手流动性或成交价格保证。']);
section('futures1',7,'futures1-7','expansionDerivNDF','差额结算参考汇率与实际换汇渠道；题设明确两种定价来源');
q('NDF定盘对冲仍留下实际兑换基差','企业未来需买美元，NDF按官方定盘汇率结算损益，但实际美元采购只能按银行可执行卖价。题设两种汇率之间的差额会变化。即使NDF名义数量和日期匹配，仍须管理什么？',[
'银行实际卖价相对官方定盘的差额风险|NDF只补偿指定参考汇率变化，不自动支付实际换汇渠道中额外扩大的点差或偏离。',
'没有任何汇率相关残余，因为名义金额相同已充分|数量匹配未消除结算指数和实际成交价之间的基准差异。',
'只需把NDF结算币改为美元就能让银行按官方价格出售|支付币种不改变银行真实卖价，也不会改写可执行换汇条件。',
'应在预算中把官方定盘和银行卖价都当作同一笔完整美元成本相加|两者用于不同计算，重复计入全额成本无法衡量真正的差额风险。']);
section('futures1',7,'futures1-7','expansionDerivForward','公开Summary：互换由分期现金流估值；题设固定年金与浮动腿现值');
q('公允互换固定利率由现值相等求解','题设一笔不交换本金的两期互换，本金100，两次固定付息均按1年计息，两期折现因子之和1.80；同本金浮动腿现值为9。初始价值为零的年固定利率是多少？',[
'5%|固定腿现值=100×K×1.80，令其等于9得K=0.05；不能仅用两次未折现本金相除。',
'4.5%|9除以200忽略两期现金流折现，固定腿现值将低于浮动腿9。',
'9%|把全部浮动腿现值当成单期利息，并遗漏年金现值权重。',
'16.2%|将浮动腿现值再乘折现因子总和，颠倒了求固定利率所需的除法。'],calc('9/(100*1.8)',.05,'公允年固定利率'));
section('futures1',7,'futures1-7','expansionDerivCurves','第8–9页：预测曲线产生现金流，折现曲线产生现值；显式简化估值模型');
q('预测曲线变动不能只改折现因子','题设互换估值系统先用预测曲线算未来浮动利息，再用独立折现曲线折现。本次只有预测曲线提高、折现曲线保持不变。复核应要求重算哪一步？',[
'重算浮动腿预计现金流，再以原折现因子计算现值|两个曲线作用不同，预测输入变化即使不改变折现因子仍会改变尚未固定的利息。',
'只提高折现率，所有浮动息金额保持原样|这把预测曲线与折现曲线的角色对调，既错改折现又漏改现金流。',
'完全不重算，因为折现曲线没变则任何现值都不变|现值取决于金额和折现两方面，现金流预测改变也会使现值改变。',
'把已经固定并确认的历史票息也按新预测利率重置|预测更新针对未定现金流，不会自动改写已有固定值的合同权利义务。']);
section('futures1',7,'futures1-7','expansionDerivSOFR','已实现与未实现日数混合；参考利率敏感度按剩余权重衰减');
q('参考期走过后的利率敏感度缩减','题设30天算术平均利率期货，前20天利率已经固定；只把剩余10天的全部预期利率上调30bp。忽略其他变化，全月平均利率提高多少？',[
'10bp|只有三分之一日数仍受本次变化影响，30×10/30=10bp。',
'30bp|把已固定的20天也当作能被今天预测变化改写。',
'20bp|误用已经走过的20天作为仍能变化的风险权重。',
'90bp|应按剩余比例缩小全月影响，而不是用全月除剩余放大。'],calc('30*10/30',10,'全月平均上升bp'));
section('futures1',7,'futures1-7','expansionDerivFX','报价币种转换；双边可执行报价取倒数必须交换买卖方向');
q('倒数汇率的买卖价需要对调','同一交易商的人民币/美元报价为买7.00、卖7.10，均指交易商买卖美元。把它严格改写为美元/人民币的双边报价，哪项正确？',[
'买价1/7.10，卖价1/7.00|交易商买人民币对应原来卖美元，方向互换；这样倒数后仍保持买价低于卖价。',
'买价1/7.00，卖价1/7.10|未交换买卖方向，会人为制造买价高于卖价的交叉报价。',
'买卖两价都用中点7.05的倒数|中点只是估值参考，取中点会抹去原有可执行点差。',
'买价负7.10，卖价负7.00|反向货币报价应倒数并对调，不是对价格取负。']);
section('futures1',7,'futures1-7','expansionDerivSOFR','100减利率报价、题设允许负参考利率；平均的最终取整规则');
q('利率期货价格超过100的含义','题设某合约价格=100−参考年利率百分数，合同允许负利率且无其他价格上限。屏幕价格100.40，复核员按“债券面值100”判定异常，正确解释是什么？',[
'它对应参考利率−0.40%，不能把债券面值当作这种期货报价上限|价格由100减利率构造，负利率自然对应大于100；这不是到期偿还100的债券价格承诺。',
'它对应利率正0.40%，系统只是把符号省略|按明示公式利率=100−100.40，结果为负而不是正。',
'它必然是无风险套利，因为所有金融工具价格不能高于面值|期货报价并非一笔面值债权的现值，不能套用无关上限。',
'它表示投资者取得100.40%的保本回报|期货价格不是客户收益率承诺，也不保证投入资金不会亏损。'],calc('100-100.4',-.4,'隐含年利率百分数'));
q('平均结算只在指定最后一步舍入','题设两天利率等权平均，规定保留原始观测全部精度，最终年利率百分数四舍五入到两位小数。两天为1.244%和1.245%，应报哪个平均？',[
'1.24%|先平均得1.2445%，再保留两位小数为1.24%；不能先把每天各自四舍五入。',
'1.25%|先把两天变成1.24与1.25再平均并舍入，会改变明示计算顺序。',
'2.49%|这是错误地把两天利率相加，不是等权平均值。',
'1.2445%且拒绝最终取整|平均中间值正确，但题设仍要求最后按两位小数形成结算值。'],calc('Math.round((1.244+1.245)/2*100)/100',1.24,'最终结算利率百分数'));
section('futures1',7,'futures1-7','expansionDerivCTD','Carry=票息收入−融资成本；Net basis=Basis−Carry，均按同一口径与期限');
q('融资差异可推翻交割券毛基差排序','题设可交割A、B毛基差分别0.30和0.50，持有至同一交割日票息收入均0.80，融资成本分别1.00和0.20；其他条件相同。按净基差=毛基差−(票息−融资)判断哪券更便宜？',[
'B；A净基差0.50，B净基差−0.10|A虽毛基差低，但融资贵；把期间净持有成本计入后，B的交割经济成本较低。',
'A；只要毛基差0.30小于0.50就无需考虑融资|毛基差未覆盖持有到交割的全部成本，融资差异足以改变排序。',
'两券相同，因为票息都为0.80|相同票息并未消除不同融资成本，净持有收益仍有差别。',
'A；融资成本越高，做交割反而收到的补贴越多|融资成本是持仓支付的代价，不是交易所给予的额外补偿。'],calc('(.3-(.8-1))-(.5-(.8-.2))',.6,'A净基差高于B的数值'));
section('futures1',5,'futures1-5','expansionDerivCases','案例E3：期限间距不相等时，对水平与线性斜率同时中性的价差构造');
q('不等距月份蝶式不能照搬一负二加一','同单位期货到期距今1、2、4个月，价格恰沿直线为100、102、106。研究员要构造对任何整体平移和线性期限斜率都为零的组合。哪组权重满足目标？',[
'2、−3、1|权重和为0且期限加权和2×1−3×2+1×4=0，既去掉水平也去掉线性斜率。',
'1、−2、1|权重和为0但期限加权和1−4+4=1，因月份不等距仍残留线性斜率。',
'1、−1、1|权重和为1，整体价格平移就会改变组合价值，尚未去掉水平。',
'1、0、−1|这是首末期限价差，直接暴露线性斜率，不是消去斜率的蝶式。'],calc('2*100-3*102+106',0,'线性期限价格下组合值'));
section('futures1',7,'futures1-7','expansionDerivCurveTrade','第2页Steepener的短期限多、长期限空；风险权重按题设匹配');
q('收益率曲线变陡不等于买入长期债','题设短、长期限国债期货组合已按两腿相等DV01配平，忽略凸性和基差；预计长期收益率上升10bp、短期上升2bp。哪种组合从这次变陡中获利？',[
'买短期期货、卖长期期货|短腿多头因加息2bp亏损，长腿空头因加息10bp获利；相同DV01下净收益对应8bp差。',
'卖短期期货、买长期期货|这一组合是偏向收益率差缩窄，本题长期上升更多会使其净亏损。',
'同时买入两腿，因为两种收益率都上升|债券价格与收益率反向，两腿同多会同时遭遇利率上升损失。',
'只比较两腿名义本金相等即可，无需DV01配平|相同本金不保证价格敏感度相同，可能留下主导损益的水平风险。']);
section('futures1',9,'futures1-9','expansionDerivCases','案例E4：明确清偿顺序下的抵押实现与剩余无担保回收');
q('抵押回收后只能对剩余债权计算回收率','题设衍生品正向终止债权100万元，先用可最终实现40万元的抵押物抵偿，剩余无担保债权回收率25%，无其他优先债权及费用。最终信用损失多少？',[
'45万元|抵押收40，剩余60回收15，总收55；无担保回收率不能再作用于已被抵押抵偿的40。',
'35万元|用100×25%再加抵押40，重复给已抵偿部分计入无担保回收。',
'60万元|扣除抵押后全损，遗漏题设剩余债权还能回收25%。',
'75万元|仅按全额债权的25%回收，漏掉明确可实现的抵押价值。'],calc('(100-40)*(1-.25)',45,'万元最终信用损失'));
section('futures1',7,'futures1-7','expansionDerivCurves','第12页Cash Compensation Mechanism；原现值减新现值的题设切换补偿');
q('折现方法切换的现金补偿与新估值分开','题设清算估值方法切换前，客户有利互换现值12；切换后同一合同现值10，安排立即给客户现金2以保持当时经济价值。客户报表同时列新现值10和现金2，正确评价是什么？',[
'当时合计价值仍为12；不能再保留旧现值12并额外加现金2|现金补偿弥合方法切换造成的现值差，旧估值应被替换而非与新现金重复并存。',
'客户净赚2，因为只要收到现金就代表额外利润|新合同估值同时下降2，需合并两项才能判断整体财富变化。',
'客户仍亏2，因为现金补偿不属于任何资产|已收到的现金是资产，应与新合约现值共同反映本次切换。',
'现金补偿后所有未来利率敏感度也必然完全不变|当时价值补齐并不保证新折现体系对后续市场变化的敏感度相同。'],calc('10+2-12',0,'切换时整体价值变化'));
section('futures1',7,'futures1-7','expansionDerivForward','远期价值的现金流复制；已付保证金不抵扣仍存续的交割价');
q('可退还履约保证金不是远期货款预付','题设企业签订到期付款100万元的实物远期，另交可全额退回的履约保证金10万元；合同明确保证金不冲抵货款、到期收货后下一日退还。企业到期只筹90万元，错误在哪里？',[
'把独立可退保证金误当已经支付的货款，到期仍须准备100万元付款|保证金和交割货款按题设是两项现金流，且退款在后，不能自行净减为90。',
'应只筹10万元，因为已交保证金即完成全部付款|保证金担保履约，并不在本合同中替代到期购买价。',
'应筹110万元，因为原10万元到期必须再交一次|题设没有再次缴纳保证金义务，不能把已交款重复列为新支出。',
'无需筹款，因为实物远期都只按价差现金结算|题设明确实物交付和100万元付款，不能改用另一类合同结算机制。']);

