section('options',1,'lifecycle','expansionDerivSOQ','第1–2页：SOQ使用各股官方开盘价，不等于某一共同时间的即时指数；题设简化两股等权');
q('开盘结算篮子不必等于最后一只股票开盘时的指数','题设结算指数=(A官方开盘价+B官方开盘价)/2。A在9:30开于110，到9:45已为100；B在9:45首次开于90。无其他成分股，结算指数应为多少？',[
'100，即(110+90)/2|结算保留A已确定的官方开盘价，不在B开盘时把A替换为最新价；它可以不同于9:45的即时指数95。',
'95，即(100+90)/2|这是9:45两只股票最新价的平均，混同了共同时间快照与各自开盘价篮子。',
'105，即(110+100)/2|把A的两个时点重复列入，漏掉了应纳入的B官方开盘价。',
'110，只取最先开盘的A作为两股结算参考|最早出现的单股价格不能代替题设完整的两股开盘篮子。'],calc('(110+90)/2',100,'开盘结算指数'));
section('options',4,'risk','expansionDerivIndexSettlement','AM & PM Settlement：题设周四停交易、周五开盘确定支付、下周一到账；风险确定与资金到账分开');
q('期权停止交易与最终市场风险截止不是同一时点','题设一份AM结算指数期权周四停止交易，最终支付由周五成分股官方开盘价决定，周一现金到账。风险台计划周四停止交易后即解除全部对冲，认为后续只有收付款，哪项修正最合适？',[
'把至周五参考价确定前的隔夜和开盘风险纳入对冲计划|停止交易不等于支付金额已固定；风险期限应覆盖结算参考形成，且对冲工具仍需匹配该参考。',
'周四停止交易就冻结最终支付，按周四最后一笔期权价解除即可|最后成交价不是题设的结算参考，周五开盘仍会改变最终支付。',
'应机械保持同一指数对冲直至周一现金到账后才解除|支付金额确定后等待到账主要是现金结算问题，继续指数对冲可能新增市场敞口。',
'应统一保持至周五收盘，因为所有指数期权都以收盘确定金额|本题明确AM官方开盘参考，使用周五收盘将无依据地延长价格风险窗口。']);
section('options',4,'risk','expansionDerivExercise','Options Exercise FAQ Exercise by exception及截止程序；题设盘后仍允许提交有效行权指令');
q('收盘虚值价差仍有盘后单腿指派窗口','题设卖出K=100认购、买入同到期K=105认购，各1张100股实物交收；收盘股价99.5。盘后仍可提交有效行权指令，消息使股价升至102。仅因收盘两腿虚值便把交收风险归零，问题是什么？',[
'100认购的持有人仍可能有效行权，105保护腿不会仅因另一腿被指派而自动履约|收盘状态没有终结明示的指令窗口；两腿处置须分别确认，否则可能留下未覆盖的股票交收头寸。',
'两腿都会必然行权，因为盘后价格只要超过低行权价就触发整个组合|两份权利各有自身执行价和行权决定，低执行价实值不自动使高执行价行权。',
'两腿都会按收盘99.5固定失效，盘后尚未截止的指令只影响下一期|题设允许本期有效指令，不能将交易收盘当成已结束的行权窗口。',
'只要原先组合最大期权损失有限，就可忽略交收到股票后的风险状态|有限损益图要求对应的两腿处置条件，单腿指派与另一腿终止可改变之后实际持仓。']);
section('options',1,'lifecycle','expansionDerivOpenInterest','正文第83行：行权并指派的合约也从未平仓量移除；题设无其他交易或更正');
q('没有平仓成交也可因行权减少未平仓量','题设某期权系列昨未平仓量100张，今日没有任何交易成交，但20张有效行权并指派，其他合约仍存续且无数据更正。今日该系列未平仓量应怎样变化？',[
'降为80张；行权和指派消除20张存续合约，无需另记20张平仓成交|未平仓量统计存续合同，交易平仓不是唯一终结渠道，不能为解释减少而虚构成交量。',
'仍为100张；只有撮合的双边平仓成交才允许减少未平仓量|这遗漏了已完成行权指派的合同终结，存续统计应扣除该20张。',
'降为60张；买方行权20与卖方被指派20要各扣一次|同一20张合同的权利义务两端不能在单边口径未平仓量中重复扣减。',
'降为0张；系列出现一次行权就表示该系列全体合约已终止|题设其余80张仍存续，部分行权不等于全系列到期或全部履约。'],calc('100-20',80,'张未平仓量'));

