section('futures1',8,'futures1-8','expansionDerivCOT','Open Interest第68–69行：期权按交易所Delta转期货等价；变化可来自重估而非成交');
q('期货等价持仓增加不一定代表实际新买单','题设某COT合并口径将认购多头按Delta换算；同一交易者两期都持有1000张认购、无期货且没有任何交易。Delta由0.4变0.6，合并多头增加200手。应如何解释？',[
'这是等价敞口重估，可以没有新增200手期货买入|期货等价量随Delta变化，持仓报告的敞口差额不能不加区分地当作真实成交量或资金流。',
'必须补录200手实际买入，否则报告增加200便无法成立|本例期权张数未变而Delta变化已足以解释等价量，不应据此虚构交易。',
'认购张数未变，所以合并多头应固定1000手不受Delta影响|题设合并报表明确使用Delta等价，不能把原始期权张数替代换算口径。',
'应记为200手空头增加，因为认购Delta上升表示买方卖出|认购多头的正Delta增加对应多头等价量扩大，方向不能因没有交易而反转。'],calc('1000*(.6-.4)',200,'手等价多头增加量'));
section('futures1',8,'futures1-8','expansionDerivCOT','Nonreportable Positions第83行：分方向从总OI扣已报告量，类别和人数未知');
q('未报告持仓残差不能直接贴上散户标签','题设市场总未平仓量为1000手，已报告交易者多头800、空头750。按分方向相减得到未报告部分，哪项既符合算术又尊重报表信息边界？',[
'未报告多头200、空头250，但不能仅据此断言散户净空50手|残差是报告门槛之外的合计，不披露其人数和商业身份，未报告不等于已经识别为散户。',
'未报告多头200、空头250，因此已证明全部散户净空50手|方向残差可以算出，但把所有残差直接归为散户超出了公开数据能支持的身份结论。',
'未报告量为1000−800−750=−550，因此报表必然发生错误|同一总OI分别作为多头和空头分母，不应同时扣除两个方向的已报告量。',
'未报告多空都应200，因为任何参与者子群的多空必须相等|只有全市场合计多空相等，某一子群可净多或净空，由其他群体提供对侧。'],calc('(1000-800)-(1000-750)',-50,'手未报告部分净多头'));
section('futures1',8,'futures1-8','expansionDerivCOTClass','Trader Classification第82–85行及Potential Limitations第106–108行；分类变化不等于持仓交易');
q('交易者重分类可造成类别持仓迁移','题设一主体的300手多头本周没有变化，也无任何成交；报告根据新增业务资料将其从甲类重分类为乙类，其他记录不变。研究员把甲类减少300、乙类增加300认作两类之间的新交易，如何修正？',[
'先分离重分类造成的存量迁移，不能当作本周实际成交流量|类别标签改变会移动汇总列，但主体、合同及市场总持仓未变，需核对分类变更再解释行为。',
'认定甲类实际卖出300且乙类实际买入300，重分类等同成交|更换统计归属不是转让合约，本题明确无交易，不能由列变化反推成交。',
'把市场总未平仓量增加300，乙类新增量就是全市场新增量|乙类增加与甲类减少对应同一原有存量，全市场未平仓量没有因此增加。',
'删除该主体全部300手直到下次成交，避免分类口径冲突|存续合同不会因身份分类变更而消失，应更新类别并保留真实持仓。']);
section('futures1',8,'futures1-8','expansionDerivCOT','Old and Other Futures第104–105行：分桶后匹配与合并后匹配的spread列不可直接相加');
q('跨作物年度价差分类不满足逐列简单相加','题设同一交易者仅有旧作物年多头70手、新作物年空头50手；各年度分别先配对多空，合并表则跨年度配对，配对数列为spreading且只余未配对数列多或空。合并表应怎样列示？',[
'多头剩余20、空头剩余0、spreading为50|合并后50对跨年头寸可被配对，两个分年度表的剩余多空列不能直接当作合并列。',
'多头70、空头50、spreading为0，因为分年度都没有内部配对|合并表允许跨年度配对，分桶计算的分类结果不保持简单可加。',
'多头20、空头0、spreading为100，因为多空两腿各50|题设spreading记配对数量，双边各50构成50对，不能重复记为100。',
'多头0、空头0、spreading为70，因为较大方向决定配对数|只有50手空头可用于配对，剩余20手多头不能凭空补出对侧。'],calc('70-50',20,'手合并后未配对多头'));
section('futures1',2,'futures1-2','expansionDerivTAS','Example of a TAS transaction第41–46行：成交价差已定，但绝对结算价尚未知');
q('TAS价差限额不构成绝对采购价格上限','题设TAS买入成交价=尚未确定的当日结算价+0.1。客户最多愿付绝对价格105，当前普通期货报价100，准备仅用TAS价差上限0.1保证预算。哪项判断准确？',[
'不能；TAS只限制相对结算价差，并未约束105的绝对上限|当前普通报价不是已固定的未来结算基准，若必须限制绝对支付须使用能约束该价格的有效安排。',
'能；下TAS单时100的普通报价已固定其基准，最高只会付100.1|题设基准是尚未确定的当日结算价，不是发单时普通盘口价格。',
'能；成交时当前报价低于105即可，后来结算只影响盈亏不影响买入价|普通期货成交价与TAS机制不同，TAS的绝对买入价正要等待结算基准确定。',
'不能；但把TAS加点从0.1改为0，就能同时消除超过105的风险|零加点仅让成交价等于未来结算价，该未知基准本身仍可高于105。']);
section('futures1',2,'futures1-2','expansionDerivSMP','FAQ第2问：题设采用取消原挂单并继续处理新单的模式，排除隐含订单');
q('自成交保护取消原挂单后新单仍可能对外成交','题设账户原无持仓，自己的卖开5手挂在100，第三方卖开5手挂在101；该账户又报买开5手限价101。SMP模式为遇同ID先撤原挂单、继续处理新单，全部为直接订单且无其他变化。结果是什么？',[
'自有100卖单被撤，买单可与第三方101成交5手，账户形成5手多头|防止自成交不等于取消所有后续交易，新买单仍有有效数量和足够限价跨到外部卖盘。',
'自有买卖单在100相抵成交，账户仍无持仓且成交量增加5手|这正是题设SMP阻止的自匹配，不能把撤单处理记成实际成交。',
'新买单被取消，自有100卖单保留，账户等待外部买家|这是取消入单模式的处理，和题设选择的取消原挂单相反。',
'两张自有订单一并取消，第三方101卖盘完全不会被访问|题设要求继续处理新单，不能自行扩展成双撤或停止后续撮合。']);
section('futures1',7,'futures1-7','expansionDerivDeliveryOptions','PDF第11–12页The Delivery Tail：CF/DV01配比与每手实物面额是一对不同约束');
q('风险对冲数量不等于交割时现券数量全部匹配','题设持有面值1000万元CTD债券，按转换因子0.8配置空头80手期货实现当前DV01近似对冲；每手实际交付面值10万元。若80手全部交割且不另交易，会留下什么？',[
'交付800万元面值，仍留下200万元尚未交付的现券|风险配比采用转换因子，实物交割却按每手固定面额一对一；原DV01中性不代表交割后零持仓，尾差需另行管理。',
'交付1000万元面值，不留现券，因为建仓时DV01已对消|敏感度匹配与实物数量匹配不同，80手只能交付800万元面值。',
'交付1250万元面值，需另购250万元以满足0.8因子调整|转换因子不把每手实物面额放大；应以80手乘每手10万元核对。',
'交付800万元后，剩余200万元仍由已完成交割的期货对冲|已完成交割的期货不再提供原先持续的价格对冲，剩余现券风险不能继续挂在已终结合约上。'],calc('1000-80*10',200,'万元交割后剩余债券面值'));
section('futures1',7,'futures1-7','expansionDerivDeliveryOptions','PDF第8–9页Wild Card：当日申报的发票金额固定，现金券仍可变；不将局部交付差额当全程利润');
q('定价后申报窗口赋予交割卖方时间选择','题设国债期货空头可在14时发票金额确定后、16时前决定是否申报当日交割；本日每单位发票金额固定100。可购入交付的债券由14时99.8降到15时99.2，忽略费用。这个安排带来什么特征？',[
'卖方可依据新的现金券成本相对已固定发票决定申报，体现交割时间选择权|15时购券并交付的局部差额为0.8，固定发票与仍变的现券形成选择机会；全程收益还需计入原期货现金流。',
'债券跌至99.2会自动把本日已固定发票同幅下调，选择时点没有作用|题设明确本日发票金额固定，不能把之后现金券变化再同步回写到发票。',
'交割买方拥有是否接受此时交割的同等拒绝权，所以卖方不能利用窗口|题设将申报选择授予合约空头，不能自行给被指派多头新增拒收权。',
'只要15时差额为0.8，就证明整笔期货从开仓起累计必赚0.8|这是当前购券交付两项的局部差额，原期货开仓及逐日结算损益并未给定。'],calc('100-99.2',.8,'每单位当前购券交付局部差额'));
section('futures1',3,'futures1-3','expansionDerivPriceControls','What are price limits及What is price banding：单笔订单拒绝与全市场价格限幅是不同检查');
q('每日涨跌限内订单仍可能触及动态价格带','题设某市场日内允许区间90至110，当前动态报单价格带99至103；超过动态带的订单直接拒绝，不触发全市场停牌。交易员报买入限价106且收到价格带拒单，正确处理认识是？',[
'应记该单被拒；106在日限内也不能通过99至103动态带|两个控制层检查不同边界，应读取拒单和市场状态，不能只用每日涨停价判断订单是否可受理。',
'应记已进入队列；日上限110优先于动态带，106仍是有效挂价|每日限幅通过不替代动态带检查，已收到拒单的订单不能当作有效排队数量。',
'应记全市场停牌；价格带拒单与触发全市场中断属于同一状态|题设明确这是单笔拒绝机制，不等于全市场中断或全天停牌。',
'应改报103并认定必能成交；带内可以受理就代表已找到对手|即使按当前带内价格重新受理，也仍取决于相反报价和数量，受理不能代替真实成交回报。']);

