section('futures1',4,'futures1-4','expansionDerivFarmHedge','PDF第3页Rh现金流及第5–6页随机产量价格负相关；原创两状态收入稳定问题');
q('自然对冲下不能按平均产量机械卖期货','农户收获时只有两种可能：120吨按80元/吨出售，或90吨按120元/吨出售；期货到时价格等于现货。现在可按100元/吨卖出任意吨数h，全部现金平仓，忽略费用和资金时点。为使两情景的销售收入加期货损益完全相同，应卖出多少吨？',[
'30吨|两情景合计分别9600+20h和10800−20h；令其相等得h=30，均为10200，产量与价格的自然对冲已降低待套保风险。',
'105吨|这是两种产量的算术平均，但直接套平均数量后两情景分别11700和8700，不能稳定总收入。',
'90吨|用最低可能产量只控制数量超卖的一个边界，不等于本题让两情景收入相同的解。',
'120吨|按最高产量卖出会在减产高价情景承担过多期货亏损，没有保留原产量价格反向变动的自然缓冲。'],calc('(90*120-120*80)/(120-80)',30,'吨收入稳定套保量'));
section('futures1',9,'futures1-9','expansionDerivWeather','第2页天气合约以指数决定现金结算；原创指数支付与企业实际损失的配对情景');
q('指数天气支付不以企业损失证明为计量上限','题设一份天气衍生合约仅按100×max(100−最终采暖指数,0)元支付，无实际损失证明或赔款上限条款。情景甲指数90但企业经营无损失，情景乙指数110但企业因其他原因损失1000元。两情景合同支付怎样记录？',[
'甲付1000元，乙付0元|支付只按明示指数公式，经营损失并非本合约触发条件；因此可能无损也收款、有损却不收款。',
'甲付0元，乙付1000元|这是按实际损失补偿的逻辑，擅自把合同没有约定的损失证明和赔付依据加入指数公式。',
'甲付1000元，乙付1000元|甲满足指数触发，但乙指数110使公式为零，实际损失不能另行创造本合约支付。',
'甲付0元，乙付0元|乙支付为零正确，但甲无经营损失不取消已经按指数产生的1000元合同收款权。'],calc('100*Math.max(100-90,0)',1000,'元情景甲的指数支付'));
section('futures1',9,'futures1-9','expansionDerivVarianceUnits','第25行以波动率偏导把Vega转换为方差单位；支付函数与波动点单位均由题设完整给出');
q('方差名义量与Vega名义量不能混乘','教学方差互换多头到期支付a×(σ²−20²)元，σ用波动点表示，例如25代表25%。合同在σ=20处每增加1个波动点的局部敏感度为10000元，因此2×a×20=10000。最终σ=25，准确支付是多少？',[
'56250元|先由局部敏感度解得a=250元/方差点，再算250×(625−400)=56250；10000不是可直接乘方差差的系数。',
'50000元|10000×5只是基于初始波动点敏感度的线性近似，遗漏方差支付中的二次项6250。',
'2250000元|把Vega名义量10000误当方差系数a并乘225，混淆了对波动点的敏感度与每方差点支付。',
'6250元|250×(25−20)²只计二次增量，遗漏初始波动点敏感度产生的线性支付50000。'],calc('(10000/(2*20))*(25**2-20**2)',56250,'元方差互换准确支付'));
section('futures1',9,'futures1-9','expansionDerivVolProducts','PDF第6页表4：方差互换以E[σ²]、波动率互换以E[σ]确定零初值执行值；概率与零利率均为题设');
q('方差执行值开平方不等于波动率互换公允执行值','在题设风险中性模型下，到期已实现波动率只有10或30个波动点，两者各半，利率为零。甲互换支付σ²−K甲，乙互换支付σ−K乙，均要求初始价值为零。正确的执行值配对是什么？',[
'K甲=500，K乙=20|应分别令期望支付为零；方差期望为(100+900)/2=500，波动率期望为(10+30)/2=20。',
'K甲=500，K乙约22.36|22.36是平均方差的平方根，不是波动率的平均数，代入乙会使其期望支付为负而非零。',
'K甲=400，K乙=20|400是平均波动率20再平方，遗漏波动率自身的不确定性，甲的期望支付会为正100。',
'K甲=400，K乙约22.36|两项分别把平方与期望、平方根与期望交换顺序，均不能使给定互换的期望支付归零。'],calc('(10**2+30**2)/2',500,'方差点的甲公允执行值'));
section('options',3,'payoffs','expansionDerivVolProducts','PDF第7页表4 Forward Starting Option (ATM)：未来起始日重设基准，按该日之后收益率支付；不使用近似定价式');
q('远期起始认购按未来重设价衡量涨幅','题设远期起始平值认购今天签约，三个月后按当时股价S1重设平值基准，六个月末支付1000×max(S2/S1−1,0)元。今日股价100，重设日80，到期96，忽略费用。到期支付多少？',[
'200元|未来起始基准为80，之后涨幅96/80−1=20%，乘合同金额1000得200；今日100不是这份期权的固定执行价。',
'0元|用今日100当固定执行价会把96判断为虚值，遗漏合同约定三个月后按S1重新确定基准。',
'160元|把80至96的价差16除以今日100得16%，混用了未来起始价差和签约日分母。',
'16000元|把16元绝对股价差直接乘1000，未按题设收益率支付除以未来起始价80。'],calc('1000*Math.max(96/80-1,0)',200,'元未来起始认购支付'));

