section('options',1,'contracts','expansionDerivSSEGuide2026','第九章第四节第1、4项：合并申报的认沽执行价高于认购执行价，无须两份合约同时实值');
q('合并行权检查不要求两腿同时实值','按上交所2026指南，一名客户持有同一ETF、同单位、当日到期的认购与认沽权利仓各一张。认购行权价3元，认沽3.2元，ETF现价3.4元；其余业务条件均满足。仅审查这组价格是否满足行权指令合并申报条件，正确判断是什么？',[
'满足，认沽行权价高于认购行权价|合并申报检查执行价的先后关系；3.2大于3，认沽当前虚值并不单独使此项条件失败。',
'不满足，认沽必须同时处于实值|规则未把两腿同时实值列为此项条件，不能额外用现价位于两执行价之间作为准入门槛。',
'不满足，认购行权价应高于认沽|该判断把合并行权的执行价条件反转，认沽执行价高于认购才符合这里的要求。',
'满足，只要两份合约行权价不相同|执行价不同还不足以通过检查，必须认沽高于认购；若顺序相反，即使不同也不满足这一条件。']);
section('options',1,'contracts','expansionDerivSSEGuide2026','第九章第四节第1、4项：同标的同单位，每一申报单位为认购和认沽各一张');
q('合并行权不能以总份数相等替代相同合约单位','客户持有同ETF、同日到期的调整认购，每张单位12000份；另一认沽每张10000份。两执行价顺序符合要求。他想把5张认购与6张认沽作为一组上交所行权指令合并申报，因为两边均为60000份。应怎样处理？',[
'不能这样合并，须同时满足等单位和逐张配对|每个合并申报单位是一张认购加一张认沽，且两份合约单位相等；总份数相等不能改变该接口条件。',
'可以这样合并，只需两边标的总份数一致|该做法以经济交付量替代合约单位及一比一配对条件，不符合行权指令合并申报要求。',
'可以先按五组申报，再自动补一张认沽|系统没有以不等单位组合后自动补足单腿的配对规则，剩余一张也不能修复已错配的单位。',
'可以把认购申报单位临时改为10000份|合约单位是正式合约条款，客户不能在行权指令中自行改写以使调整合约变成标准合约。']);
section('options',1,'contracts','expansionDerivSSEGuide2026','第九章第四节第1、2项：组合解除后的净头寸及累计申报，超量部分无效');
q('合并申报超量按剩余净权利仓识别有效部分','上交所行权日，同一账户组合解除后，某认购有权利仓7张、义务仓3张，相应认沽有权利仓9张、义务仓2张。两合约符合合并条件，无其他占用。客户先有效合并申报2组，再申报5组且未撤单。第二笔有几组有效？',[
'2组|认购净权利仓4张、认沽7张，最多可配4组；首笔已占2组，第二笔仅剩2组有效。',
'0组|合并行权超量申报仅超出可用净头寸的部分无效，并非直接套用超量平仓整笔无效规则。',
'4组|4组是未扣首笔已有效申报前的总配对容量，第二笔不能重复占用首笔的2组净权利仓。',
'5组|只看7张认购及9张认沽毛权利仓会漏掉义务仓对冲与先前申报，导致重复使用可行权合约。'],calc('Math.min(7-3,9-2)-2',2,'组第二笔有效合并申报'));
section('options',1,'contracts','expansionDerivSSEGuide2026','第九章第四节第5项：中国结算先处理合并申报，再检查普通行权可用数量');
q('异常重复行权数据按合并申报优先处理','清算复核发现异常输入：同一账户认购与认沽可用净权利仓各5张，收到合并申报4组，以及此前提交的该认购普通行权3张。假设除重复数量外均合格，前端本应拦截重复占用。按上交所2026指南，日终先采取哪种处理顺序？',[
'先处理合并4组，再按剩余认购检查普通申报|中国结算先处理有效合并行权，再按剩余可用权利仓核验非合并行权，不能让同一张合约行权两次。',
'先处理较早普通3张，再截减合并申报数量|该顺序把提交时间优先误套到两类行权的日终校验，指南明确先处理合并申报数据。',
'先各自核验两类申报，合格后再合计为7张|分别看每笔不超过5张仍会合计使用7张认购，无法解决相同净权利仓被重复申报的问题。',
'先撤掉全部普通申报，不再检查剩余认购|合并优先不等于普通申报一律撤销，处理合并后仍须按剩余可用数量进行有效性检查。']);
section('options',1,'contracts','expansionDerivSSERules','第108条末款：实际行权日之前接受的申报无效');
q('特殊顺延后原行权申报须重新管理','原定行权日客户已提交行权指令，随后上交所因规则规定的特殊情形公告将最后交易日、到期日及行权日顺延。客户在新的实际行权日仍希望行权。对原指令应怎样处理？',[
'原指令按无效处理，按新行权日重新办理|规则明确实际行权日前接受的申报按无效处理；顺延改变有效行权日，原回执不替代新日申报。',
'原指令自动滚动，只有新增数量需要办理|特殊顺延不采用原申报自动滚动机制，若只办理新增数量，原本想行权的头寸可能没有有效指令。',
'原指令永久保留，仅把现金交收日后移|本题不只是交收日期移动，最后交易日、到期日和行权日均变更，旧日申报效力也按规则处理。',
'原指令仍先执行，新日申报只能用剩余仓|实际行权日之前的申报无效，不能先用其占用权利仓，再据此限制新行权日的正常申报。']);
section('options',1,'contracts','expansionDerivSSERules','第112条：ETF行权现金结算价=前一交易日单位净值×(1+对应指数当日涨跌幅)');
q('ETF特殊现金结算使用净值与指数而非旧成交价','某沪市ETF期权已符合规则规定的特殊现金结算情形。ETF前一交易日单位净值4元、前一交易日收盘成交价4.10元，对应指数当日下跌2%。忽略舍入，按第112条计算的标的行权现金结算价格是多少？',[
'3.92元|规则以单位净值4元为基数乘1−2%，得3.92元；不是用含折溢价的前收盘成交价作基数。',
'4.018元|该值为4.10乘98%，错误地将前收盘成交价替代前一交易日单位净值。',
'4.08元|该值为4乘102%，把对应指数的跌幅当作涨幅，方向与题给市场变动相反。',
'4.10元|直接沿用旧收盘成交价既漏掉净值基数，也漏掉指数当日变动，不符合特殊结算公式。'],calc('4*(1-0.02)',3.92,'元ETF行权现金结算价格'));
section('options',1,'contracts','expansionDerivSSERules','第110条第2项：交收日标的停牌至收盘时应交标的不足部分现金结算');
q('交收日停牌时区分实际可交付与不足部分','某沪市期权交收日，标的全天停牌，义务方应交10000份，实际可供交收8000份。不存在交易所对全量另作特殊安排的情况。仅按第110条关于不足部分的处理，如何划分交收？',[
'8000份证券交付，2000份按公布现金价处理|交收日停牌情形针对应交标的不足部分进行现金结算，不能把已经具备交付条件的8000份也当然改成现金。',
'10000份全部改用交易所公布现金价处理|题目排除了全量另作安排，条文中的不足部分范围是2000份，不是整笔10000份交收义务。',
'8000份证券交付，2000份等复牌才履行|停牌至收盘时不足部分适用现金结算处理，不能自行把该部分延到未来不确定的复牌日。',
'8000份证券交付，2000份按期权权利金处理|应交标的缺口按适用的标的行权现金结算价处理，期权权利金不是替代交付证券的计价基础。']);
section('options',2,'covered-protective','expansionDerivSSERules','第48、51条：当日买入证券可锁定，但解锁不消除原卖出限制');
q('备兑锁定解锁不重置现货买入日期','客户今日买入一只不实行日内回转交易的沪市合约标的，随后将其备兑锁定；未开出认购便成功解除锁定。他认为解锁后的证券是“返还证券”，今天即可卖出。正确判断是什么？',[
'仍受当日买入限制，锁定解锁没有改变买入日|当日买入可以备兑锁定，但当日再解锁不因此取得卖出资格；锁定只是用途状态变更，不是新的证券来源。',
'可以卖出，解锁回执已替代原买入记录|解锁回执只说明备兑限制解除，不会消除现货自身的当日买入卖出限制。',
'可以卖出，未实际开出认购就不受限制|是否实际建立备兑义务并不改变现货买入日期；即使没有开仓，日内回转限制仍然适用。',
'不能卖出，因为解锁后仍保留原备兑冻结|成功解除锁定已移除备兑用途冻结；本题当日不能卖出的原因是现货买入日期限制，不能把两个状态混为一谈。']);
section('options',2,'covered-protective','expansionDerivSSEGuide2026','第八章第二节：除权除息日在途配股送股可计入已有备兑足额判断，不能用于备兑新开仓');
q('在途送股补已有备兑不等于可以新开仓','某除权日，客户已有备兑持仓按调整后单位需12000份，已到位备用证券10000份，另有尚未上市流通的应到账送股2000份，合计恰好足额。他又想用这2000份在途数量新做备兑。正确判断是什么？',[
'原备兑可视为足额，在途数量不能用于新备兑|指南允许相应在途配股送股用于已有备兑持仓的足额判断，却不允许把尚未上市流通数量用于备兑新开仓。',
'原备兑仍欠2000份，新备兑也不可使用在途|后一判断正确，但前者忽略除权除息日已有备用证券与对应在途数量合并足额的特定处理。',
'原备兑可视为足额，新备兑也能再用这2000份|在途数量既受不得新开仓的限制，也已用于支持已有持仓，不能再次作为新增备兑担保。',
'原备兑应减到10000份，新备兑可用在途数量|不能自行把调整后既有交付义务减回10000份，也不能把在途股票转作备兑新开仓证券。']);
section('options',2,'covered-protective','expansionDerivSSERules','第113条；2026指南第七章其他原因导致备兑不足：现有备兑证券用于到期行权交付');
q('到期交收可引发另一未到期备兑的缺券','同一账户今天应交付某ETF10000份，非备兑可交付证券仅6000份；另有该ETF10000份正用于担保下月到期的备兑认购。按沪市规则，相应备兑证券被用于弥补今天缺口后，客户应重点处理什么？',[
'下月备兑形成4000份缺口，须按时补券或处置|备兑证券可以被用于当日行权交付，今天缺4000份会消耗下月担保证券；未到期义务仍在，必须处理新的备兑不足。',
'下月备兑仍足额，因为只检查开仓时的锁定数|备兑足额是持续的证券担保要求，交收消耗后不能仅凭开仓时曾经锁定足额就忽略缺口。',
'下月义务自动减少四成，与剩余担保数量一致|担保证券被动减少不会按比例注销期权义务，持仓数量与备兑证券数量必须分别维护。',
'今天仍欠4000份，因为未到期备兑证券不可动|沪市规则明确该类不足时相应备兑证券用于当日交割，因此不能把其视为绝对隔离而忽略后续备兑不足。']);
section('options',4,'risk','expansionDerivSSEGuide2026','第十一章第一节：日终双向对冲优先非备兑义务仓，组合策略持仓除外');
q('自动对冲优先消耗保证金义务仓','沪市同一账户同一认购日终有普通权利仓4张、保证金义务仓3张、备兑义务仓5张，均非组合策略持仓，无其他变动。按日终对冲顺序，最后应留下哪种头寸？',[
'4张备兑义务仓，无保证金义务仓|4张权利仓先对冲3张非备兑义务仓，再对冲1张备兑义务仓，所以剩余4张均为备兑义务仓。',
'3张保证金义务仓、1张备兑义务仓|这对应优先冲减备兑义务仓的错误顺序，与规则优先对冲非备兑义务仓的安排相反。',
'1张权利仓、5张备兑义务仓|先冲减3张保证金义务仓后，还剩1张权利仓可继续对冲备兑义务仓，不能在第一步后停止。',
'4张保证金义务仓，无备兑义务仓|对冲不会将剩余备兑义务仓自动转成保证金义务仓，净张数相同也不代表担保类型可以改写。']);
q('尚未解除的组合成分不参与普通日终对冲','客户已有正式锁定的认购牛市价差组合，其中低行权价认购权利仓1张；当日又独立卖出开仓该低行权价认购1张。该组合今天未到自动解除日，也未主动解除。能否日终把组合内权利仓与新义务仓直接对冲掉？',[
'不能直接对冲，已锁定组合成分应保留在组合内|普通日终双向持仓对冲排除仍在组合中的持仓，不能因出现同合约反向普通仓就自动破坏已经锁定的组合结构。',
'可以直接对冲，因为同一合约只允许单向持仓|普通净额规则有组合策略持仓例外，同合约存在反向普通头寸不使组合成分当然失去锁定状态。',
'可以直接对冲，组合中的另一腿自动移到普通仓|这相当于未经解除流程拆散组合，日终普通对冲不会自行执行该项组合变更。',
'不能对冲，但新义务仓也自动享有组合减免|不能对冲并不意味着新义务仓取得组合身份，独立新开仓的保证金仍应按其适用规则核算。']);
section('options',4,'risk','expansionDerivSSECombo','第7条：同笔构建无法满足全部组合要求时整笔无效');
q('组合构建不足采用整笔无效而非部分构建','客户准备正式构建4组同一种价差组合，可用的两腿成分合约分别只有4张与3张，均未锁定且其他条件满足。他提交一笔4组构建申报。按上交所组合策略指引，这笔申报如何处理？',[
'整笔无效，调整数量后再申请构建|同笔构建的成分合约不能满足全部数量时整笔无效，不采用合并行权超量部分无效的处理模式。',
'先构建3组，余下1组等待补足成分|组合构建指令不是可部分成交的交易挂单，数量不足不能先建立部分组合再让剩余部分排队。',
'先构建3组，余下1组自动取消即可|该说法套用了部分执行剩余撤销模式，而组合构建数量不足的明确结果是整笔无效。',
'先构建4组，再要求客户补买短缺1张|构建必须以现有足额可用成分为前提，不能先确认不存在完整成分的一组再追补合约。']);
section('options',4,'risk','expansionDerivSSECombo','第5、15条：价差E-2自动解除，空头跨式E日解除；解除后当月不得重构');
q('不同组合自动解除日不能统一设为到期日','假设周一、周二、周三均为沪市正常交易日，所有合约周三到期，无特别公告。客户持有已登记的认购牛市价差和跨式空头。周二开盘检查组合状态及重构权限，哪项正确？',[
'价差已解除且不能重构当月组合，跨式尚存续|四类价差于E−2即周一日终自动解除，解除后当月到期合约不能重构；空头跨式一般至E日日终才解除。',
'两者都仍存续，因自动解除统一在周三日终|该判断把空头跨式的解除日推广到价差，遗漏价差在到期日前第二个交易日自动解除的安排。',
'两者都已解除，但都能在周二重新申报构建|跨式尚未到其自动解除日，而且自动解除后的当月到期合约一般也不得重新构建组合。',
'价差已解除但可立即重构，跨式尚在存续中|前半只识别自动解除时点，却漏掉解除后当月合约不得再用于构建组合的后续限制。']);
section('options',4,'risk','expansionDerivSSECombo','第4条第5项：两腿维持保证金相等时附加结算价取较大值');
q('跨式组合两腿保证金相等时的附加权利金','某沪市已登记跨式空头一组，两腿各自维持保证金均为5000元，认购结算价0.18元、认沽0.12元，单位均10000份。假定适用指引第4条标准且无上浮，组合维持保证金应为多少？',[
'6800元|两腿维持保证金相等时，附加项取较高结算价0.18乘10000；5000+1800=6800元。',
'6200元|该值取了较低结算价0.12，但保证金相等的特殊分支要求使用两结算价中的较大值。',
'5000元|仅取两腿保证金最大值遗漏应附加的权利金结算价金额，不能完整反映指引公式。',
'10000元|直接相加两腿单独保证金没有应用正式组合策略标准，也没有处理相等时的附加价选择。'],calc('5000+Math.max(0.18,0.12)*10000',6800,'元组合维持保证金'));
section('options',4,'risk','expansionDerivSSECombo','第14条：成分停牌可构建解除，暂时停止交易或临时停市除外');
q('成分停牌与临时停市的组合非交易指令边界','风控员准备在允许申报时段解除已登记期权组合。甲情形只是该成分合约停牌，市场未临时停市；乙情形交易所正对该市场临时停市。保证金等其他条件足额。按组合指引，哪项区分正确？',[
'甲仍可接受解除申报，乙不适用该停牌受理安排|第14条允许成分合约停牌期间构建、解除组合，但明确排除暂时停止交易或临时停市，需区分业务状态。',
'甲乙都不能受理，因为解除等同竞价平仓成交|解除组合属于持仓组合状态调整，不等同卖出或买入成交；成分停牌不当然停止这种申报。',
'甲乙都必须受理，因为非交易指令不受停市影响|非交易性质不意味着任何市场状态都可受理，条文明确对暂时停止交易或临时停市作出例外。',
'甲不能受理，乙可受理以优先降低市场风险|该处理反转了规则的许可与例外，风险降低的主观目的不能自行扩展停市期间的受理范围。']);
section('options',4,'risk','expansionDerivSSEOne','风险管理：单边平仓暂不实施；组合指引发布通知第17–19条暂缓');
q('规则附件列有功能不等于当前已开放该功能','截至2026年10月14日，客户读到沪市组合策略指引附件第17–19条写有“单边平仓”，想在不先解除组合的情况下调用该专用指令。官网办理页仍标明该功能暂不实施。应怎样安排操作？',[
'按尚未开放处理，核实可用解除与平仓流程|功能条文与实施状态应共同读取，暂不实施时不能仅因附件描述了接口就假设该专用指令已可用。',
'按已经开放处理，附件有计算公式即可下单|公式说明可能是待实施功能的设计，不能覆盖发布通知及当前办理页明确列出的暂不实施状态。',
'按客户授权开放，由券商自行启用交易所接口|客户授权不能使交易所尚未实施的专用功能生效，仍应使用已开放且经核实的业务路径。',
'按风控额度开放，只要增加保证金就可调用|足额资金是业务条件之一，却不替代功能本身的实施状态，额外保证金不能使未开放接口变得有效。']);
section('options',1,'lifecycle','expansionDerivSSERules','第14条：已调整合约日终持仓为零则下一交易日摘牌；不涉及普通未调整合约');
q('调整合约零持仓会改变下一交易日可交易清单','某沪市ETF期权因除息已调整合约单位及行权价，距到期尚有两周，但今天全市场该调整合约日终持仓已归零。交易系统仍拟把它列入明天可新开仓的候选清单，理由是尚未到期。按第14条应怎样修正？',[
'将该调整合约移出明日清单，按规则次日摘牌|已调整合约日终持仓为零时下一交易日摘牌；尚有剩余期限不使该零持仓调整合约继续挂牌。',
'保留到原到期日，只在今天成交量也为零时删除|条文看的是调整合约的日终持仓数量，不附加当日成交量为零条件，也无需等到原定到期日。',
'把同ETF所有标准和调整合约同时移出清单|某份调整合约满足零持仓摘牌条件，不意味着该ETF整个合约品种或其他仍符合挂牌条件的合约一并摘牌。',
'恢复该合约除息前条款后继续沿用原代码交易|零持仓触发摘牌，不是撤销此前有效的除息调整；不能自行恢复旧单位和旧行权价继续使用同一合约。']);
section('options',4,'risk','expansionDerivSSEGuide2026','第五章第一节（三）第2、4项：额度调整造成超限与违规开仓超限的不同处置');
q('限额下调形成的存量超限区别违规开仓','按上交所2026指南，甲客户原持仓合法，交易所限额调整后持仓超过新限额；乙客户则因券商前端控制失效，在既定限额下违规开仓而超限。两者均无其他风险事件。券商不能把哪种处理一概套用到两人？',[
'不能都按违规超限强平，甲应先按新限额限制开仓|仅因交易所限额调整导致的存量超限，指南不要求自行平仓或强平；前端失效导致违规超限则应及时处置超额持仓。',
'不能限制甲的新开仓，原核定限额应持续有效|甲原持仓的保留不等于旧限额永久有效，新开仓仍应按已经调整后的持仓限额控制。',
'不能要求乙减持，既已成交就只限制以后开仓|乙因前端失效发生违规超额开仓，不属于限额事后调整的存量例外，不能只阻止未来开仓而放任超额。',
'不能区别两人，超限来源不影响平仓处置要求|指南明确区分限额调整导致的超限与违反既定规则造成的超限，来源正是选择处置路径的重要条件。']);
section('options',4,'risk','expansionDerivSSEGuide2026','第五章第一节（二）：单日买入开仓累计额度，平仓不计增可买入开仓额度');
q('日内平仓不恢复当日买入开仓额度','某沪市期权客户当日买入开仓限额按题设为100张。他已买入开仓70张并全部成交，其中50张又卖出平仓；无未成交开仓单，其他持仓及资金限制均足额。今天还可新增买入开仓多少张？',[
'30张|单日买入开仓限额统计当日累计开仓，已成交70张仍计入；卖出平仓50张只降存量，不恢复当日开仓额度。',
'80张|该值用100减当前剩余20张，错误地把单日累计买入开仓限额当成当前权利仓持仓限额。',
'100张|卖出平仓不撤销已发生的买入开仓记录，不能因日内曾减仓就将累计计数清零。',
'50张|已经卖出的50张是存量减少数量，不是可用开仓额度；应从单日限额扣除累计已开仓70张。'],calc('100-70',30,'张当日剩余买入开仓额度'));
section('options',4,'risk','expansionDerivSSEGuide2026','第五章第二节（一）：限购前端参考算法按持仓成本和已申报未成交金额占用');
q('期权限购占用不能因市场跌价自动释放','按沪市2026指南的限购前端参考算法，客户核定买入额度10万元。已有权利仓持仓成本6万元，当前市值降到3万元；另有已申报未成交买入开仓金额2万元，未撤单。新买入开仓3万元能否通过该项额度检查？',[
'不能，占用按成本和待成交金额合计11万元|参考算法以现有权利仓持仓成本6万加未成交2万再加新单3万核验，市值下跌不会自动把原成本占用降到3万。',
'能够，按当前市值计算总占用只有8万元|该值用市值3万替代持仓成本6万，混淆风险估值与限购参考算法的占用口径。',
'能够，只把已有持仓成本与新单相加得9万元|该值漏掉已申报未成交但尚未撤销的2万元开仓承诺，可能让同时成交的订单突破额度。',
'不能，已有持仓成本与市值应合并占用14万元|持仓成本与该持仓当前市值是同一头寸的不同计量，不应重复相加；正确占用是11万而非14万。'],calc('6+2+3',11,'万元限购算法总占用'));
section('options',1,'contracts','expansionDerivSSEGuide2026','第十章第二节：客户自设策略优于券商默认，行权日手动委托优于协议行权委托');
q('协议行权默认策略与客户设置的优先级','沪市客户已认可券商默认的协议行权策略，之后又自行设置某合约的专用策略；行权日他还主动提交该合约手动行权委托。系统设计者把三个来源都当独立指令相加。正确的处理原则是什么？',[
'按手动、客户自设、券商默认的适用优先级处理|指南规定手动委托优于协议委托，客户自设策略优于券商默认；不能把不同层级对同一持仓的意图盲目累加。',
'按券商默认、客户自设、手动的先后顺序处理|默认策略只是客户认可的兜底安排，不因更早存在就覆盖后续客户专用策略和当日手动意图。',
'按触发所得数量最大者处理，优先完成更多行权|数量最大不是指南规定的冲突解决标准，扩大执行数量可能偏离客户后来提交的明确行权意图。',
'按三个来源分别累加，最后只做合约数量截断|数量截断不能替代指令优先级控制，盲目累加仍可能让较低优先级策略改变高优先级委托的执行结果。']);
